insert into public.chunks (id, episode_id, cms_item_id, chunk_index, content, token_estimate, speakers, start_timestamp, end_timestamp, podcast_index, episode_name, slug, web_url, guest_name, guest_title, categories, short_description, podcast_length)
select id, episode_id, cms_item_id, chunk_index, content, token_estimate, speakers, start_timestamp, end_timestamp, podcast_index, episode_name, slug, web_url, guest_name, guest_title, categories, short_description, podcast_length
from jsonb_to_recordset($jsonpayload$
[{"id": "bc89cb7e-cd0a-4a2b-b7b0-7cf5253bf4d6", "episode_id": "75f56310-05dd-4251-93ca-e178ecafde6d", "cms_item_id": "68225dfc7bb476527f8c48a8", "chunk_index": 1, "content": "John Peabody (00:02:07): Well, yeah, I've been here in New York, 10 plus years, 11 years. I sort of stopped counting Gear Patrol was in New York during the pandemic, they disbanded, the office went fully remote.\n\nCole Heilborn (00:02:23): We've had a few guests on the show who have been based out of New York, and I love it when there's an outdoor company based in New York because it seems like this super neat hybrid of meshing of cultures and the people are always super fascinating. And so it seems like a really, really unique place to work from.\n\nJohn Peabody (00:02:42): Well, it is, and I mean, if you don't live here or you're not from New York, you probably get the sense that New York is Manhattan and this skyscrapers and busy and crazy and grinding and all that kind of stuff, and it is that, but it's also a lot of other things. It's like Brooklyn and it's trees and parks, and it's Rockaway Beach and Surf, and it's hikes nearby in New York. And accessibility to ski mountains not too far away and plenty of parks. So I am not going to say it's the best beach town in the world or the best mountain town in the world or anything like that. But we do have our fair share of outdoor activities. I sort of consider myself not a city person at all, even though I've been here for 10 years and I guess I am technically a New Yorker. I just don't even identify as one, weirdly.\n\nCole Heilborn (00:03:42): Well, I guess that makes sense, sort of. I'm curious to learn a little bit more about your job. So Gear Patrol, there's a division under Gear Patrol called Gear Patrol Studios. Could you explain a little bit about what the studio does and what your role as Director of Branded content, what that means?", "token_estimate": 430, "speakers": ["John Peabody", "Cole Heilborn"], "start_timestamp": "00:02:07", "end_timestamp": "00:03:42", "podcast_index": 133, "episode_name": "EP: 133 How to Beat the Attention Economy | John G Peabody | Gear Patrol", "slug": "ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "web_url": "https://www.portsidepro.com/podcast-feed/ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "guest_name": "John Peabody", "guest_title": null, "categories": ["brand"], "short_description": "Do you struggle to create content that really resonates with your audience? Are you frustrated by shorter attention spans? On this episode, Cole sits down with John Peabody to talk about how to beat the attention economy and create GOOD content that matters.", "podcast_length": "1:09"}, {"id": "aa493649-1c58-4cda-92ae-c28670e8ad42", "episode_id": "75f56310-05dd-4251-93ca-e178ecafde6d", "cms_item_id": "68225dfc7bb476527f8c48a8", "chunk_index": 2, "content": "John Peabody (00:04:00): Yeah, definitely. So Gear Patrol is obviously a media company. We do reviews, product journalism, reviews, lifestyle content, all sorts of stuff. And Gear Patrol Studios is our in-house branded content studio. So we create a ton of different partnership programs with various clients. Too many to name, but I could name a bunch. And we create content in partnership with various advertisers. I work really closely with our creative director, whose name is Joe Ky, who's really, really talented, and basically just see ideas from, or program ideas from ideation through completion basically.\n\nCole Heilborn (00:04:50): Gotcha. And what type of deliverables? What type content is the team producing?\n\nJohn Peabody (00:04:55): So yeah, that's a good question. I mean, everything from fairly turnkey, shorter articles a client could sponsor what is called today in Gear, which is our daily sort of wrap up of the day in Gear News all the way to sponsored video series. We've pitched podcasts recently. We haven't produced a sponsored podcast, but really anything that we can come up with, we will produce it.\n\nCole Heilborn (00:05:28): Gotcha. So how does that structure work? So a brand might come to Gear Patrol and say, we want to collaborate on this piece, and then is the studio built in a way so that you then automatically create those deliverables or are they a separate channel?\n\nJohn Peabody (00:05:46): Well, yeah, I guess what do you mean by separate channel? Let me clarify that.\n\nCole Heilborn (00:05:50): Yeah, so how do you work with the Gear Patrol umbrella above you, and then how does that work in tandem with the brands that Gear Patrol is collaborating with?", "token_estimate": 425, "speakers": ["John Peabody", "Cole Heilborn"], "start_timestamp": "00:04:00", "end_timestamp": "00:05:50", "podcast_index": 133, "episode_name": "EP: 133 How to Beat the Attention Economy | John G Peabody | Gear Patrol", "slug": "ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "web_url": "https://www.portsidepro.com/podcast-feed/ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "guest_name": "John Peabody", "guest_title": null, "categories": ["brand"], "short_description": "Do you struggle to create content that really resonates with your audience? Are you frustrated by shorter attention spans? On this episode, Cole sits down with John Peabody to talk about how to beat the attention economy and create GOOD content that matters.", "podcast_length": "1:09"}, {"id": "7c7f7c76-7fa8-43c9-b16f-eab6eafd6da5", "episode_id": "75f56310-05dd-4251-93ca-e178ecafde6d", "cms_item_id": "68225dfc7bb476527f8c48a8", "chunk_index": 3, "content": "John Peabody (00:06:01): Yeah, okay, sure. So I mean, the way it generally happens, and it happens different ways, but brands will send work with our sales team and they'll give us an RFP or request for a proposal. And in that RFP, they'll tell us sort of what they're trying to achieve, what their budget is, what their timing is, et cetera. And it might be something like maybe their KPI is brand awareness or maybe their KPI is, they really want to sell this product and actually just convert people on this product. Whatever their KPI is, we'll kind of huddle the creative strategy team. And we have a dedicated creative strategist who I work with very closely, and we have a sort of a pre-sale brain trust or whatever that gets together and comes up with a strategy for this client. We want to convert people for this watch brand. (00:06:59): We want to drive people to this landing page and get people to buy this watch. What's the best way to do it? We'll come up with the plan that we think is the strongest at their budget level, put it in a proposal, deck it up, send it to the brand, pitch it to them, they love it, of course, and then they buy it. And then, yeah, we work with the production team to kind of make it happen. And then as far as how that works with the Greater Gear Patrol team, there's obviously, we have a ton of editors at Gear Patrol who are always producing content, and our content lives in the Gear Patrol ecosystem is clearly labeled sponsored content. We're not trying to deceive anyone that this is content that the editors created that's different, but it lives in the same ecosystem and is promoted in the same ecosystem is found next to the content that the editors created. (00:08:02): So it's very much, well, I have a sort of point of view on sponsored content that since it's sponsored, it has to be really good and it probably has to sometimes be better than even the content the editors are producing in order to get the attention and I don't know, get the attention from the audience that you're trying for. If it's worse or it doesn't feel like there was effort put into it, or it's just not produced well, then it's really, really easy to write it off as like, oh, that's just sponsored content, that's an ad that's branded content. So I dunno, I try and I think I speak for everyone at Gear Patrol Studios that when we produce something we're really trying to produce, that's even better than editorial if we can do it to make it stand out and win attention.", "token_estimate": 627, "speakers": ["John Peabody"], "start_timestamp": "00:06:01", "end_timestamp": "00:06:01", "podcast_index": 133, "episode_name": "EP: 133 How to Beat the Attention Economy | John G Peabody | Gear Patrol", "slug": "ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "web_url": "https://www.portsidepro.com/podcast-feed/ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "guest_name": "John Peabody", "guest_title": null, "categories": ["brand"], "short_description": "Do you struggle to create content that really resonates with your audience? Are you frustrated by shorter attention spans? On this episode, Cole sits down with John Peabody to talk about how to beat the attention economy and create GOOD content that matters.", "podcast_length": "1:09"}, {"id": "adff1fe5-3d95-4bde-9ec0-3d7390d7338a", "episode_id": "75f56310-05dd-4251-93ca-e178ecafde6d", "cms_item_id": "68225dfc7bb476527f8c48a8", "chunk_index": 4, "content": "Cole Heilborn (00:09:03): That makes sense, especially in today's age, anything that's sponsored content automatically loses a few points of credibility. So you have to overcome that by overachieving on the level of quality or the creative or the story behind it all in order to make up for that gap between user generated or editorial or sponsored content.\n\nJohn Peabody (00:09:26): Yeah, yeah, exactly. And I mean, one thing that's actually really great about that is because it's branded content, there's normally a budget associated with it that there might not be if the editor was producing, if an editor was producing that content. So what's the right word? I'm trying to think of luxury, of being able to work with a lot of creative partners, photographers, video makers, illustrators, to really plus up the content and make it look beautiful and make it feel premium, which is kind of one reason I love sponsored content and producing it. I came from a background in journalism, but I really enjoy the sponsored content world just because there is budget to do things really well.\n\nCole Heilborn (00:10:16): Yeah, really quick, let's just touch on your background. How did you end up with Gear", "token_estimate": 301, "speakers": ["Cole Heilborn", "John Peabody"], "start_timestamp": "00:09:03", "end_timestamp": "00:10:16", "podcast_index": 133, "episode_name": "EP: 133 How to Beat the Attention Economy | John G Peabody | Gear Patrol", "slug": "ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "web_url": "https://www.portsidepro.com/podcast-feed/ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "guest_name": "John Peabody", "guest_title": null, "categories": ["brand"], "short_description": "Do you struggle to create content that really resonates with your audience? Are you frustrated by shorter attention spans? On this episode, Cole sits down with John Peabody to talk about how to beat the attention economy and create GOOD content that matters.", "podcast_length": "1:09"}, {"id": "9c3a2f9d-3fb5-47f7-8fea-3c1c743dbb64", "episode_id": "75f56310-05dd-4251-93ca-e178ecafde6d", "cms_item_id": "68225dfc7bb476527f8c48a8", "chunk_index": 5, "content": "John Peabody (00:10:22): Patrol? Yeah, so I'm a journalist by trade, by training. Got my start working at newspapers a long time ago, sort of went to grad school for journalism after working at a newspaper, moved to New York to become a journalist in the big city, sort of swashbuckling reporter was my dream. Ended up working at Reuters, which is the biggest news agency in the world. One of, I don't know, 5,000 journalists there or something, was commuting into Times Square every day sitting in a cubicle. And to be honest, just wasn't my vision of what a career in journalism was or should be, or not what it was or should be, but just what I wanted. And I left Reuters kind of struck out on my own to be a freelancer, writer and editor. And while I was doing that, while I was freelancing, I started working for brands as well. (00:11:25): I had a blog and I was shooting some photos and naturally sort of just started doing some content work for brands. Huckberry was one of them that was really good to me, and I did some projects with them, did some work with Kaufman Mercantile, which was an old e-commerce brand. And eventually I just was sort of only working with brands, just more profitable than trying to be a freelance writer and kind of realized if I'm doing this full-time for brands, I should probably just go in-house somewhere and just work in branded content and get health insurance and stuff like that. And I got a job at the Atlantic doing creative strategy, which was amazing. And it was the first time I was kind of doing creative strategy, full-time pitching clients, coming up with ideas for branded content campaigns, selling them through, there's a lot of similar sort of muscles you use as a journalist or editor, but they're slightly different. (00:12:26): You're pitching someone with a commercial interest and you have to make sure things have commercial value and commercial appeal. And like I said before, you get budget to actually produce content. And I just really liked it, honestly. I liked how it was built off of storytelling, but slightly different. And anyway, I was at The Atlantic for a couple of years, went to Hokey the watch blog where I was kind of running branded content there as well, and then eventually was producing or running the photo and video teams left, I guess about a year ago and made my way to Gear Patrol earlier this year. And I've been in Gear Patrol for almost a year now, running Gear Patrol studios.", "token_estimate": 618, "speakers": ["John Peabody"], "start_timestamp": "00:10:22", "end_timestamp": "00:10:22", "podcast_index": 133, "episode_name": "EP: 133 How to Beat the Attention Economy | John G Peabody | Gear Patrol", "slug": "ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "web_url": "https://www.portsidepro.com/podcast-feed/ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "guest_name": "John Peabody", "guest_title": null, "categories": ["brand"], "short_description": "Do you struggle to create content that really resonates with your audience? Are you frustrated by shorter attention spans? On this episode, Cole sits down with John Peabody to talk about how to beat the attention economy and create GOOD content that matters.", "podcast_length": "1:09"}, {"id": "2e800243-fe71-4512-87bf-2eca9699143a", "episode_id": "75f56310-05dd-4251-93ca-e178ecafde6d", "cms_item_id": "68225dfc7bb476527f8c48a8", "chunk_index": 6, "content": "Cole Heilborn (00:13:20): Awesome. Congratulations.\n\nJohn Peabody (00:13:22): Thank you. I appreciate it. Yeah.\n\nCole Heilborn (00:13:25): So when we first connected, we started talking about the attention economy and how the attention economy is changing, maybe how it's not changing. And I'm curious just to kind of dive into your perspective on the attention economy. How would you describe it? How would you define it in today's world?\n\nJohn Peabody (00:13:44): Yeah, I mean this is a great question and such a big sort of topic to talk about. There's a couple things going on. I would say with the attention economy that are sort of contradictory and interesting and notable, et cetera. There's two major things I think are really interesting and sort of incongruent. One is the desire for short form content, which is happening. And we see TikTok is huge, right? And TikTok is so popular and the videos are very, very short and range from being highly produced to very amateurish. It almost doesn't matter. They're super engaging and I don't know about you, but when I open up TikTok, I'm like, all of a sudden 45 minutes is gone or an hour is gone and I've watched, I don't know, 20, 30 videos. So that's amazing and that's happening and that's very interesting to me. On the other end of the spectrum, there's very much a crazy demand for long form content and content that goes much deeper. (00:14:58): And I think you see that with obviously the insane explosion of podcasts over the last couple of years. Long form video on YouTube is super popular. I mean 30 minute, 40 minute, hour long videos on YouTube are super popular. And long form writing too is popular. Subscriptions are up at places like the New York Times, the Atlantic, the New Yorker, all these news outlets that do long form reporting. There's very much a desire for that content as well. So for a while people were kind of writing off long form content that the future is in social media and short form content and very snackable content and stuff like that. But that's just not true. That's just proven not true at all. People want that. But people also want to go very, very deep on things and love going deep on everything. So I mean, as an aside, I was talking to some people I worked with last night about paranormal podcasts. (00:16:12): This is not my world at all. This is not my interest. But there were three people who were obsessed about paranormal podcasts and we fired up the app or the phone. And there's dozens and dozens of long form podcasts all about paranormal activity. So no matter what you're interested in, there's tons of long form content where you can go crazy deep on it. So what does that say about the attention economy? I don't know. Does it say our attentions are sort of all over the place and range from short to long form? I guess. I mean, just think maybe the through line is just we have attention for something that's really interesting and it doesn't matter if that's short or long or medium or a podcast or a video or an article. If it's done well, if it's content that's created well and is interesting, people will consume it, people will find it and people will consume it voraciously. And I think that's kind of fascinating and something I think about all the time as a marketer.", "token_estimate": 826, "speakers": ["Cole Heilborn", "John Peabody"], "start_timestamp": "00:13:20", "end_timestamp": "00:13:44", "podcast_index": 133, "episode_name": "EP: 133 How to Beat the Attention Economy | John G Peabody | Gear Patrol", "slug": "ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "web_url": "https://www.portsidepro.com/podcast-feed/ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "guest_name": "John Peabody", "guest_title": null, "categories": ["brand"], "short_description": "Do you struggle to create content that really resonates with your audience? Are you frustrated by shorter attention spans? On this episode, Cole sits down with John Peabody to talk about how to beat the attention economy and create GOOD content that matters.", "podcast_length": "1:09"}, {"id": "935e77b0-ed97-45a0-b5da-c5440dcdbb53", "episode_id": "75f56310-05dd-4251-93ca-e178ecafde6d", "cms_item_id": "68225dfc7bb476527f8c48a8", "chunk_index": 7, "content": "Cole Heilborn (00:17:31): So I was trying to wrap my head around short form or long form, regardless how much content is being created out in the world. And I'm sure we've all read some stats about that, but I pulled a couple just to bounce off of you. So the first one is on average per day, people are exposed to about 6,000 to 10,000 advertisements second. That's\n\nJohn Peabody (00:17:55): Crazy. My just reaction is like, oh my God, I can't even believe that, but I believe it.\n\nCole Heilborn (00:18:01): I didn't believe that at first. But then as I was looking at the website that I was pulling this stat from, I realized that there was three popup ads all around me and they were cycling through every three seconds. And so I think in that moment I was exposed to about 15 ads in a span of 30 seconds, 60 seconds, which I just found really ironic. Second point was by 2025, it's estimated that 463 exabytes of data will be created each day. And I had to look up what an exabyte is. An exabyte is 1 billion gigabytes.\n\nJohn Peabody (00:18:35): I can't even fathom what that is. I just know it's a ton.\n\nCole Heilborn (00:18:40): I can wrap my head around a terabyte, 10 terabytes. But yeah, that's next level and that's every day. The last stat is currently in every 24 hour period, 1 billion hours of content on YouTube are watched.", "token_estimate": 335, "speakers": ["Cole Heilborn", "John Peabody"], "start_timestamp": "00:17:31", "end_timestamp": "00:18:40", "podcast_index": 133, "episode_name": "EP: 133 How to Beat the Attention Economy | John G Peabody | Gear Patrol", "slug": "ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "web_url": "https://www.portsidepro.com/podcast-feed/ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "guest_name": "John Peabody", "guest_title": null, "categories": ["brand"], "short_description": "Do you struggle to create content that really resonates with your audience? Are you frustrated by shorter attention spans? On this episode, Cole sits down with John Peabody to talk about how to beat the attention economy and create GOOD content that matters.", "podcast_length": "1:09"}, {"id": "88175611-f4eb-46b3-8829-d66e9a8e69e6", "episode_id": "75f56310-05dd-4251-93ca-e178ecafde6d", "cms_item_id": "68225dfc7bb476527f8c48a8", "chunk_index": 8, "content": "John Peabody (00:18:55): Crazy. I mean, yeah, those are mind boggling numbers to the point of you almost can't wrap your head around them. I don't know how you would, but also totally intuitive because anyone who has a phone knows that it's a constant just feed of information into your brain and is daunting. I don't know anyone who doesn't have a phone right now who doesn't have sort of a complicated love hate relationship with it. It's simultaneously great and totally draining at the same time, which I think content in general is in a lot of content is a advertising, and these devices are obviously heavily monetized. And I don't know, I guess that my initial reaction to all that is almost like that just makes me feel more committed and almost ownership of creating good content that actually stands out and doesn't just become one of 6,000 advertisements that you see in a day and totally forget about because you've been totally overwhelmed with images of products and travel locations and whatever. Yeah, we're in sort of a tower of Babel situation. There's just endless noise. That's part of the attention economy too, right? Yeah.\n\nCole Heilborn (00:20:34): So when you think about how to break through the noise, and you alluded to it earlier, you said, regardless if it's long form or short form, what we're seeing is people are consuming interesting content, whatever interesting is to someone. How do you think about breaking through the noise? How do you try to create something that is interesting so that it does stand out so you're not one of those 6,000 ads?", "token_estimate": 396, "speakers": ["John Peabody", "Cole Heilborn"], "start_timestamp": "00:18:55", "end_timestamp": "00:20:34", "podcast_index": 133, "episode_name": "EP: 133 How to Beat the Attention Economy | John G Peabody | Gear Patrol", "slug": "ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "web_url": "https://www.portsidepro.com/podcast-feed/ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "guest_name": "John Peabody", "guest_title": null, "categories": ["brand"], "short_description": "Do you struggle to create content that really resonates with your audience? Are you frustrated by shorter attention spans? On this episode, Cole sits down with John Peabody to talk about how to beat the attention economy and create GOOD content that matters.", "podcast_length": "1:09"}, {"id": "8b80076c-4efb-4a8e-9a70-6f0764570746", "episode_id": "75f56310-05dd-4251-93ca-e178ecafde6d", "cms_item_id": "68225dfc7bb476527f8c48a8", "chunk_index": 9, "content": "John Peabody (00:20:59): Yeah, I mean, as someone with a background in journalism and is passionate about journalism, I take a lot of the lessons from that world into creating content. So for me it's stories of human interest, human led narratives, narratives in general, telling stories about people, the backstories of products, using the tools of a journalist, really good photography, really good video production, sharp writing. These are things that sort of, they're just good quality production techniques that make things, I dunno, interesting is kind of a cop out word, but make things interesting to me. And that's sort of the trade craft of content is just producing things as highly as possible as you can. And I don't know, I think if you think about things almost as a journalist who journalists are fighting through all this noise as well all the time have been for a long time, the lessons from that world are easily applied to creating content. (00:22:22): And that's how I approach things. That's definitely not the only way to approach things. But I am not an influencer. I don't really buy into influencer marketing too much. I mean, I think there's probably a place for it, and I wouldn't say I would never work with influencers or anything like that. I have, but it's not one of the mediums or tools in my handbag that I want to use if I'm trying to really tell a story or let people know about a product or a service or something like that. It's not like, I don't know, the ten second video on TikTok isn't what I want to produce. I want to go deeper. I want to go a little bit longer and hopefully do something a little bit more impactful. So I don't know. I don't know if that answers your question, but that's kind of just where I come from is just quality storytelling basically.\n\nCole Heilborn (00:23:20): So maybe one way I'm trying to wrap my head around this is what about humans makes us one hour? We just want to consume TikTok and zone out for half an hour, but then the next hour we want to sit down and listen to a three hour podcast about aliens. What about us allows us to transition so quickly? And what about us finds both of those formats entertaining? Well,", "token_estimate": 550, "speakers": ["John Peabody", "Cole Heilborn"], "start_timestamp": "00:20:59", "end_timestamp": "00:23:20", "podcast_index": 133, "episode_name": "EP: 133 How to Beat the Attention Economy | John G Peabody | Gear Patrol", "slug": "ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "web_url": "https://www.portsidepro.com/podcast-feed/ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "guest_name": "John Peabody", "guest_title": null, "categories": ["brand"], "short_description": "Do you struggle to create content that really resonates with your audience? Are you frustrated by shorter attention spans? On this episode, Cole sits down with John Peabody to talk about how to beat the attention economy and create GOOD content that matters.", "podcast_length": "1:09"}, {"id": "72a13495-bdbe-4e22-92e8-4b1cc357cc29", "episode_id": "75f56310-05dd-4251-93ca-e178ecafde6d", "cms_item_id": "68225dfc7bb476527f8c48a8", "chunk_index": 10, "content": "John Peabody (00:23:45): Oh my God. Well, I mean we contain multitudes. I don't know, I don't know what it is. This is kind of a cop out, but we're just social creatures. We, we've evolved around storytelling and I think storytelling is probably one of the oldest, I don't know, forms of entertainment we have, I don't know, I don't want to say something cliche. We were cavemen sitting around a fire telling each other's stories, but we probably were. And that's in our DNA as humans. And how that comes to life now is crazy through phones and short videos on TikTok and stuff like that, but also very deep, much more immersive tools like podcasts and long form video and movies and all that kind of stuff. And I would say I'll go out on a limb and say even great tiktoks like podcasts or great movies have characters and have conflict, and there is a narrative to them. I think that's probably one of the ingredients of great TikTok is just those elements of storytelling as well. So I don't want to totally discredit short form content, even though it's not my bag in producing it. I definitely enjoy it and I think that those elements, I guess sort of have to be there as well. And maybe that's what the unifier is between long and shorter form content is just conflict characters narrative. If those are there, then you can kind of hook people in.\n\nCole Heilborn (00:25:37): Yeah. I'm also thinking about it before all the technology existed to, because there's a format and a piece of technology that meets us in every single spot in our life. It fits whatever we're doing in our life. If I'm on the bus, maybe I'm on TikTok, but if I'm at home on the couch, maybe I'm going to pop open YouTube and I'm going to watch a documentary. And maybe before we had all of these different formats, there was only so many ways that we could consume something either verbally, maybe reading the newspaper, reading a book, a magazine, et cetera. And maybe now there there's just so many more ways to tell a story that it makes us inundated because we can be consuming a story at any moment throughout our day.", "token_estimate": 526, "speakers": ["John Peabody", "Cole Heilborn"], "start_timestamp": "00:23:45", "end_timestamp": "00:25:37", "podcast_index": 133, "episode_name": "EP: 133 How to Beat the Attention Economy | John G Peabody | Gear Patrol", "slug": "ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "web_url": "https://www.portsidepro.com/podcast-feed/ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "guest_name": "John Peabody", "guest_title": null, "categories": ["brand"], "short_description": "Do you struggle to create content that really resonates with your audience? Are you frustrated by shorter attention spans? On this episode, Cole sits down with John Peabody to talk about how to beat the attention economy and create GOOD content that matters.", "podcast_length": "1:09"}, {"id": "52e3a77d-d8e1-4bfc-bdb9-01d77dec1e53", "episode_id": "75f56310-05dd-4251-93ca-e178ecafde6d", "cms_item_id": "68225dfc7bb476527f8c48a8", "chunk_index": 11, "content": "John Peabody (00:26:22): Yeah, absolutely. Totally a hundred percent agree. The phone is like, that's kind of why we have the love hate relationship with the phone is it's the thing that allows us to access all this great stuff, storytelling or touching base with your family or maps or music or whatever it is. But also what comes with it is almost that overwhelming sort of, I don't know, attention grab that it is. I mean, it's grabbing for your attention at all times. And yeah, geez, that's kind of the double-edged part of being a content marketer, content producer these days is you're competing with that and you're trying to stand out and not just be noise. I don't know anyone who wants to just add to the noise or the chaos, at least I don't want to. And I don't think good marketing does, basically.\n\nCole Heilborn (00:27:27): Yeah. Yeah. That's a very introspective question because if you were to really examine each of the work that each of us are doing, are we really cutting through the noise or are we just adding to it like this podcast, is it truly cutting through or are we just adding to the hundreds and thousands and millions of hours of podcasts that already exist?\n\nJohn Peabody (00:27:45): Well, this podcast clearly no, this podcast is rising above and delivering a premium experience to an engaged audience who appreciates it. So no, clearly we are not just adding to the noise right now.\n\nCole Heilborn (00:28:02): So I'm curious, with your time over your career history, how have you seen companies and brands react and start to shift to just the change in the attention economy that we've seen over the last 10 to 15 years? What things have you noticed?", "token_estimate": 422, "speakers": ["John Peabody", "Cole Heilborn"], "start_timestamp": "00:26:22", "end_timestamp": "00:28:02", "podcast_index": 133, "episode_name": "EP: 133 How to Beat the Attention Economy | John G Peabody | Gear Patrol", "slug": "ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "web_url": "https://www.portsidepro.com/podcast-feed/ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "guest_name": "John Peabody", "guest_title": null, "categories": ["brand"], "short_description": "Do you struggle to create content that really resonates with your audience? Are you frustrated by shorter attention spans? On this episode, Cole sits down with John Peabody to talk about how to beat the attention economy and create GOOD content that matters.", "podcast_length": "1:09"}, {"id": "8cdbd2be-99ad-486a-8d73-f494fe783232", "episode_id": "75f56310-05dd-4251-93ca-e178ecafde6d", "cms_item_id": "68225dfc7bb476527f8c48a8", "chunk_index": 12, "content": "John Peabody (00:28:18): I mean, there's major, I don't want to call 'em epochs or whatever of technology over the last, I guess I've been creating content or journalism for 20 years now. And so there was the rise of social media, which was crazy, Facebook and Twitter, and it seemed like this is the new dawn and this is the new way that we're going to consume content and everything is going to be through Facebook and Twitter and eventually Instagram. And that seemed kind of the way it was going to be for a while without getting too granular. That's been until fairly recently I think. And now it feels like those, God do I want to say paradigm shift. There's been a major shift of how we are generally not just thinking about, but actually consuming social media. I think the last six months to a year is, or even the last three months have been really telling, we've all sort of had these conversations about social media and the attention economy and felt this sort of overwhelming sense of, God, I'm looking at my phone all the time, but in the last couple months, Facebook and Twitter are sort of really, people are beginning to have conversations. (00:29:48): Is this the end of social media? New users aren't going to Facebook, younger users aren't going to Facebook, they're not going to Instagram. Twitter is like total chaos, partly thanks to Elon Musk. It's total chaos, and people are jumping to Twitter ship and going to Mastodon, or I don't even know what other new places they're finding. They're certainly going to Substack. A lot of people are just have Substack and are getting their news and information from Substack. So people are genuinely rejecting social media now in a way that they haven't for a long time. All this, of course, TikTok is super popular. I know tiktoks growing insane, so I know it's very hard to make blanket statements, but I think there's no doubt this rejection of social media happening right now, and I don't think it's going away. I don't think it's fully dying, but we're at a really, really interesting point now of what is the next phase of content consumption or whatever look like. And it feels less and less like social media. It's not going to be social media. I don't know. Does that kind of answer your question? I kind of forgot what you asked. Even.", "token_estimate": 579, "speakers": ["John Peabody"], "start_timestamp": "00:28:18", "end_timestamp": "00:28:18", "podcast_index": 133, "episode_name": "EP: 133 How to Beat the Attention Economy | John G Peabody | Gear Patrol", "slug": "ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "web_url": "https://www.portsidepro.com/podcast-feed/ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "guest_name": "John Peabody", "guest_title": null, "categories": ["brand"], "short_description": "Do you struggle to create content that really resonates with your audience? Are you frustrated by shorter attention spans? On this episode, Cole sits down with John Peabody to talk about how to beat the attention economy and create GOOD content that matters.", "podcast_length": "1:09"}, {"id": "3338735d-7501-4b4f-be32-b59291898941", "episode_id": "75f56310-05dd-4251-93ca-e178ecafde6d", "cms_item_id": "68225dfc7bb476527f8c48a8", "chunk_index": 13, "content": "Cole Heilborn (00:31:09): I mean, John, right now we're in the deep end, so there's no right or wrong\n\nJohn Peabody (00:31:12): Answer. No. Okay, good. Okay.\n\nCole Heilborn (00:31:15): So you mentioned in the last two to three months you've been seeing trends about folks moving away from social. Is that just related to Twitter or are there other things that you're aware of that are contributing also?\n\nJohn Peabody (00:31:28): Well, I mean Facebook, I think it's pretty well reported that they're struggling. Facebook as in meta, Facebook and Instagram are struggling to attract younger audiences. They're just not going to those platforms. I mean, that's the big challenge for Meta right now and why they're investing in the metaverse, right? The idea is the next operating system of the internet will be some kind of metaverse type experience, and they're making that big play, so they own the next operating system in 10 or 15 years or whatever. I don't know. I'm not smart enough to know at all if that's true. I think it's interesting that they're making a giant gamble as a company, and I think that in itself is a giant tell for a meta, like we are losing market share, and we recognize that it's such a big problem that we're willing to make such a giant gamble on some totally TBD underdeveloped product technology that frankly, we don't know if people really or will embrace, but we need to do something. And I don't know, I mean, I have a complicated relationship with social media, I think like everyone, but I give a lot of credit to, I don't know if it's Zuckerberg or the people in power at Facebook decision makers that they're willing to make such a big gamble. I feel like you don't see a lot of companies who are sitting on billions of dollars make such audacious gambles. Let's bet the whole company on the metaverse. That doesn't happen that often.\n\nCole Heilborn (00:33:12): Yeah, let's bet 6 million, 6 billion in invest towards this", "token_estimate": 490, "speakers": ["Cole Heilborn", "John Peabody"], "start_timestamp": "00:31:09", "end_timestamp": "00:33:12", "podcast_index": 133, "episode_name": "EP: 133 How to Beat the Attention Economy | John G Peabody | Gear Patrol", "slug": "ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "web_url": "https://www.portsidepro.com/podcast-feed/ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "guest_name": "John Peabody", "guest_title": null, "categories": ["brand"], "short_description": "Do you struggle to create content that really resonates with your audience? Are you frustrated by shorter attention spans? On this episode, Cole sits down with John Peabody to talk about how to beat the attention economy and create GOOD content that matters.", "podcast_length": "1:09"}, {"id": "e0adb60e-6d73-4aa5-bc95-01ac8f1b8e50", "episode_id": "75f56310-05dd-4251-93ca-e178ecafde6d", "cms_item_id": "68225dfc7bb476527f8c48a8", "chunk_index": 14, "content": "John Peabody (00:33:16): Thing. And I don't know, are we going to all be wearing headsets in six years and eight years? Geez, I don't think so. But also, I wouldn't have bet that Facebook would've been a thing six years before Facebook launched, so I don't know.\n\nCole Heilborn (00:33:36): Yeah, interesting. So YouTube is a platform that stands out to me since 2008 or whenever it was founded, has been steady rock\n\nJohn Peabody (00:33:46): Solid. Yeah, it's true.\n\nCole Heilborn (00:33:49): But they're, they're always improvising. They're always adapting, but they're not making any hail Mary's like Facebook is. If you had to compare the differences between Facebook and YouTube, what are they and why is YouTube a more stable platform around the attention economy and everything we've been discussing?", "token_estimate": 202, "speakers": ["John Peabody", "Cole Heilborn"], "start_timestamp": "00:33:16", "end_timestamp": "00:33:49", "podcast_index": 133, "episode_name": "EP: 133 How to Beat the Attention Economy | John G Peabody | Gear Patrol", "slug": "ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "web_url": "https://www.portsidepro.com/podcast-feed/ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "guest_name": "John Peabody", "guest_title": null, "categories": ["brand"], "short_description": "Do you struggle to create content that really resonates with your audience? Are you frustrated by shorter attention spans? On this episode, Cole sits down with John Peabody to talk about how to beat the attention economy and create GOOD content that matters.", "podcast_length": "1:09"}, {"id": "257f796e-334b-45f3-8674-25f9642f03fa", "episode_id": "75f56310-05dd-4251-93ca-e178ecafde6d", "cms_item_id": "68225dfc7bb476527f8c48a8", "chunk_index": 15, "content": "John Peabody (00:34:08): Yeah, I mean, that's a really great question, and as we were right before you were going to ask that question, YouTube popped in my mind is that's kind of the other elephant in the room. I mean, I don't know, maybe it's that YouTube is more of a platform for delivering content than Facebook is. I mean, I have YouTube on my TV and watch YouTube there. I have YouTube on my phone and it's also, it's not, people call it a social network, and I just don't think YouTube is a social network. In previous roles I had, when we were reporting social growth internally, YouTube would get thrown in and I was just like, this doesn't belong here. I don't have friends on YouTube that I'm interacting with. I have people I follow, but they're just channels like ESPN and Casey Nyad or whatever. So I don't know. (00:35:13): I'm sure there's someone who can argue that to me convincingly or the opposite of that. Convincingly to me, I don't know, YouTube is, YouTube is such a whale on the internet, and I love it so much. I really genuinely love YouTube. I love the breadth of content there. I love the quality of content there. There's a lot of stuff I will never, 99% of the stuff I won't ever consume, but the fact that I can go deep on the weirdest, most curious things is amazing. And it's not part of, well, there's an algorithm, but it's not part of a newsfeed where I'm getting a lot of other stuff from it. It's like I literally go in and I can get what I want. It's pretty good at knowing what I want without being really noisy too. So I don't know, I guess it's kind of a different beast than Facebook. (00:36:17): And it's a giant search engine too. I mean, I don't know about you, but when I'm searching for something on the internet, oftentimes it's just at YouTube I'm literally looking for a video of how to, I don't know, sharpen a knife or how to do something. I go to YouTube to do it. So that's a huge value proposition there that doesn't exist. It's almost like more comparable to Google Maps. It's just an amazing resource of information than it is a social network to me. And I don't think I'm alone in using it that way. Yeah,", "token_estimate": 542, "speakers": ["John Peabody"], "start_timestamp": "00:34:08", "end_timestamp": "00:34:08", "podcast_index": 133, "episode_name": "EP: 133 How to Beat the Attention Economy | John G Peabody | Gear Patrol", "slug": "ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "web_url": "https://www.portsidepro.com/podcast-feed/ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "guest_name": "John Peabody", "guest_title": null, "categories": ["brand"], "short_description": "Do you struggle to create content that really resonates with your audience? Are you frustrated by shorter attention spans? On this episode, Cole sits down with John Peabody to talk about how to beat the attention economy and create GOOD content that matters.", "podcast_length": "1:09"}, {"id": "8bff926c-5b1f-496f-bb4c-0771eb471d4b", "episode_id": "75f56310-05dd-4251-93ca-e178ecafde6d", "cms_item_id": "68225dfc7bb476527f8c48a8", "chunk_index": 16, "content": "Cole Heilborn (00:37:02): I mean, just this morning I was looking up how to change the heat shield on my wife's Subaru exhaust.\n\nJohn Peabody (00:37:07): That's a fun project. There you go.\n\nCole Heilborn (00:37:10): Yeah, it's rattling and I need to swap it out, but where do I go to figure out how to do that quick YouTube search and I can find the make and model and I mean, everyone knows how that works.\n\nJohn Peabody (00:37:21): Yeah, totally. There's some guy who's got the exact car and has done it step by step in 45 seconds and you're like, the Internet's amazing. Thank you.\n\nCole Heilborn (00:37:30): Yeah. So for you, if it doesn't fit in the social media camp, where does it belong?\n\nJohn Peabody (00:37:39): I don't know. That's a really good question. I a platform for distribution, but that also undersells it. I dunno, I guess it kind of defies categories in my mind. And to be fair, it is social. People use it as social media. I mean, listen, if I was Casey, nice stat, I would probably see YouTube as a social platform telling your story, sharing it with people, people liking it, people commenting. That is very much a social platform in that sense, but that's not how I use it. So I guess it's a lot of different things to a lot of different people.\n\nCole Heilborn (00:38:23): Do you feel like brands in the industry today are fully capitalizing on the potential of YouTube?\n\nJohn Peabody (00:38:31): Some are, yeah. I mean some for sure, some not. Yeah, that's the easy answer. I mean, I think to capitalize on it fully, you have to fully embrace producing video, which is not easy as and good video and anything. If you're going to do it, you kind of have to fully commit to doing it basically. Otherwise it's just not even worth it, basically.", "token_estimate": 443, "speakers": ["Cole Heilborn", "John Peabody"], "start_timestamp": "00:37:02", "end_timestamp": "00:38:31", "podcast_index": 133, "episode_name": "EP: 133 How to Beat the Attention Economy | John G Peabody | Gear Patrol", "slug": "ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "web_url": "https://www.portsidepro.com/podcast-feed/ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "guest_name": "John Peabody", "guest_title": null, "categories": ["brand"], "short_description": "Do you struggle to create content that really resonates with your audience? Are you frustrated by shorter attention spans? On this episode, Cole sits down with John Peabody to talk about how to beat the attention economy and create GOOD content that matters.", "podcast_length": "1:09"}, {"id": "bc8f336a-5c62-4ce1-a77f-e6ca3df7f75e", "episode_id": "75f56310-05dd-4251-93ca-e178ecafde6d", "cms_item_id": "68225dfc7bb476527f8c48a8", "chunk_index": 17, "content": "Cole Heilborn (00:39:05): Yeah, your investment time is years of work and you see so many brands on YouTube, but I don't know that, I think the ones that are doing it really well, the audience knows what to expect. They've been trained to consume whatever it is per the brands, but there's a lot of brands out there that I don't know that have really trained themselves or train their audience to consume what they're creating. And I think that's why you see poor engagement on a lot of platforms or on a lot of channels, brand platforms.\n\nJohn Peabody (00:39:40): Yeah, I think that's a good point. I mean, who's doing YouTube really well? What's a brand that's doing YouTube really well, in your opinion?\n\nCole Heilborn (00:39:48): I mean, the easiest example is Patagonia, but they're kind of an exception because, well, they're not even an exception. They do an amazing job.\n\nJohn Peabody (00:40:00): Yeah, I think they do great stuff and they train their audience to know what to expect there. We're going to do some sort of slower docus style films about the environment and sort of environmental justice and stuff like that. Yeah, I love it. Mean Yeti comes to mind for me as just killing it with YouTube and video in general. And I think Yeti's been doing these really good documentaries for a while. And I think I remember the first time I watched one of their documentaries, I don't even know which one it was, which had nothing to do with coolers at all, absolutely nothing to do with coolers. I was like, why is Yeti doing this? Why did Yeti just produce this crazy really, really good video that's on par with anything you'd see at a film festival anywhere? And I guess they had a film festival, maybe they were promoting, I don't even really know the backstory, but now they've trained their audience, people on YouTube to expect really super high quality videos on their YouTube channel, and they pretty consistently deliver really amazing storytelling, high production value stuff you don't expect from Yeti. And I dunno, I'm sort of consistently impressed with them.", "token_estimate": 521, "speakers": ["Cole Heilborn", "John Peabody"], "start_timestamp": "00:39:05", "end_timestamp": "00:40:00", "podcast_index": 133, "episode_name": "EP: 133 How to Beat the Attention Economy | John G Peabody | Gear Patrol", "slug": "ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "web_url": "https://www.portsidepro.com/podcast-feed/ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "guest_name": "John Peabody", "guest_title": null, "categories": ["brand"], "short_description": "Do you struggle to create content that really resonates with your audience? Are you frustrated by shorter attention spans? On this episode, Cole sits down with John Peabody to talk about how to beat the attention economy and create GOOD content that matters.", "podcast_length": "1:09"}, {"id": "bd9690e6-9d4f-4ee0-98a5-c0c09fa053c7", "episode_id": "75f56310-05dd-4251-93ca-e178ecafde6d", "cms_item_id": "68225dfc7bb476527f8c48a8", "chunk_index": 18, "content": "Cole Heilborn (00:41:34): Definitely. Yeah, I've always looked up to them. They do phenomenal work and one day I'd love to have the opportunity to work with them.\n\nJohn Peabody (00:41:43): Yeti call Cole, give Cole a call. Come on, let's do this.\n\nCole Heilborn (00:41:47): Thanks John. I appreciate the plug. So that's an interesting idea. I'm thinking now about, I'm kind of speaking out loud here, I'll see if my thought lands. I'm thinking now about the difference between short form and long form content and the investment expectations of each of those types of content. And in the short attention span economy that we're in, the goal is mass content, frequent constant content that hopefully has a high return on, I post something, I see a sale, I post five things and I see five sales. So we've been almost, I wonder if our brands do they expect is the expectation to see quick returns on short form pieces of content? And then I get, I'm comparing that to long form content, which seems like a much longer play, a much more brand play rather than the short return", "token_estimate": 268, "speakers": ["Cole Heilborn", "John Peabody"], "start_timestamp": "00:41:34", "end_timestamp": "00:41:47", "podcast_index": 133, "episode_name": "EP: 133 How to Beat the Attention Economy | John G Peabody | Gear Patrol", "slug": "ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "web_url": "https://www.portsidepro.com/podcast-feed/ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "guest_name": "John Peabody", "guest_title": null, "categories": ["brand"], "short_description": "Do you struggle to create content that really resonates with your audience? Are you frustrated by shorter attention spans? On this episode, Cole sits down with John Peabody to talk about how to beat the attention economy and create GOOD content that matters.", "podcast_length": "1:09"}, {"id": "651f2ad8-e8c1-49ee-b576-05cd29e72440", "episode_id": "75f56310-05dd-4251-93ca-e178ecafde6d", "cms_item_id": "68225dfc7bb476527f8c48a8", "chunk_index": 19, "content": "John Peabody (00:42:54): Sort of brand expectations versus the content execution or short form, long form piece of content. And what do they expect? I think this is a really good thing to talk about because I think there's almost this misconception, or not misconception, but misunderstanding of what different pieces of content can do for you or your brand. And it's not always moving product. That can be the value of one piece of content, but it might not be the value of, say, a long form video, which might be more about building brand awareness or getting people to find you on YouTube, for example. So I think there's a lot of nuance, and I think this is a really critical part of creative strategy, is just knowing what tools are in your bag and which ones are effective at doing which. So if a client or a brand wants to say, move a lot of sweatshirts, they're selling sweatshirts or something, you're probably not going to spend six months making a long form documentary about some fishermen in Argentina or something. (00:44:08): It just doesn't make sense. But you might sponsor an article at Gear Patrol or somewhere else, wherever it is that talks about some of the finer points and design points, and I dunno, elements of the sweatshirt to get people to know about it. Or you might just post a sponsored post on Instagram and maybe that's enough to do it. So it just comes down to what are you trying to achieve? And it's the marketing funnel that we all kind of talk about and know about. But it's always good to keep in mind. And I would say, and I don't want to sound like too self-serving or I'm trying to plug Gear Patrol or whatever, but I would just say in general, I think publishers are really, really well positioned for this reason, because you can move people through the funnel in a way that a lot of other advertising partners, so you can do bigger, deeper storytelling that builds awareness about a brand. (00:45:18): And then you can do shorter form stories that are sort of more about consideration considering specific products, moving 'em down the funnel to here's an actual deal on this product and you can buy this sweatshirt or this knife right now, maybe there's a discount or whatever, but here's where you go to buy it. And I think that I am super bullish on publishers and content marketing in general, branded content almost just for that reason, because you can enter into that funnel or that stream or whatever you want to call it, and create different pieces of content in different places that help kind of move users, audience people along in different ways that other partners can't do or just don't have the ability to.", "token_estimate": 667, "speakers": ["John Peabody"], "start_timestamp": "00:42:54", "end_timestamp": "00:42:54", "podcast_index": 133, "episode_name": "EP: 133 How to Beat the Attention Economy | John G Peabody | Gear Patrol", "slug": "ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "web_url": "https://www.portsidepro.com/podcast-feed/ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "guest_name": "John Peabody", "guest_title": null, "categories": ["brand"], "short_description": "Do you struggle to create content that really resonates with your audience? Are you frustrated by shorter attention spans? On this episode, Cole sits down with John Peabody to talk about how to beat the attention economy and create GOOD content that matters.", "podcast_length": "1:09"}, {"id": "28412808-1920-4f49-883b-c6673fd61e4a", "episode_id": "75f56310-05dd-4251-93ca-e178ecafde6d", "cms_item_id": "68225dfc7bb476527f8c48a8", "chunk_index": 20, "content": "Cole Heilborn (00:46:21): And I think that's one of the benefits of a publisher like Gear Patrol when a brand works with you or as a customer, if I go to Gear Patrol, I might realize that what I'm reading or what I'm watching is sponsored content. And in the back of my mind, I know, oh, this brand partnered with Gear Patrol, but there's some level of journalistic unbiased that seems to come with a site like Gear Patrol where I go there because I want a perspective on something that maybe I really don't trust the brand to give me because they're too close. They're the brand, they sell the product. But Gear Patrol is kind of this, I mean, you're really in many ways an influencer. The company is an influencer that people trust. I trust for quality reviews and quality products. So that separation between the brand and the consumer I think is really valuable, especially in today's world where you carry that weight of authority, you have that perspective in the community that is trusted.", "token_estimate": 249, "speakers": ["Cole Heilborn"], "start_timestamp": "00:46:21", "end_timestamp": "00:46:21", "podcast_index": 133, "episode_name": "EP: 133 How to Beat the Attention Economy | John G Peabody | Gear Patrol", "slug": "ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "web_url": "https://www.portsidepro.com/podcast-feed/ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "guest_name": "John Peabody", "guest_title": null, "categories": ["brand"], "short_description": "Do you struggle to create content that really resonates with your audience? Are you frustrated by shorter attention spans? On this episode, Cole sits down with John Peabody to talk about how to beat the attention economy and create GOOD content that matters.", "podcast_length": "1:09"}, {"id": "efc7c13f-bbef-4868-b056-6ee502c96b15", "episode_id": "75f56310-05dd-4251-93ca-e178ecafde6d", "cms_item_id": "68225dfc7bb476527f8c48a8", "chunk_index": 21, "content": "John Peabody (00:47:23): Yeah, I'm glad you're saying that because I think that's exactly the point. I think there's also, there's an element, this is something I noticed when I was at Hokey, which is a watch website, watch blog and e-commerce shop, amazing site, amazing watches. But I used to always wonder people, are people suspect of branded content on Hokey because it's a watch shop, it's a watch blog. Do people trust branded content? And ultimately what it came down to is, I actually think I thought about that a lot more than anyone who was looking at the content thought about it. If you're into watches and you see interesting watch content, whether it's by the editors or sponsored by a brand, it almost doesn't matter because you're just like, I'm just into this watch and seeing photos of this watch and learning about this watch. How deep can I take it in the ocean? Or what's the backstory of it? Or how big is the case or whatever. (00:48:39): And I don't want to write I off. I think it's important to recognize that there's editorial content and branded content and they serve different purposes. But I also just think in general when it comes to product journalism, people just want to know about products and want to find out about cool products. And it's sort of not like we're the New York Times and we're producing sponsored content on some major policy thing, like Exxon gave us money and we have some sponsored piece of content about how great oil and gases for the future, that's a little bit more problematic than here's just a cool knife that, Hey, you might be interested in buying this thing if you're into knives. You know what I mean?", "token_estimate": 418, "speakers": ["John Peabody"], "start_timestamp": "00:47:23", "end_timestamp": "00:47:23", "podcast_index": 133, "episode_name": "EP: 133 How to Beat the Attention Economy | John G Peabody | Gear Patrol", "slug": "ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "web_url": "https://www.portsidepro.com/podcast-feed/ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "guest_name": "John Peabody", "guest_title": null, "categories": ["brand"], "short_description": "Do you struggle to create content that really resonates with your audience? Are you frustrated by shorter attention spans? On this episode, Cole sits down with John Peabody to talk about how to beat the attention economy and create GOOD content that matters.", "podcast_length": "1:09"}, {"id": "39406c97-063c-4e0a-9ab9-d37e15bc2efd", "episode_id": "75f56310-05dd-4251-93ca-e178ecafde6d", "cms_item_id": "68225dfc7bb476527f8c48a8", "chunk_index": 22, "content": "Cole Heilborn (00:49:30): Yeah. I think it goes to say also it's important for a brand to have a partner like Gear Patrol, but also be their own sustaining, thriving content machine. I'm thinking about if I'm going to go, let's say hire someone to fix my wife's car because I can't figure out the heat shield on YouTube, probably what I'm going to do is I might ask for a referral from a friend, which is getting a referral from Gear Patrol, and then I might go to that auto body or that mechanic shop and then look at their contents or their website, and both of them need to meet my expectations and answer my questions. One without the other isn't as powerful.\n\nJohn Peabody (00:50:09): Yeah, totally. I mean, that's like a lot of brands have their in-house content studios now to do that, and they should and have to, because a publisher now, and this is to your question of who's doing YouTube well and who's not, it's like, I don't know, some brands create awesome content and some others, it's really, really hard. It's hard to produce it. Yeah.\n\nCole Heilborn (00:50:36): So do you feel like branded content is a format that we should be paying attention to as we're trying to figure out how to cut through the noise that's out there?", "token_estimate": 311, "speakers": ["Cole Heilborn", "John Peabody"], "start_timestamp": "00:49:30", "end_timestamp": "00:50:36", "podcast_index": 133, "episode_name": "EP: 133 How to Beat the Attention Economy | John G Peabody | Gear Patrol", "slug": "ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "web_url": "https://www.portsidepro.com/podcast-feed/ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "guest_name": "John Peabody", "guest_title": null, "categories": ["brand"], "short_description": "Do you struggle to create content that really resonates with your audience? Are you frustrated by shorter attention spans? On this episode, Cole sits down with John Peabody to talk about how to beat the attention economy and create GOOD content that matters.", "podcast_length": "1:09"}, {"id": "eef5dc70-7f11-4684-a6bf-bceac0094fc2", "episode_id": "75f56310-05dd-4251-93ca-e178ecafde6d", "cms_item_id": "68225dfc7bb476527f8c48a8", "chunk_index": 23, "content": "John Peabody (00:50:47): Well, I mean, that's an interesting question. I don't know totally how to answer it other than maybe if it's good or it provides value, you're trying to change the heat shield in your car, and I don't know, maybe the auto parts company or whatever created a video on how to do this, then that's great branded content or marketing content, it has utilitarian value, then you should pay attention to it. Or I don't want to tell anyone they should or shouldn't do anything, but that's helpful content. But geez, there's so much not helpful content out there. (00:51:36): I don't want to say you should ignore other content, but people just do because it's not interesting or not helpful. So I don't know. I personally just watch, consume what interests me, and if it's branded or it's not branded at this point in time where we are in the world and technology, it doesn't really matter to me too much if Yeti produced a video or if the National Geographic produced a video or if the New York Times produced a video. If it's interesting and it's good, I'll watch it. I feel like I'm savvy enough to understand, okay, there's this agenda behind this video or whatever, and that's fine.\n\nCole Heilborn (00:52:30): So we've mentioned a few different formats of branded content. We've talked a lot about video and film, podcasts, articles. I'm curious, in your time, have you come across any other medium or format that isn't mainstream that you've noted and you're like, oh, that was a really interesting format, or a way that that content was delivered?", "token_estimate": 393, "speakers": ["John Peabody", "Cole Heilborn"], "start_timestamp": "00:50:47", "end_timestamp": "00:52:30", "podcast_index": 133, "episode_name": "EP: 133 How to Beat the Attention Economy | John G Peabody | Gear Patrol", "slug": "ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "web_url": "https://www.portsidepro.com/podcast-feed/ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "guest_name": "John Peabody", "guest_title": null, "categories": ["brand"], "short_description": "Do you struggle to create content that really resonates with your audience? Are you frustrated by shorter attention spans? On this episode, Cole sits down with John Peabody to talk about how to beat the attention economy and create GOOD content that matters.", "podcast_length": "1:09"}, {"id": "68c3b9e3-ff71-4bac-9156-ef8a872a89c1", "episode_id": "75f56310-05dd-4251-93ca-e178ecafde6d", "cms_item_id": "68225dfc7bb476527f8c48a8", "chunk_index": 24, "content": "John Peabody (00:52:52): That's a good question. Well, I mean, podcasts are interesting, and there are some obviously branded podcasts out there. More and more, a lot of them produce sort of in-house activations. Events are really interesting to me. The Atlantic where I used to work just had this giant event in LA, and I forget the name of it, but it was a giant art installation and it kind of created a forest inside a big warehouse. I didn't get to go, I wasn't in la I wish I had, but that is a giant branded event that was sponsored, I think by MasterCard. I could be getting this wrong, but that's a total format breaker and something that people went to and because it was just interesting and creative and experiential and there wasn't anything like that that had ever been done before. So that's super interesting. I don't know the details about production or anything, but it was a big, big production. So I don't know. Events are always interesting. Totally different, totally different beast. And I've been involved in a couple producing a couple smaller ones. But yeah, I think in situations like that, the opportunities are endless.\n\nCole Heilborn (00:54:35): I never thought about that as an event, as a form of brand branded content, but you bring it up and I mean, it makes total sense and everyone's been going to events and it doesn't feel like, I mean, it's sponsored content.", "token_estimate": 350, "speakers": ["John Peabody", "Cole Heilborn"], "start_timestamp": "00:52:52", "end_timestamp": "00:54:35", "podcast_index": 133, "episode_name": "EP: 133 How to Beat the Attention Economy | John G Peabody | Gear Patrol", "slug": "ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "web_url": "https://www.portsidepro.com/podcast-feed/ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "guest_name": "John Peabody", "guest_title": null, "categories": ["brand"], "short_description": "Do you struggle to create content that really resonates with your audience? Are you frustrated by shorter attention spans? On this episode, Cole sits down with John Peabody to talk about how to beat the attention economy and create GOOD content that matters.", "podcast_length": "1:09"}, {"id": "eb808308-a227-4a2f-a44c-ad2ce333107c", "episode_id": "75f56310-05dd-4251-93ca-e178ecafde6d", "cms_item_id": "68225dfc7bb476527f8c48a8", "chunk_index": 25, "content": "John Peabody (00:54:49): Yeah, it's like a branded experience. And probably I think going to see more of those now that we're all Covid iss overish or I don't know what the right way to describe Covid is right now, but yeah, I'm sure we'll see more of those. I'm trying to think of other branded content formats that have kind of stuck out to me. I mean, Netflix is really interesting branded content too. There's endless product placement in Netflix, which we don't even really realize when we're watching it. But that's a giant business that I don't feel like we really know a lot about. Most of us, even savvy consumers of media don't even fully appreciate or understand how much of Netflix is actually branded content. And I think it's like a lot. Why is that Coca-Cola in there? Because Coca-Cola paid to put it there. Yeah. I dunno. What about you? Are there any formats you can think of or anything that's notable to you?\n\nCole Heilborn (00:56:01): I'm really intrigued by, and I don't have an example, but I'm really intrigued by more experiential or more in in-person experiences. (00:56:14): And I guess a sort of quasi example is, so a couple of years ago I purchased, I got a pair of long Johns base layers and they showed up and the box they showed up in was its own experience in itself. It was super well created, the artwork was incredible, and you open the lid and they're like, there, there's something you read and then you go one layer deeper and there's something else and there's a book, and then there's a picture, and then you eventually reach the product. But it was its own experience just unboxing the product, which I thought was it stuck out to me. And I've never purchased a product that has intrigued me the same way as this base layer. And so obviously it's very different because I've already purchased the product and I sat my doorstep, but that really stood out to me.", "token_estimate": 476, "speakers": ["John Peabody", "Cole Heilborn"], "start_timestamp": "00:54:49", "end_timestamp": "00:56:01", "podcast_index": 133, "episode_name": "EP: 133 How to Beat the Attention Economy | John G Peabody | Gear Patrol", "slug": "ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "web_url": "https://www.portsidepro.com/podcast-feed/ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "guest_name": "John Peabody", "guest_title": null, "categories": ["brand"], "short_description": "Do you struggle to create content that really resonates with your audience? Are you frustrated by shorter attention spans? On this episode, Cole sits down with John Peabody to talk about how to beat the attention economy and create GOOD content that matters.", "podcast_length": "1:09"}, {"id": "ac662dae-25c5-4875-89b3-260c19acd1f4", "episode_id": "75f56310-05dd-4251-93ca-e178ecafde6d", "cms_item_id": "68225dfc7bb476527f8c48a8", "chunk_index": 26, "content": "John Peabody (00:57:08): Yeah, that's an interesting, I mean, that's so many smart people really thinking about that exact moment to make you feel this sense of wonder when you open a product, I think is pretty cool and interesting, hence a zillion unboxing video accounts on YouTube that are exploring all that stuff. It made me kind of think about how we think of going to stores now too. And that stores have obviously are experiences and a good store is an experience in itself, especially here in New York. They're almost like loss leaders for a lot of brands. They know they're not going to really make money from the store, but they want it to be almost an embassy for their brand, a place where you can go experience the brand or whatever and what it's all about. And the box is an extension of that too, that you should feel the brand, the values of the brand at the store. And if you're not at the store, you should feel what the brand's about just by opening up the product at home. I think that's super interesting. It's not totally my world, but one that I really, really appreciate when it's done really well, for sure.\n\nCole Heilborn (00:58:30): Yeah. What about apparel?\n\nJohn Peabody (00:58:32): Yeah. What about it?\n\nCole Heilborn (00:58:36): I mean, we're all walking billboards.\n\nJohn Peabody (00:58:38): I don't know. I'm of a generation that doesn't want to be a walking billboard, and I personally don't like logos on me and by very clothing that has very minimal logos. That's just me. I'm not the normal person right now. I live in New York and obviously younger people want to wrap brands, and that's fashion, right? It's like supreme written across my chest or whatever, more power to you. That's not what I want at all. Even though I work in branded content, I don't want to be branded content.", "token_estimate": 456, "speakers": ["John Peabody", "Cole Heilborn"], "start_timestamp": "00:57:08", "end_timestamp": "00:58:38", "podcast_index": 133, "episode_name": "EP: 133 How to Beat the Attention Economy | John G Peabody | Gear Patrol", "slug": "ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "web_url": "https://www.portsidepro.com/podcast-feed/ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "guest_name": "John Peabody", "guest_title": null, "categories": ["brand"], "short_description": "Do you struggle to create content that really resonates with your audience? Are you frustrated by shorter attention spans? On this episode, Cole sits down with John Peabody to talk about how to beat the attention economy and create GOOD content that matters.", "podcast_length": "1:09"}, {"id": "29895eeb-9b3c-43ab-9560-9712b376e0c6", "episode_id": "75f56310-05dd-4251-93ca-e178ecafde6d", "cms_item_id": "68225dfc7bb476527f8c48a8", "chunk_index": 27, "content": "Cole Heilborn (00:59:23): Yeah, I'm just thinking about when you're skiing and you look up above the chairlift and you see the name of every ski manufacturer on the snowboard or the ski underneath. Yeah. I just wonder if there's a way to take that further. I see the Burton logo on the bottom of the snowboard, but is there a way to let me continue that journey somehow while I'm on the ski hill? I don't know.\n\nJohn Peabody (00:59:47): I don't know either. Let's pitch Burton on a program. We're going to create a lodge on the side of the slope. That's a Burton branded experience. I mean, they probably wouldn't even be into it anyway. They're like, they probably don't even need to do branded content.\n\nCole Heilborn (01:00:06): Yeah, that's an interesting idea though. Like a branded ski lodge.\n\nJohn Peabody (01:00:09): Yeah, I'm sure it's been done. I'm sure someone's done it. And you can have Burton Hot Chocolate or something as you warm your boots up in the Burton heat warmer or whatever. Yeah,\n\nCole Heilborn (01:00:23): Because thinking about that, that might devalue my appreciation for the brand though.\n\nJohn Peabody (01:00:28): Yeah, totally. I mean, I think that that's kind of a cool brand because they're sort of a little bit of, I don't know, they cut their own path and sort of anti-establishment.\n\nCole Heilborn (01:00:41): Yeah. Interesting. So we've discussed a lot. I'm curious what sticks out to you if you kind of had to sum things up as you look towards the future and just considering the various aspects we've discussed today.", "token_estimate": 390, "speakers": ["Cole Heilborn", "John Peabody"], "start_timestamp": "00:59:23", "end_timestamp": "01:00:41", "podcast_index": 133, "episode_name": "EP: 133 How to Beat the Attention Economy | John G Peabody | Gear Patrol", "slug": "ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "web_url": "https://www.portsidepro.com/podcast-feed/ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "guest_name": "John Peabody", "guest_title": null, "categories": ["brand"], "short_description": "Do you struggle to create content that really resonates with your audience? Are you frustrated by shorter attention spans? On this episode, Cole sits down with John Peabody to talk about how to beat the attention economy and create GOOD content that matters.", "podcast_length": "1:09"}, {"id": "54a529cc-85be-486e-b269-f7ef19781167", "episode_id": "75f56310-05dd-4251-93ca-e178ecafde6d", "cms_item_id": "68225dfc7bb476527f8c48a8", "chunk_index": 28, "content": "John Peabody (01:00:55): Well, I can say a couple things about where I think we kind of are and a little bit where things are going. I don't want to try and predict the future because it can't be done, but I think that there's some notable things happening right now that if I was in marketing or advertising, there are things I'm paying attention to. And one is of course sort of the decline of social media and Facebook is a big part of that, and how apple's privacy rules have affected Facebook. And so how we're consuming media and the general distrust or disharmony with shorter form content and social media and stuff like that is happening, just feeling like OD'ed on it asterisk, even though TikTok is growing and super popular, obviously. So that's one interesting thing, and I think that there's a real interesting moment and opportunity right now for a deeper call it long form content, just high quality content again, and for brands to produce it or whomever is trying to get a messaging out. I mean, even if it's a political party or a nonprofit or whoever, there are sort of endless opportunities to tell deeper stories now that will actually be consumed and be appreciated and enjoyed by people. (01:02:41): I don't think this is a cutting edge idea, but it's just a trend we're seeing now that I am really, really appreciative of coming from a place 10 years ago where it seemed like longer form content was maybe gone. Magazines are disappearing, no one's watching documentary films or whatever. And it turns out no, people actually do want this content. They do want longer form content. They do have long attention spans if what they're consuming is done well. And that's, to me a very interesting opportunity and a very optimistic one that I feel very good about. So I don't know if that kind of wraps it up, but that's where my head's at is kind of just recommitting to this idea of producing really good engaging content that doesn't have to be five seconds long.\n\nCole Heilborn (01:03:44): So what does that mean for your team at the studio?", "token_estimate": 517, "speakers": ["John Peabody", "Cole Heilborn"], "start_timestamp": "01:00:55", "end_timestamp": "01:03:44", "podcast_index": 133, "episode_name": "EP: 133 How to Beat the Attention Economy | John G Peabody | Gear Patrol", "slug": "ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "web_url": "https://www.portsidepro.com/podcast-feed/ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "guest_name": "John Peabody", "guest_title": null, "categories": ["brand"], "short_description": "Do you struggle to create content that really resonates with your audience? Are you frustrated by shorter attention spans? On this episode, Cole sits down with John Peabody to talk about how to beat the attention economy and create GOOD content that matters.", "podcast_length": "1:09"}, {"id": "fabf21e2-a4e8-4ff2-9fb1-0ebe1a388685", "episode_id": "75f56310-05dd-4251-93ca-e178ecafde6d", "cms_item_id": "68225dfc7bb476527f8c48a8", "chunk_index": 29, "content": "John Peabody (01:03:47): It means that we just double down on doing things really well, working with really good photographers, spending time to design articles to make sure they look beautiful, making sure the copy is really well written and engaging sharp, making sure that what we are putting into the world is good. I think it has to be, and it just is a commitment to craft. I mean, creating content for you and myself is a craft, and if you enjoy it and respect it, then I think that's the only way to do it, is to kind of do it well. What's the point otherwise?\n\nCole Heilborn (01:04:34): Yeah. Yeah. Well said. Well, on that note of wrapping things up, you've given me some optimism about the future. Yeah. I mean, it seems like why wouldn't you want to make something that people remember? I guess that seems really obvious to me, but maybe that's naive. Maybe I'm slightly naive.\n\nJohn Peabody (01:04:50): I don't think so. I don't think so, and I think honestly, that is to me, the ultimate goal right there. If I can make a piece of content, a video, an article that is remembered, I might not always couch success in these terms, but that's ultimately what you want to do is make something that people remember and think about. That's a huge success. If you can do that today, you've the content game.\n\nCole Heilborn (01:05:19): So here's another, I'm taking that thought and I'm running with it. It seems odd. That isn't a lot of our perspective on things. People only have, I mean, the attention economy is built on the idea that our attention is a commodity, therefore it's limited. I only have 24 hours in a day to consume something. So why have we made such an emphasis to create volume of content when we could be focusing on the deeper content to, I guess I'm trying to connect those dots. I could either make a lot of content to stand out or I can make a couple pieces of content to really stand out.", "token_estimate": 481, "speakers": ["John Peabody", "Cole Heilborn"], "start_timestamp": "01:03:47", "end_timestamp": "01:05:19", "podcast_index": 133, "episode_name": "EP: 133 How to Beat the Attention Economy | John G Peabody | Gear Patrol", "slug": "ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "web_url": "https://www.portsidepro.com/podcast-feed/ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "guest_name": "John Peabody", "guest_title": null, "categories": ["brand"], "short_description": "Do you struggle to create content that really resonates with your audience? Are you frustrated by shorter attention spans? On this episode, Cole sits down with John Peabody to talk about how to beat the attention economy and create GOOD content that matters.", "podcast_length": "1:09"}, {"id": "561cef90-4a82-4a33-8117-b871c45da386", "episode_id": "75f56310-05dd-4251-93ca-e178ecafde6d", "cms_item_id": "68225dfc7bb476527f8c48a8", "chunk_index": 30, "content": "John Peabody (01:05:57): I think it's almost like this, there's two ways of thinking about it, and this is a gross simplification, but you could create really short content that's just designed to grab someone's attention for a second. That's almost the equivalent of them yelling at you like, Hey, pay attention to me. And it's like, okay, you got my attention. What is it? And it's like, look at this pen. And you're like, okay, great, great, cool. I just broke my train of thought, but I am now seeing a pen. Cool. Or you can try and do something that hits on a deeper level and maybe makes you, not even make you think more, but just enjoy more or sit with a little bit more, and I don't even mean a 30 minute video or something, but just something that's slightly deeper and that's the content that is going to build a deeper affinity for a brand and sort of build more trust and awareness. And that's the Yeti video or the Patagonia video or whatever. That's done really well, that's someone's going to talk about on a podcast like years later, they're going to be like, yes, I remember watching this video six years ago. They're not going to talk about the little loud piece of content that broke their attention and broke through the noise for a quarter of a second, but then just became the noise.\n\nCole Heilborn (01:07:27): Yeah. I love it. Let's wrap things up there.\n\nJohn Peabody (01:07:31): Okay.\n\nCole Heilborn (01:07:31): John, if folks want to connect with you, they want to learn more about Gear Patrol Studios or find you personally, where can they go to connect?\n\nJohn Peabody (01:07:39): Yeah, if people want to connect gear patrol studios.com or gear patrol.com, hit us up. Of course, you can find me online, John peabody.net is my website, but Instagram, Twitter, I'm all the place. And yeah. Cole, this has been really fun. I really appreciate it.", "token_estimate": 468, "speakers": ["John Peabody", "Cole Heilborn"], "start_timestamp": "01:05:57", "end_timestamp": "01:07:39", "podcast_index": 133, "episode_name": "EP: 133 How to Beat the Attention Economy | John G Peabody | Gear Patrol", "slug": "ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "web_url": "https://www.portsidepro.com/podcast-feed/ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "guest_name": "John Peabody", "guest_title": null, "categories": ["brand"], "short_description": "Do you struggle to create content that really resonates with your audience? Are you frustrated by shorter attention spans? On this episode, Cole sits down with John Peabody to talk about how to beat the attention economy and create GOOD content that matters.", "podcast_length": "1:09"}, {"id": "ff4b8f49-9ffc-448f-99d0-29cd01ffdc4f", "episode_id": "75f56310-05dd-4251-93ca-e178ecafde6d", "cms_item_id": "68225dfc7bb476527f8c48a8", "chunk_index": 31, "content": "Cole Heilborn (01:08:03): Likewise. Yeah, I appreciate you being willing just to kind of jump in and dive into a topic that we're definitely not smart enough to understand, but we just kind of bumble around in it and come up with some ideas. Folks, I'd highly encourage you to go check out John's website. We didn't touch on it at all, but you did a project with John Mayer a few years ago. Very well done. Very, very cool project. So I'll leave folks with that. Go check out John's website and see what he's been up to. John, thank you again for taking the time and I hope you have a great rest of your day.\n\nSpeaker 3 (01:08:35): Thanks, man. My pleasure.\n\nCole Heilborn (01:08:36): Take care.\n\nSpeaker 3 (01:08:37): Bye.\n\nCole Heilborn (01:08:38): Thank you for listening to this episode of the Backcountry Marketing Podcast. Please share it with a friend or leave us a review on Apple. If you work at a brand or agency in the outdoor industry that needs help bringing in video project to life, head over to portside pro.com and send us an email. We'd love to help.", "token_estimate": 267, "speakers": ["Cole Heilborn", "Speaker 3"], "start_timestamp": "01:08:03", "end_timestamp": "01:08:38", "podcast_index": 133, "episode_name": "EP: 133 How to Beat the Attention Economy | John G Peabody | Gear Patrol", "slug": "ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "web_url": "https://www.portsidepro.com/podcast-feed/ep-133-director-of-branded-content-john-g-peabody-gear-patrol", "guest_name": "John Peabody", "guest_title": null, "categories": ["brand"], "short_description": "Do you struggle to create content that really resonates with your audience? Are you frustrated by shorter attention spans? On this episode, Cole sits down with John Peabody to talk about how to beat the attention economy and create GOOD content that matters.", "podcast_length": "1:09"}, {"id": "6907cf6b-fd58-495e-997d-dce997c11b28", "episode_id": "1fe39ccf-fc9c-4d58-a297-b44f0d5bab00", "cms_item_id": "68225dfc7bb476527f8c491a", "chunk_index": 0, "content": "Cole Heilborn (00:00.238): When I say the golden days of brand storytelling is dead and over, what I mean to say is you have to fight and justify that work tenfold compared to what it used to be like. Brands are not so easily green lighting a one -off 10 -minute short doc. There needs to be a viewer experience, there needs to be a funnel of engagement, there needs to be a tangible point of sale. It's forcing me and my team to come up with strategic solutions of how we're packaging these short branded films. Welcome to the Backcountry Marketing Podcast. I'm your host, Cole Howland. On this podcast, you'll hear from leaders in the outdoor marketing industry discuss the gritty details of their work, as well as the latest challenges and lessons that are running along the way. If you want to hone your craft and become a stronger marketer, then this podcast is for you. This podcast is produced by Portside Productions, an outdoor film production company based in the Pacific Northwest. If you work at a brand or agency in the outdoor industry that needs help bringing in video project to life, head over to portsidepro .com and send us an email. We'd love to help. Welcome to the Backcountry Marketing Podcast. Today I'm sitting down with Lindsay Hagen. She is a documentary filmmaker and head of development at Gnarly Bay. Lindsay, how are you? Hi, hi Cole. I'm doing well. Thanks for having me. Yeah, thanks for being here. I've got to say it's quite an honor to have you on the show. I feel like I've been following your work for many years and on my YouTube great video playlist that I add amazing work to, you have at least three pieces on that playlist. So it's exciting to get the chat with you today. That's really cool. Thank you. Likewise. I'm thrilled. So my first question for you, you've told a lot of stories. You've been doing this for quite some time and I'm curious, have we commoditized storytelling? And if it is commoditized, have we devalued stories today? Ooh, you're starting with a real gut punch. Um, well, you're asking the right person because I definitely think about this a lot. Um, especially because I started off in the branded storytelling space and it's kind of the world that I've continued to exist in for the past six or seven years. Have we started to devalue? Um, I think there's a threshold and definitely a gray area. And it's something that when you bring brand partners onto documentary storytelling, I think we have to be very aware of.", "token_estimate": 622, "speakers": ["Cole Heilborn"], "start_timestamp": "00:00.238", "end_timestamp": "00:00.238", "podcast_index": 145, "episode_name": "EP: 145 The Golden Age of Branded Films is Dead | Lindsey Hagen | gnarlybay", "slug": "ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "web_url": "https://www.portsidepro.com/podcast-feed/ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "guest_name": "Lindsey Hagen", "guest_title": "Head of Development at Gnarlybay", "categories": ["creative", "brand"], "short_description": "Simply uploading a video to YouTube and expecting hundreds of thousands of people to watch are days of the past. I’ve always said that 50% of the work is making the film, and the other 50% is marketing it. Without a strategic distribution plan, your film is likely to flop. As we look at the industry today, brands are cutting marketing budgets and these types of one-story-telling films are often the first to go. If there isn’t a direct result in sales it’s hard to quantify the impact these types of projects have.", "podcast_length": "56:00"}, {"id": "d85cb59a-462f-4207-8f49-d5f1b19bd66b", "episode_id": "1fe39ccf-fc9c-4d58-a297-b44f0d5bab00", "cms_item_id": "68225dfc7bb476527f8c491a", "chunk_index": 1, "content": "Cole Heilborn (02:20.75): is this idea of guardrails. As a storyteller, if you're working on a documentary film and you take that out to market, I think it's really important to identify those guardrails where you are and aren't willing to go, what the subject is comfortable with before you ever take anything out to market. There is a very real chance that if you don't put those stops in place, you could take a documentary work and basically just sell out. And at that point, we might as well be making a commercial. So I hope that answers your question, but my answer is as documentary storytellers, as filmmakers, if you are going to be doing documentary work in the branded space, I do think you have to be very vigilant and do your due diligence to keep your story intact and unhindered. And that really comes down to just level setting with the client upfront, knowing where you are and aren't willing to go before you get roped into something where then you end up having like product plastered all throughout your film or... you end up in a situation where, you know, a client is asking you to ask the subject something that maybe isn't authentic or true to them. So you really have to do your due diligence and advocate for the subject matter upfront. So you've been telling stories for quite some time now. You've had a number of films, win festivals, numerous Vimeo staff picks. You've had a project nominated for an Oscar. Over all these projects that you've worked on, I'm curious, how has your role as a storyteller evolved and what guardrails do you give yourself? So I started in film actually as an executive producer. I came into the film space, which is a crazy thing to say. Most people start as a producer, a PA, and work their way up. So I realized that's like so atypical. I didn't go to film school. I studied speech language and hearing science. I worked in adaptive sports. It's a very roundabout way of getting into film. But I started, like I said, as an executive producer. I came from a background in sales, marketing, and brand strategy. I worked at a PR firm in Boston for some time. I worked at a ski and snowboard magazine. So that brings us to this podcast, Backcountry. I learned how to do sales in the outdoor industry and all of my clients while I was working at this magazine, unfortunately started transitioning from wanting to do print media spends to branded content and video, like video storytelling. And at the time that was very new. That was back in...", "token_estimate": 626, "speakers": ["Cole Heilborn"], "start_timestamp": "02:20.75", "end_timestamp": "02:20.75", "podcast_index": 145, "episode_name": "EP: 145 The Golden Age of Branded Films is Dead | Lindsey Hagen | gnarlybay", "slug": "ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "web_url": "https://www.portsidepro.com/podcast-feed/ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "guest_name": "Lindsey Hagen", "guest_title": "Head of Development at Gnarlybay", "categories": ["creative", "brand"], "short_description": "Simply uploading a video to YouTube and expecting hundreds of thousands of people to watch are days of the past. I’ve always said that 50% of the work is making the film, and the other 50% is marketing it. Without a strategic distribution plan, your film is likely to flop. As we look at the industry today, brands are cutting marketing budgets and these types of one-story-telling films are often the first to go. If there isn’t a direct result in sales it’s hard to quantify the impact these types of projects have.", "podcast_length": "56:00"}, {"id": "5f33a4d7-2abe-4e83-bd5e-1baf6c5fc4eb", "episode_id": "1fe39ccf-fc9c-4d58-a297-b44f0d5bab00", "cms_item_id": "68225dfc7bb476527f8c491a", "chunk_index": 2, "content": "Cole Heilborn (04:46.35): Gosh, like 2013, 2014, all my clients wanted video. I couldn't offer them a solution for what they were asking for. And I had these really wonderful relationships. At the time, I think I had like 400 clients in the outdoor industry. I was constantly in touch with. So that helped me make the jump into film was basically servicing my clients and helping them achieve what they wanted, which is storytelling. And that's where my heart was. Documentary was always something I really cared deeply about human rights, social impact, environmental. I started at a company called Steph Studios. I knew them from the ski industry, actually. They started off making amazing ski films. I was like a total follower. I loved their films. I used to go to all the screenings on campus at CU. They had moved on to Los Angeles and they were opening their first little office space. We were just getting started and I jumped in headfirst. I knew how to do sales. I knew how to package projects and campaigns. I knew nothing about film. So they really taught me like everything, all the basics. And I just, I hustled really, really hard. And when I was starting with them, I was living in Boulder, Colorado. The company was based in LA. I wasn't ready to leave the mountains and I would fly out every two weeks and sleep under the edit bay on a little blowup mattress. Eventually I got like a beater bike so I could at least bike around LA. And then from there I graduated to a, a van and I lived out of my Astro van on the streets of. LA outside the office and I'd have to rotate where I parked my van like every three days for street cleaning. So I graduated into this EP role, cut my teeth in sales and what that meant for selling films. I was going to take someone's story out for sale, out to brand partners. I wanted to ensure that I could protect their story and really keep their value intact. So I wanted to start directing. I had no experience directing. I was passionate as hell. I was often the girl brought to tears at the office just because I was so passionate. Amazing. That's awesome to see the trajectory of where you've been and where you're going. What do you enjoy most about your job today? What about storytelling is something that you're passionate about? I mean, storytelling is the most human thing we do. It's the way to connect with one another. It's a way to con...", "token_estimate": 601, "speakers": ["Cole Heilborn"], "start_timestamp": "04:46.35", "end_timestamp": "04:46.35", "podcast_index": 145, "episode_name": "EP: 145 The Golden Age of Branded Films is Dead | Lindsey Hagen | gnarlybay", "slug": "ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "web_url": "https://www.portsidepro.com/podcast-feed/ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "guest_name": "Lindsey Hagen", "guest_title": "Head of Development at Gnarlybay", "categories": ["creative", "brand"], "short_description": "Simply uploading a video to YouTube and expecting hundreds of thousands of people to watch are days of the past. I’ve always said that 50% of the work is making the film, and the other 50% is marketing it. Without a strategic distribution plan, your film is likely to flop. As we look at the industry today, brands are cutting marketing budgets and these types of one-story-telling films are often the first to go. If there isn’t a direct result in sales it’s hard to quantify the impact these types of projects have.", "podcast_length": "56:00"}, {"id": "b211e0d0-e249-4aa6-8891-39cb80691dc1", "episode_id": "1fe39ccf-fc9c-4d58-a297-b44f0d5bab00", "cms_item_id": "68225dfc7bb476527f8c491a", "chunk_index": 3, "content": "Cole Heilborn (07:12.11): convey deep emotions. You know, written storytelling is also amazing in its own right, but what I love about visual storytelling is the way that it can really grab at your emotions. The way music can like pull at that feeling and maybe you can't quite describe or put a word to it, but seeing something on a screen paired with moving imagery and music, it's just the most like emotional. way to I think connect and empathize with the subject matter that you may have no connection to otherwise. I love creating emotional connections with the viewer and I love identifying stories that can help us bridge a gap and realize that we are not so different as we appear on paper and when we get to those deeper sentiment, those deeper human values. Really, like I want the work that I do to help connect us. Well, that kind of segues into our conversation for today. And, you know, we're talking about the importance of stories and maybe how stories are being told today and some of the challenges with telling branded stories. When we first got connected, I think one of the first things you said to me was that the golden age of branded films are dead. And that's kind of our headline for today, what we're going to be diving into. And, and I'm curious, uh, what do you mean by that? What observations? have you been making and we'll kind of dig into this throughout the conversation. But I guess why is this a conversation that you're passionate about? What are you seeing today that led you to kind of this idea or this statement? Gosh, I sound so doomsday, but I think it is a reflection of some of what I've been seeing. I mean, post -COVID, brands are reeling back their marketing budgets. They're having to really justify where they're spending their money and it is ultimately just coming down to ROI. So... When I say the golden days of branded storytelling is dead and over, what I mean to say is you have to fight and justify that work tenfold compared to what it used to be like. Brands are not so easily green lighting a one -off, 10 -minute short doc. There needs to be a viewer experience. There needs to be a funnel of engagement. There needs to be a tangible point of sale at some point within the matrix of deliverables that you're creating.", "token_estimate": 570, "speakers": ["Cole Heilborn"], "start_timestamp": "07:12.11", "end_timestamp": "07:12.11", "podcast_index": 145, "episode_name": "EP: 145 The Golden Age of Branded Films is Dead | Lindsey Hagen | gnarlybay", "slug": "ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "web_url": "https://www.portsidepro.com/podcast-feed/ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "guest_name": "Lindsey Hagen", "guest_title": "Head of Development at Gnarlybay", "categories": ["creative", "brand"], "short_description": "Simply uploading a video to YouTube and expecting hundreds of thousands of people to watch are days of the past. I’ve always said that 50% of the work is making the film, and the other 50% is marketing it. Without a strategic distribution plan, your film is likely to flop. As we look at the industry today, brands are cutting marketing budgets and these types of one-story-telling films are often the first to go. If there isn’t a direct result in sales it’s hard to quantify the impact these types of projects have.", "podcast_length": "56:00"}, {"id": "360e9b65-2fdf-4268-a2f4-5ababca013b4", "episode_id": "1fe39ccf-fc9c-4d58-a297-b44f0d5bab00", "cms_item_id": "68225dfc7bb476527f8c491a", "chunk_index": 4, "content": "Cole Heilborn (09:26.862): So I think it's forcing me as a head of development, as someone who's coming up with strategy and packaging for these short documentaries, it's forcing me and my team to come up with strategic solutions with how we're packaging these short branded films and what that distribution rollout looks like and how the viewer experience reflects that rollout. Do you remember kind of what year or what time timeframe it was when branded films really took over? Like it was a buzzword for quite some time and like everyone was jumping on the bandwagon and trying to create branded films. When was that? I mean, I'd love to look at Yeti's YouTube channel and see, but I would say, I mean, I was selling branded films in 2014, 2015. It for me kind of felt like the start of it, but that was just when I got started. But I remember back then it was as simple as here's your 10 minute short doc, you're going to put it on your YouTube or your Vimeo and here's a trailer. And... I think what we've seen is we gotta work harder. There's no guarantee that anyone's gonna see the film on YouTube, there's no guarantee that anyone's gonna see it on Vimeo. And if your social content isn't working hard for you, if you're not putting paid ad spends behind it, if there's not a CTA, a call to action or a direct click through, it's just getting lost. There's just so much out there. I think brands are also realizing this, that they really need to come up with a ideal user experience and really understand what their ROI is. Like, how are they defining success for each of these film assets and accompanying campaigns? So it has changed in the sense that these are more multifaceted campaigns that revolve around a storytelling moment. Do you feel like branded films back in the day were kind of viewed as a superfood? It's like, if you make one of these things, like all of these amazing benefits will happen. I was reading this article about kind of this idea and it was talking about how back in the day, like brands would just, you know, we'd make films, we'd throw them up there and it's kind of like build it and they will come mentality. What was the mentality around branded films? Why were they so popular? And I guess I'm saying this in past tense as in like, you know, 2013, 2014. There was a shift, I think with the audience.", "token_estimate": 587, "speakers": ["Cole Heilborn"], "start_timestamp": "09:26.862", "end_timestamp": "09:26.862", "podcast_index": 145, "episode_name": "EP: 145 The Golden Age of Branded Films is Dead | Lindsey Hagen | gnarlybay", "slug": "ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "web_url": "https://www.portsidepro.com/podcast-feed/ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "guest_name": "Lindsey Hagen", "guest_title": "Head of Development at Gnarlybay", "categories": ["creative", "brand"], "short_description": "Simply uploading a video to YouTube and expecting hundreds of thousands of people to watch are days of the past. I’ve always said that 50% of the work is making the film, and the other 50% is marketing it. Without a strategic distribution plan, your film is likely to flop. As we look at the industry today, brands are cutting marketing budgets and these types of one-story-telling films are often the first to go. If there isn’t a direct result in sales it’s hard to quantify the impact these types of projects have.", "podcast_length": "56:00"}, {"id": "5f89edb6-1ad8-44d5-9abf-dc0b9261a72f", "episode_id": "1fe39ccf-fc9c-4d58-a297-b44f0d5bab00", "cms_item_id": "68225dfc7bb476527f8c491a", "chunk_index": 5, "content": "Cole Heilborn (11:46.574): viewers were wanting to get behind something meaningful. And I think a lot of viewers started feeling pretty jaded. You know, all the products on the market are essentially the same. It's like, what are the brand ethos that differentiate you? Like, why would you shop a brand like Patagonia who you know has a great footprint environmentally and great social impact? And, you know, from everything that you see in the public eye, I think viewers are becoming much more vigilant. with the brands that they engage with based on the company ethos. And maybe it's because there's other factors that we can't control right now. Certain things with climate change are just plain upsetting and COVID was upsetting and there's certain decisions that you can control. I think consumerism is one of those things that you have a choice in. So it feels good to align with companies, brands who are doing good, who are sharing positive stories, who are uplifting community members. So in a weird way, it's like, well, things in the environment and the sphere aren't going well. It makes the viewer more vigilant with what they can control and help, um, you know, perpetuate some, some positivity. So that's how I justify it. That's how I felt personally as a consumer. Do you feel like that's changing? Do we care about the ethos of a company more or less than we did 10 years ago as an audience, as consumers? I think more. Yeah. I think there is a feeling of a little bit of helplessness. uh, living in the world today. So if there's a way to feel a little bit less helpless and if there's a brand who's more transparent about their practices and you know, at the end of the day, putting your dollars towards something, if that can help a little bit or there's a brand that helps justify that spend, it helps, you know, it helps me feel a little bit better. So I guess where's the disconnect if branded films help bridge these gaps between a brand's ethos and consumers. I guess what you're saying is like, you're seeing brands rolling back. are cutting back on these types of projects, these types of budgets, because they need to see more of a direct return on these things. I guess, why is that? Why are we seeing that trend right now? I think COVID was tough. Everything I'm hearing is marketing budgets are just getting slashed. So while storytelling and brand ethos is still super important, they need to like, they need to hit their sales goals. Just like we need to hit our sales goals to keep our businesses open.", "token_estimate": 635, "speakers": ["Cole Heilborn"], "start_timestamp": "11:46.574", "end_timestamp": "11:46.574", "podcast_index": 145, "episode_name": "EP: 145 The Golden Age of Branded Films is Dead | Lindsey Hagen | gnarlybay", "slug": "ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "web_url": "https://www.portsidepro.com/podcast-feed/ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "guest_name": "Lindsey Hagen", "guest_title": "Head of Development at Gnarlybay", "categories": ["creative", "brand"], "short_description": "Simply uploading a video to YouTube and expecting hundreds of thousands of people to watch are days of the past. I’ve always said that 50% of the work is making the film, and the other 50% is marketing it. Without a strategic distribution plan, your film is likely to flop. As we look at the industry today, brands are cutting marketing budgets and these types of one-story-telling films are often the first to go. If there isn’t a direct result in sales it’s hard to quantify the impact these types of projects have.", "podcast_length": "56:00"}, {"id": "210d3327-6139-435f-8626-67f7f07c75eb", "episode_id": "1fe39ccf-fc9c-4d58-a297-b44f0d5bab00", "cms_item_id": "68225dfc7bb476527f8c491a", "chunk_index": 6, "content": "Cole Heilborn (14:12.558): So I don't think the ethos driven films are dying. I think they just need to be fully insulated with a campaign that really helps push them, either the messaging or the product integration or whatever your call to action is. They're, they can't just stand on their own anymore. Yeah. What, what problem do brands have if they make a branded film today? Would you say that if you had to take a poll of everyone who made a branded film and everyone who published it, what? Is it living up to the expectations that the brand is looking for or are most of them falling short of the potential? I think there's some confusion with what that transition looks like. Okay. And what I'm seeing is brands are realizing we can't just be making short films and putting them on YouTube anymore, but we don't quite know how to bridge the gap. And so what I've tried to do is come up with... strategy and solutions to help justify ROI. So if we're going to go tell a short film or go tell a short story, let's derive a commercial from that short doc. What's your 60 second commercial? What's your product launch that tees up with the storytelling moment? Is there any opportunity for a festival run? Are you trying to impact grassroots communities really? brands need to start asking what their end goal is. Why are we making the content? Who do we want it to see? And what do we want them to do about it? Are we asking them to purchase something? Is this film tied to a product launch? Is it tied to a sustainability effort? I think asking those questions earlier on before we even start talking about what the film we're making or the cool story, it's like, no, no, no. What do we want people to do and why? and then you retrofit the whole campaign to match that. Got it. So your job is no longer just a filmmaker. You've got a number of other hats that you're wearing, just trying to get to your job as a filmmaker. Oh, yeah, totally. No, I'm I'm like barely out in the field anymore. And I've said this a handful of times to other filmmakers in the space, like I'm having work 10 times harder for the same amount of sell through. And I like I like the challenge. I actually like strategy. I like.", "token_estimate": 553, "speakers": ["Cole Heilborn"], "start_timestamp": "14:12.558", "end_timestamp": "14:12.558", "podcast_index": 145, "episode_name": "EP: 145 The Golden Age of Branded Films is Dead | Lindsey Hagen | gnarlybay", "slug": "ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "web_url": "https://www.portsidepro.com/podcast-feed/ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "guest_name": "Lindsey Hagen", "guest_title": "Head of Development at Gnarlybay", "categories": ["creative", "brand"], "short_description": "Simply uploading a video to YouTube and expecting hundreds of thousands of people to watch are days of the past. I’ve always said that 50% of the work is making the film, and the other 50% is marketing it. Without a strategic distribution plan, your film is likely to flop. As we look at the industry today, brands are cutting marketing budgets and these types of one-story-telling films are often the first to go. If there isn’t a direct result in sales it’s hard to quantify the impact these types of projects have.", "podcast_length": "56:00"}, {"id": "22640434-5668-4706-97d9-dd6bcb1b51f3", "episode_id": "1fe39ccf-fc9c-4d58-a297-b44f0d5bab00", "cms_item_id": "68225dfc7bb476527f8c491a", "chunk_index": 7, "content": "Cole Heilborn (16:33.422): understanding what the distribution is going to look like. And I like asking those questions upfront because I feel like ultimately it's going to deliver a more robust campaign and film activation. So it's changed the way that I talk about, you know, film development. It's changed the way I go about sales. Their goals come first and then putting together a story that best aligns with those goals comes second. Where in the past I would just spray stories out to brands I thought were good partners. But I need to understand their marketing goals. I need to understand their ROI needs first and then see how I could retrofit a campaign to their needs. Interesting. Has that been a hard transition for you to kind of flip the script or flip the approach? We've had to really develop our sales materials. So case studies, even mock case studies, proof of concept so that these clients, our brand partners can see what something looks like before we actually go put in the production time and dollars to make it. Yeah, it's it's been really fun. I've actually really enjoyed the process. And it's been a good learning challenge for our development team to start really thinking thinking more like our brand partners thinking more like an extension of the brands we work with. What does a mock case study look like? Can you share? Sure. So essentially, is me being like, if I were to make this film and the accompanying campaign, this is what it would look like. And we will literally mock up all the deliverables, the entire distribution flow, um, we'll mock up what the landing page looks like, what the point of sale integration looks like. It's kind of like if you were to do your case study on the front end. Wow. Dang. Uh, that's a lot of work. Yeah. Our team was like, we took a good solid, like that past three months, just developing a bunch of these, like mock mock case studies. Interesting and that seems to work like do brands need to kind of see everything packaged and pre -built for them or can they connect the dots themselves if you just hand them the pieces? It just depends and where I've always been very proactive is this idea of kind of delivering a menu before they're asking for it. Because I think it's a great way to help solve problems.", "token_estimate": 573, "speakers": ["Cole Heilborn"], "start_timestamp": "16:33.422", "end_timestamp": "16:33.422", "podcast_index": 145, "episode_name": "EP: 145 The Golden Age of Branded Films is Dead | Lindsey Hagen | gnarlybay", "slug": "ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "web_url": "https://www.portsidepro.com/podcast-feed/ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "guest_name": "Lindsey Hagen", "guest_title": "Head of Development at Gnarlybay", "categories": ["creative", "brand"], "short_description": "Simply uploading a video to YouTube and expecting hundreds of thousands of people to watch are days of the past. I’ve always said that 50% of the work is making the film, and the other 50% is marketing it. Without a strategic distribution plan, your film is likely to flop. As we look at the industry today, brands are cutting marketing budgets and these types of one-story-telling films are often the first to go. If there isn’t a direct result in sales it’s hard to quantify the impact these types of projects have.", "podcast_length": "56:00"}, {"id": "1f1727b5-10b4-428b-9e1f-e5a7a6398fdc", "episode_id": "1fe39ccf-fc9c-4d58-a297-b44f0d5bab00", "cms_item_id": "68225dfc7bb476527f8c491a", "chunk_index": 8, "content": "Cole Heilborn (18:58.574): and deliver your services as a resource and a problem solved that maybe they don't have the bandwidth internally to solve because they need to meet their overhead. Yeah. You mentioned that COVID has played a role in getting to where we are today. Do you feel like social media has played a role at all in kind of the demise of branded films, if you will? I was so jaded about social media influencers for the longest time, and I think they've kind of like leveled out a little bit. Yes, social media, certainly. I mean, the algorithm is changing constantly. For example, if you put a teaser up for a short doc on Instagram, but you don't give any context around the campaign or why the brand is sharing that teaser, it just gets lost in the feed. So I think you really need to approach social media differently than your traditional storytelling platform. It needs to be like, cutty, easily digestible, text on screen. There has to be a very direct... action or a request for the viewer at the end. Yeah, it's constantly changing. So we're not really putting like trailers for films out on social anymore. We're trying to put like an anthem or even a commercial, something that's a little more engaging. And I'm also trying to avoid social media influencers. Interesting. Okay. Huh. So you won't even put a trailer out. You'll you'll put something very specific. specifically cut for social to push people? Are you trying to push them to a film screening or a landing page somewhere? I guess it probably depends. Yeah, a landing page, point of sale, if there is a product integration. For certain bike companies, for example, those social cuts are going to do a lot better if there's a bike or a gear integration tied into it. And then once you bring them to that page where they can learn more about the product, there's your story all living within that landscape. So I think just knowing where your audience goes to digest certain content and not like hitting them over the head with something that they're just not ready to digest. So here's another thing that I've been wondering about. When I look at the subscriber count for a place, a YouTube channel like Red Bull or Yeti, the subscriber count is significantly less than that of an individual YouTuber.", "token_estimate": 572, "speakers": ["Cole Heilborn"], "start_timestamp": "18:58.574", "end_timestamp": "18:58.574", "podcast_index": 145, "episode_name": "EP: 145 The Golden Age of Branded Films is Dead | Lindsey Hagen | gnarlybay", "slug": "ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "web_url": "https://www.portsidepro.com/podcast-feed/ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "guest_name": "Lindsey Hagen", "guest_title": "Head of Development at Gnarlybay", "categories": ["creative", "brand"], "short_description": "Simply uploading a video to YouTube and expecting hundreds of thousands of people to watch are days of the past. I’ve always said that 50% of the work is making the film, and the other 50% is marketing it. Without a strategic distribution plan, your film is likely to flop. As we look at the industry today, brands are cutting marketing budgets and these types of one-story-telling films are often the first to go. If there isn’t a direct result in sales it’s hard to quantify the impact these types of projects have.", "podcast_length": "56:00"}, {"id": "1a27305b-b779-47ce-b321-e2085aacd315", "episode_id": "1fe39ccf-fc9c-4d58-a297-b44f0d5bab00", "cms_item_id": "68225dfc7bb476527f8c491a", "chunk_index": 9, "content": "Cole Heilborn (21:22.798): When I look at YouTube channels and I look at the subscriber count and the audience base, it's very different between individuals and brands. And I've been asking this question, like, do brands, do people want to hear from brands? Because everyone talks about Yeti as an amazing example of a brand who's built an incredible following on YouTube. But based on their subscriber count, it's only like 149 ,000, which is nothing compared to the hundreds of millions that. you know, famous YouTubers have. And so what role do you feel like the brand has? Do they have a place? Should they have their own audience? Do people want to hear directly from them? Is that changing these days? Or I guess I'm just looking at numbers and I feel like there's a question there. Yeah, that's a great question. I mean, at the end of the day, the people there's behind all these brands are people. Brands have human values. Brands are run by people. Marketing campaigns are run. by sentient beings who have this emotional connection and understanding of the world. So I think it's in our best interest, the people behind the brands to keep it human. And the brands that I really resonate with are the ones that are wearing their values, you know, on their sleeve. And I feel more connected to them as a participant, as a viewer, as a consumer. So. I think, you know, I as a consumer, I want brands to stand for something. I don't want them to just like sit back on their haunches like status quo and coast knowing that they're making, you know, they're pocketing a bunch of cash. Like I want brands to continue to raise the bar from an ethos standpoint. And I actually am seeing more pressure. in the branded space amongst some of the top contributors to continue to raise that bar. So I'm not sick of hearing from brands. In fact, I want them to continue to up the ante and use their marketing campaigns or their foundations and funds to do good work. And I want to know about it as a consumer. What do you mean by pressure? What sort of what are you seeing?", "token_estimate": 517, "speakers": ["Cole Heilborn"], "start_timestamp": "21:22.798", "end_timestamp": "21:22.798", "podcast_index": 145, "episode_name": "EP: 145 The Golden Age of Branded Films is Dead | Lindsey Hagen | gnarlybay", "slug": "ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "web_url": "https://www.portsidepro.com/podcast-feed/ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "guest_name": "Lindsey Hagen", "guest_title": "Head of Development at Gnarlybay", "categories": ["creative", "brand"], "short_description": "Simply uploading a video to YouTube and expecting hundreds of thousands of people to watch are days of the past. I’ve always said that 50% of the work is making the film, and the other 50% is marketing it. Without a strategic distribution plan, your film is likely to flop. As we look at the industry today, brands are cutting marketing budgets and these types of one-story-telling films are often the first to go. If there isn’t a direct result in sales it’s hard to quantify the impact these types of projects have.", "podcast_length": "56:00"}, {"id": "688400e5-99d3-410d-b630-722e5c7b56f2", "episode_id": "1fe39ccf-fc9c-4d58-a297-b44f0d5bab00", "cms_item_id": "68225dfc7bb476527f8c491a", "chunk_index": 10, "content": "Cole Heilborn (23:41.614): I mean, you see brands like REI and Patagonia constantly carrying the torch, you know, and just making bold stands, especially within the outdoor industry. And I think that creates a ripple effect. We live in this consumer society, capitalist society, and if brands can be the ones to help drive and spearhead change, I think it'll have a societal ripple effect. We've already seen it. There's so much control. Um, so many marketing budgets and, and revenue streams, there is a, there's a way to use all of that for good. And that is the gap I'm constantly trying to bridge with branded storytelling is identifying what good these brands have the potential to bring to the world. And let's use those marketing dollars to do so in a way that still helps the brand get paid, helps them sell through their products. But. Let's talk about the good work you're doing. Let's talk about the potential for good and keep moving things in a progressive direction through storytelling. I don't know if I agree with this, but do you feel like the industry is telling too many stories? Is the audience overwhelmed with the amount of stories that they can consume? And I guess the reason I'm curious about to hear your answer is because like I hear oftentimes from brands and you know, businesses all over, like they have an incredible story. They have an incredible why they're doing amazing work. And then they tell their story, whether it's through a video or a film or a journal, an article, and it gets, you know, it's crickets. There's like, there's zero response. And it can be the most groundbreaking story that that's ever been told, but no one pays attention. No one cares. I'm sure there's multiple factors at play there, but are we inundated with stories to the point where we're just at capacity, like we can't take on anymore? Yeah. That's a great question. Because it is such a competitive market and there are so many brands wanting to tell stories, I think we as filmmakers and on the brand side really have to ask ourselves, is there entertainment value to this story? If I were to send this out to organic media partners looking for organic media placement, can this story stand on its own as a story first? Or is this just a profile piece that aligns with?", "token_estimate": 573, "speakers": ["Cole Heilborn"], "start_timestamp": "23:41.614", "end_timestamp": "23:41.614", "podcast_index": 145, "episode_name": "EP: 145 The Golden Age of Branded Films is Dead | Lindsey Hagen | gnarlybay", "slug": "ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "web_url": "https://www.portsidepro.com/podcast-feed/ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "guest_name": "Lindsey Hagen", "guest_title": "Head of Development at Gnarlybay", "categories": ["creative", "brand"], "short_description": "Simply uploading a video to YouTube and expecting hundreds of thousands of people to watch are days of the past. I’ve always said that 50% of the work is making the film, and the other 50% is marketing it. Without a strategic distribution plan, your film is likely to flop. As we look at the industry today, brands are cutting marketing budgets and these types of one-story-telling films are often the first to go. If there isn’t a direct result in sales it’s hard to quantify the impact these types of projects have.", "podcast_length": "56:00"}, {"id": "1a318fe1-bd83-48ff-979e-eea7a84be415", "episode_id": "1fe39ccf-fc9c-4d58-a297-b44f0d5bab00", "cms_item_id": "68225dfc7bb476527f8c491a", "chunk_index": 11, "content": "Cole Heilborn (26:02.926): so -and -so's values when it ties to sustainability. So I think brands need to look at the entertainment value. Can this film or story stand on its own outside of their built -in audience? And if it can, then you have potential for a really compelling film that can break the mold, that can go on to have festival success, that can go on to have an educational distribution, potentially get organic media placement or acquisition with a streamer. I think... constantly weighing, um, weighing like entertainment versus like just a direct branded film, um, is really important. So you feel like there's a, the missing X factor is this entertainment component. Not many pieces in your perspective have this entertainment piece. Is that, is that what you're seeing? I think if brands are only thinking about targeting their existing audience, that project can only go so far. For example, A brand like Nike. If you're going to be telling a football story, does that story have potential to resonate with an audience who maybe has never played football, has no interest in the sport of football, but maybe there's a compelling human narrative or a coming of age story, some sort of adversity or hero's journey that they can relate to, or is it timely? Is there a timely event that can help broaden the audience? If you have the ability to entertain and broaden your endemic audience. then that has the makings for a piece that can kind of break the mold. Otherwise just make a commercial or make your short doc, but then have all your auxiliary assets that are going to best serve your ROI needs. Interesting. So from a storytelling perspective, what are some elements of a story that makes it entertaining, that kind of takes it that, you know, that extra 10 % that turns it into a really incredible piece? Like what are you looking for in the writing room as you're working on pieces? I think you need to look at the current landscape. Like, why is this story relevant now? Am I the best storyteller? Am I the most suited to tell this story? If not, who are your collaborators that have the insight who can really make this more more intimately connected through their own lived experience? Yeah, is there a timely event that it attaches to? Like, everything needs to be like timely.", "token_estimate": 577, "speakers": ["Cole Heilborn"], "start_timestamp": "26:02.926", "end_timestamp": "26:02.926", "podcast_index": 145, "episode_name": "EP: 145 The Golden Age of Branded Films is Dead | Lindsey Hagen | gnarlybay", "slug": "ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "web_url": "https://www.portsidepro.com/podcast-feed/ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "guest_name": "Lindsey Hagen", "guest_title": "Head of Development at Gnarlybay", "categories": ["creative", "brand"], "short_description": "Simply uploading a video to YouTube and expecting hundreds of thousands of people to watch are days of the past. I’ve always said that 50% of the work is making the film, and the other 50% is marketing it. Without a strategic distribution plan, your film is likely to flop. As we look at the industry today, brands are cutting marketing budgets and these types of one-story-telling films are often the first to go. If there isn’t a direct result in sales it’s hard to quantify the impact these types of projects have.", "podcast_length": "56:00"}, {"id": "131b0461-24ab-44ac-875a-35668b545ef8", "episode_id": "1fe39ccf-fc9c-4d58-a297-b44f0d5bab00", "cms_item_id": "68225dfc7bb476527f8c491a", "chunk_index": 12, "content": "Cole Heilborn (28:33.454): and current, even if you're telling a story that took place in the past, what is the present day hook? So I think having a present day hook, empowering filmmakers who most closely resonate with the subject matter is always going to help the story shine brighter. And having a suite of assets that help insulate the piece, to help build out a user experience, making sure that there's a robust distribution plan and that your piece has to be entertaining. No one wants to watch talking head interviews and text on screen and like, yeah, factory macro shots. And there's a place for that, but maybe it's your B2B videos. Gotcha. Yeah. What do you think makes stories relatable? What elements of a story makes me want to connect with a story that you've made? I mean, I always just lean into emotion. I think emotion beyond words is how we connect with one another. There's that feeling like... Ultimately, when I watch a piece, if I get that feeling in my chest or my stomach, whether it's elation or sadness or joy or nostalgia, if there's a feeling, like that's the best way for me to describe it. And that is what I think differentiates really good filmmaking is attaining that feeling. Or maybe someone doesn't even know why they have, why their gut is it not, or why their heart's pounding, but they felt something. And so that's gonna... carry over into a conversation or potentially become a film that they share, or it's going to, in fact, impact how they engage with the world or the next person they see on the street. So I know that's kind of vague, but I guess that's the creative side of me. Like you're really just trying to tap into a feeling that changes the way that people engage with the world. I mean, it, it might be vague, but I think it makes a ton of sense. And I feel like as I've wrestled with these questions, like that's what I ultimately come back to. It's like, if I'm going to watch something, I want to be emotionally invested. Like I want to be. overwhelmed and captivated by the emotion. And if it's not happening, then I just don't care. Like I want to move on to the next thing. And that's difficult to accomplish. That takes a lot of effort and a lot of skill in order to actually create that emotion. Yeah, totally. And I think, I mean, coming from the outdoor filmmaking space, like there's so many projects that are objective based, you know, climbing that mountain, skiing that first descent. But I'm...", "token_estimate": 618, "speakers": ["Cole Heilborn"], "start_timestamp": "28:33.454", "end_timestamp": "28:33.454", "podcast_index": 145, "episode_name": "EP: 145 The Golden Age of Branded Films is Dead | Lindsey Hagen | gnarlybay", "slug": "ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "web_url": "https://www.portsidepro.com/podcast-feed/ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "guest_name": "Lindsey Hagen", "guest_title": "Head of Development at Gnarlybay", "categories": ["creative", "brand"], "short_description": "Simply uploading a video to YouTube and expecting hundreds of thousands of people to watch are days of the past. I’ve always said that 50% of the work is making the film, and the other 50% is marketing it. Without a strategic distribution plan, your film is likely to flop. As we look at the industry today, brands are cutting marketing budgets and these types of one-story-telling films are often the first to go. If there isn’t a direct result in sales it’s hard to quantify the impact these types of projects have.", "podcast_length": "56:00"}, {"id": "1efb53db-1e25-478d-9223-f980bbc54274", "episode_id": "1fe39ccf-fc9c-4d58-a297-b44f0d5bab00", "cms_item_id": "68225dfc7bb476527f8c491a", "chunk_index": 13, "content": "Cole Heilborn (30:57.038): really fascinated with the why, like the internal processes, the emotional why, the why it is that people are doing what they do, what circumstances brought them to this case, like what is the backstory? I'm always fascinated when I meet someone like what is the backstory that made them so convicted in this aspect of their life? What happened to them or what did they have to go through or what did they learn along the way? I think backstories are absolutely fascinating and how it shapes all of us really and how we engage with the world. And then I love the in -between moments. So between that objective, what are the other things going on in your life? Who's the person you're sharing tea with at the teahouse before you go up to your final alpine ascent? Or, I don't know, I just love the, like when you go, you mentioned you just went for a bike trip. Like when I go on a bike ride or a long trip, yes, the bike ride itself is wonderful, but I'm probably gonna be more interested in telling you about, the really unique miner I met on the way who had this crazy story and he's lived up the mountains for the last 30 years or like the amazing burger I got at the outside the gas station. So I think about storytelling in the same way that, you know, when I call my mom and I'm excited about something, it's not usually like the bolded objective. It's the little bits along the way. Do you think we forget about the little moments when it comes to telling stories? Like, do we lose track of those? Yes, I think the nuance can so easily get lost. And nuance is so much of how we connect with people. When you're sitting across the table from someone and you see them fidgeting with their fingernail, if you're observant enough in those situations, you understand either something else on their mind, maybe they're nervous about something, maybe something happened earlier in the day. So I think if you can take that humanity and how we connect with people beyond your everyday life and apply it to your filmmaking. That's where the viewer is smart. Like we are engineered. We're meant to pick up on these human cues. So bringing those cues into your storytelling, I think is really, really important. And it doesn't need to be overt. It should be subtle. So if you had to take off your filmmaker hat and put on your producing distribution marketing hat, which sounds like you do very, very cleanly and very smoothly these days.", "token_estimate": 615, "speakers": ["Cole Heilborn"], "start_timestamp": "30:57.038", "end_timestamp": "30:57.038", "podcast_index": 145, "episode_name": "EP: 145 The Golden Age of Branded Films is Dead | Lindsey Hagen | gnarlybay", "slug": "ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "web_url": "https://www.portsidepro.com/podcast-feed/ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "guest_name": "Lindsey Hagen", "guest_title": "Head of Development at Gnarlybay", "categories": ["creative", "brand"], "short_description": "Simply uploading a video to YouTube and expecting hundreds of thousands of people to watch are days of the past. I’ve always said that 50% of the work is making the film, and the other 50% is marketing it. Without a strategic distribution plan, your film is likely to flop. As we look at the industry today, brands are cutting marketing budgets and these types of one-story-telling films are often the first to go. If there isn’t a direct result in sales it’s hard to quantify the impact these types of projects have.", "podcast_length": "56:00"}, {"id": "1910cf9e-f9c1-47a2-bbc4-a3963dcce782", "episode_id": "1fe39ccf-fc9c-4d58-a297-b44f0d5bab00", "cms_item_id": "68225dfc7bb476527f8c491a", "chunk_index": 14, "content": "Cole Heilborn (33:21.55): It's obviously clear that storytelling still has a place. Emotions still matter. There's still a lot of potential with them. But to come back to your original point of what you're seeing is those tools have to be used and strategically deployed in order to create a real impact in our ROI. So let's kind of dive down that rabbit hole. How do you do that? How do you build a strategy that actually harnesses the power of filmmaking and emotions and turns it into results for the brand? Well, just like any relationship, you need to understand your client on a personal level. You need to understand their challenges, where they've come up short in the past, what the hurdles are for them as a partner, and constantly as a creative outlet, a creative resource, a production partner, think how you can help problem solve. And whether they're paying you for that creative development upfront or not, I think it's always going to be worth your time. You know, rather than just throwing things at the wall and hoping something sticks, it's really going to be helpful to have that insight, understand your brand partner's pain points, any upcoming launches or initiatives that they're working towards and thinking of yourself as an extension of that brand and how you look at stories. So, for example, if I'm working with a brand, that has a new youth empowerment initiative and probably not going to bring them a cycling story around a nine -year -old woman who just cycled around the world. But perhaps there's a youth empowerment angle we can take and do they have any nonprofits they work with? Is there the ability to grow their footprint in the youth demographic? Can we play this in schools all over the country? Can we do an educational distribution run so that, you know, elementary schools can program this? So, I'm really trying to understand their problems, practically come up with solutions through the lens of storytelling, always thinking about the emotional connection. But at the end of the day, I need to understand what they are deeming as a successful return on investment. So I'm building projects based upon their needs and how they're defining success. What are some common ROIs that frequently come up? Are there?", "token_estimate": 565, "speakers": ["Cole Heilborn"], "start_timestamp": "33:21.55", "end_timestamp": "33:21.55", "podcast_index": 145, "episode_name": "EP: 145 The Golden Age of Branded Films is Dead | Lindsey Hagen | gnarlybay", "slug": "ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "web_url": "https://www.portsidepro.com/podcast-feed/ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "guest_name": "Lindsey Hagen", "guest_title": "Head of Development at Gnarlybay", "categories": ["creative", "brand"], "short_description": "Simply uploading a video to YouTube and expecting hundreds of thousands of people to watch are days of the past. I’ve always said that 50% of the work is making the film, and the other 50% is marketing it. Without a strategic distribution plan, your film is likely to flop. As we look at the industry today, brands are cutting marketing budgets and these types of one-story-telling films are often the first to go. If there isn’t a direct result in sales it’s hard to quantify the impact these types of projects have.", "podcast_length": "56:00"}, {"id": "ce516d36-f3c8-4ba2-a853-ca279ddf3e76", "episode_id": "1fe39ccf-fc9c-4d58-a297-b44f0d5bab00", "cms_item_id": "68225dfc7bb476527f8c491a", "chunk_index": 15, "content": "Cole Heilborn (35:47.694): Are there some, some ones that you frequently see? I mean, sometimes it's as simple as brands just need to sell a product. Um, or we're working with a farming group right now and they, they want more young farmers to get involved with farming and sign up for this, um, like young farmer, um, you know, training sessions or, you know, some of these other brands have affiliated nonprofit partners and they just want a call to action at the end of the film and they want folks. to donate to the nonprofit. It really just depends. Of course, we still have brands asking, we want to hit this many views and engagement, we want to see click through. And that, unless you're really doing a targeted paid ad spend, I think it's hard to have those expectations with these brand storytelling pieces. So if you are going to create a short film, let's say there's a new bike. that's coming out and you have a short film that features the bike, but really the film is about a story. Maybe it features one of your athletes. You should have a commercial asset derived from that story. If you already have a film team out on the ground filming, why not just get yourself a 60 second commercial asset while you're at it? And then your social assets should have product integration. Maybe there's a bit of story in there and there should be a paid ad spend behind it. And then you're clicking through to your landing page where your product, launch lives, your film lives there as well. And so while your product is working, is working for you, and people can click and watch the film if they want, they can fall in love with the subject matter. There's also the potential for that film to have a festival run and there's butts in seats waiting to engage with this more emotional, nuanced story. And then you have brand affiliation or potentially you grew your, your your audience because maybe they wouldn't have come to your product launch otherwise, but they've been thinking about getting a bike and now they love you because you told a great story. Are views important? Like that's some, that's often the KPI that folks bring up, you know, it's like, Oh, I want a million views. Is that important? Um, I think it is, but I don't think it necessarily needs to be views on YouTube or views on Vimeo. Um, you know, views can happen. Like I said, educational distributors, festivals, grassroots community organizing.", "token_estimate": 607, "speakers": ["Cole Heilborn"], "start_timestamp": "35:47.694", "end_timestamp": "35:47.694", "podcast_index": 145, "episode_name": "EP: 145 The Golden Age of Branded Films is Dead | Lindsey Hagen | gnarlybay", "slug": "ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "web_url": "https://www.portsidepro.com/podcast-feed/ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "guest_name": "Lindsey Hagen", "guest_title": "Head of Development at Gnarlybay", "categories": ["creative", "brand"], "short_description": "Simply uploading a video to YouTube and expecting hundreds of thousands of people to watch are days of the past. I’ve always said that 50% of the work is making the film, and the other 50% is marketing it. Without a strategic distribution plan, your film is likely to flop. As we look at the industry today, brands are cutting marketing budgets and these types of one-story-telling films are often the first to go. If there isn’t a direct result in sales it’s hard to quantify the impact these types of projects have.", "podcast_length": "56:00"}, {"id": "0c136087-678a-43ee-8042-d9bcb152da70", "episode_id": "1fe39ccf-fc9c-4d58-a297-b44f0d5bab00", "cms_item_id": "68225dfc7bb476527f8c491a", "chunk_index": 16, "content": "Cole Heilborn (38:10.67): And you need to prepare your content to be digestible based on what your audience is willing to give you. So let's not put a long film on social. Let's hit people when they're actually already sitting in seats and ready to engage with the content. And if you do have a 22 minute branded film, what's your four minute cut down that can live on your YouTube channel or live on your product launch page? That's a little more digestible. And what about film festivals? You've had a lot of success with festival awards. What role does the festival play in the distribution campaign for brands? What does it fulfill? What is it? What's the objective of submitting to a festival? I mean, honestly, it's pretty cheap to submit to film festivals. I think it's a great way to grow your audience. It's a great way to, you can target various regions. You can target festivals that focus on different subject matter. Since COVID, virtual film festivals have become way more of a thing, so you actually can hit a larger audience than you ever could have sitting in theater seats. And there is, if you have a film that has emotional depth and it exceeds three minutes, it's probably worth trying the Festival of Root, because that is where your audience is ready to sink into those emotions, or a captive audience. And it's potential for your marketing team to be out in the field meeting people firsthand who this story or subject matter is really resonating with. So again, it comes back to the human level. We did a film this past year where Dickies came on as a partner and having the Dickies team at the festival with us, putting on this skate event for the youth in this local community and sharing. you know, sharing our film story with a community that is very different. Like we did a project that was filmed in Dallas focusing on kind of like food access disparity in food deserts in downtown Dallas. But it was through the lens of skateboarding at a skate park that provides access to fresh produce for the inner city. And we brought that story to Telluride. And those those two scenarios could not be more different.", "token_estimate": 535, "speakers": ["Cole Heilborn"], "start_timestamp": "38:10.67", "end_timestamp": "38:10.67", "podcast_index": 145, "episode_name": "EP: 145 The Golden Age of Branded Films is Dead | Lindsey Hagen | gnarlybay", "slug": "ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "web_url": "https://www.portsidepro.com/podcast-feed/ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "guest_name": "Lindsey Hagen", "guest_title": "Head of Development at Gnarlybay", "categories": ["creative", "brand"], "short_description": "Simply uploading a video to YouTube and expecting hundreds of thousands of people to watch are days of the past. I’ve always said that 50% of the work is making the film, and the other 50% is marketing it. Without a strategic distribution plan, your film is likely to flop. As we look at the industry today, brands are cutting marketing budgets and these types of one-story-telling films are often the first to go. If there isn’t a direct result in sales it’s hard to quantify the impact these types of projects have.", "podcast_length": "56:00"}, {"id": "1f4fd768-48c7-476f-b6bb-4142d8d7ad10", "episode_id": "1fe39ccf-fc9c-4d58-a297-b44f0d5bab00", "cms_item_id": "68225dfc7bb476527f8c491a", "chunk_index": 17, "content": "Cole Heilborn (40:33.038): But what was so cool is that there is, when you bring these films in person, these stories in person to a community, and you almost spoon feed it to them, you'd be surprised the amount of connection and empathy. But it's really, if you just put it out on Dickie's Instagram, are you ever going to reach that audience? Probably not. So I think those are conversations that people bring back to their dinner table and can actually help change, again, how we see, how we engage with the world. So it makes it more human in my perspective. Is it possible for a film today to be uploaded to YouTube or Vimeo and take off? Or are the odds of that happening one or two percent? I think it's becoming less and less likely for films to just have overt success if you just drop them on YouTube or Vimeo with no sort of funnel, user funnel. I think you really do need to create. more of a targeted rollout and strategy. And do you think that's the filmmaker's job? Is that someone else's job? No, it should be. No, independent filmmakers should be focused on making the best film, the best story possible. It is the brand's internal marketing team. It's their job to come up with some of those strategies and solutions. But what I'm seeing is folks are just strapped. So I personally and they're under a lot of pressure. So I personally, as a filmmaker, I am so invested in the success of my films and wanting them to impact people in the way that I envision and I know they have the potential to impact. So I will take it upon myself to create a robust distribution strategy and proposal, not because the client necessarily asked for it, but because I want to try to meet them wherever they are and help fill the gaps because I want the story to do well too, just as my brand partner does. Potentially even more so because I am emotionally invested and I do connect with a subject matter of these stories I'm telling. So if there's potential for me to, you know, take some time and on my own time outside of work, like apply to some festivals or, you know, submit for an award or an educational distribution partnership, I will because I believe in the work I'm doing and I'm very convicted in the stories that I like proactively take on and take out to network. And unfortunately,", "token_estimate": 575, "speakers": ["Cole Heilborn"], "start_timestamp": "40:33.038", "end_timestamp": "40:33.038", "podcast_index": 145, "episode_name": "EP: 145 The Golden Age of Branded Films is Dead | Lindsey Hagen | gnarlybay", "slug": "ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "web_url": "https://www.portsidepro.com/podcast-feed/ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "guest_name": "Lindsey Hagen", "guest_title": "Head of Development at Gnarlybay", "categories": ["creative", "brand"], "short_description": "Simply uploading a video to YouTube and expecting hundreds of thousands of people to watch are days of the past. I’ve always said that 50% of the work is making the film, and the other 50% is marketing it. Without a strategic distribution plan, your film is likely to flop. As we look at the industry today, brands are cutting marketing budgets and these types of one-story-telling films are often the first to go. If there isn’t a direct result in sales it’s hard to quantify the impact these types of projects have.", "podcast_length": "56:00"}, {"id": "0828e35a-28d3-4722-85b2-7510d7fa67cd", "episode_id": "1fe39ccf-fc9c-4d58-a297-b44f0d5bab00", "cms_item_id": "68225dfc7bb476527f8c491a", "chunk_index": 18, "content": "Cole Heilborn (42:57.646): the chances of you getting hired again for a second film if the first film doesn't perform is minimal. Yes, then that's the unfortunate thing. As a filmmaker, typically your hire is just one small piece of the project and that's just making the thing. So if there isn't a comprehensive marketing strategy or distribution plan, it could reflect poorly on you as a filmmaker, like you didn't do your job. when in reality, maybe you weren't getting the full picture, you weren't given the opportunity to show how this piece could shine. So I'm always looking for areas where I can go one step further and offer solutions when it comes to distribution strategy. You guys just recently did a piece with Cannondale, and I think it's a great example of how you've kind of taken everything we've talked about and actually put it into practice. Could you share that project with us and kind of the effects of it, the ripple effect? Sure. So that's a great example. Cannondale at the time, their marketing director in the road category, his name is Colin Keveney, he and I formed just a friendship first and foremost. So, you know, I never try to reach out to brands with like an overt pitch or sale unless I know it's really timely and like directly connected with their needs. But he and I connected during COVID and just got to know each other first and foremost, just kind of checking in every few months. And... You know, he knew that I was just stepping into directing. He knew that I was really excited about impact related storytelling. He knew I had a background in adaptive sports before I ever got into film, sales or marketing. I was an adaptive sports instructor across climbing, skiing, wheelchair basketball. And so because I had that personal relationship with the brand, because bringing it back to my past note, we're all human behind our titles on LinkedIn. You know, when he had a product launch that, that he really coveted, it was a big product launch for him to manage. Um, he came to me, I think he knew he could trust my creative direction, my ability to manage a team. He knew I wanted to direct and he knew that in my free time, I like biking. So he came to me with the launch of, um, one of their new bikes at the time called the top stone. And he wanted to do a commercial that featured three different athletes on the product.", "token_estimate": 594, "speakers": ["Cole Heilborn"], "start_timestamp": "42:57.646", "end_timestamp": "42:57.646", "podcast_index": 145, "episode_name": "EP: 145 The Golden Age of Branded Films is Dead | Lindsey Hagen | gnarlybay", "slug": "ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "web_url": "https://www.portsidepro.com/podcast-feed/ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "guest_name": "Lindsey Hagen", "guest_title": "Head of Development at Gnarlybay", "categories": ["creative", "brand"], "short_description": "Simply uploading a video to YouTube and expecting hundreds of thousands of people to watch are days of the past. I’ve always said that 50% of the work is making the film, and the other 50% is marketing it. Without a strategic distribution plan, your film is likely to flop. As we look at the industry today, brands are cutting marketing budgets and these types of one-story-telling films are often the first to go. If there isn’t a direct result in sales it’s hard to quantify the impact these types of projects have.", "podcast_length": "56:00"}, {"id": "921528f8-b10f-4b7c-8dbb-810f4c6fca6d", "episode_id": "1fe39ccf-fc9c-4d58-a297-b44f0d5bab00", "cms_item_id": "68225dfc7bb476527f8c491a", "chunk_index": 19, "content": "Cole Heilborn (45:16.59): riding the bike through various different terrains, but he wanted each athlete to have a story component. So we created this commercial asset featuring three different athletes, three different disciplines, very different walks of life and expertise in their own right. We created the commercial asset. That was a project I directed. So it was a huge risk that he took. He'd never worked with me as a director. And he really threw me a bone in that respect. The product launch did well and when they want, again, talk about the user experience, when they launched the bike, they pushed it out through Paydots, spends on social, drove traffic to their landing page where the point of sale lived, and on that landing page that's where the commercial lived as well. After we made that piece, we started talking further about, okay, we featured these three athletes that are affiliated with Cannondale. Are there any stories within these athletes? lives or backgrounds that we could highlight through a short doc. Since they're already existing in this commercial, let's create some brand recognition and let's go one step further. So what we started to do is actually piece out if we were to feature all three of these athletes, what would their film look like? So we started with Meg Fisher, who's an amazing para cyclist, Olympian, a Paralympian cyclist. And, you know, Colin had been speaking with her. She's one of the athletes we featured in the commercial. And given my background in adaptive sports, he's like, I think you need to talk to Meg. She's doing some really cool mentorship work within the para cycling community, especially in her hometown of Missoula, Montana. And she's working with a little boy named Jack and he's not a little boy. He's actually 15 now, but she's working with a young athlete named Jack and she's doing a lot of advocacy work around para inclusion within the gravel, gravel cycling space. and I think you should hop on a call with her. So he was kind of like planting the seed, the story seed in my mind. So the next step for me is getting on a call, getting to understand her backstory, what her mentorship relationship looked like with Jack. It turns out she was a family friend of Jack's. He's a recent cancer survivor, so he had an amputation below the knee.", "token_estimate": 581, "speakers": ["Cole Heilborn"], "start_timestamp": "45:16.59", "end_timestamp": "45:16.59", "podcast_index": 145, "episode_name": "EP: 145 The Golden Age of Branded Films is Dead | Lindsey Hagen | gnarlybay", "slug": "ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "web_url": "https://www.portsidepro.com/podcast-feed/ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "guest_name": "Lindsey Hagen", "guest_title": "Head of Development at Gnarlybay", "categories": ["creative", "brand"], "short_description": "Simply uploading a video to YouTube and expecting hundreds of thousands of people to watch are days of the past. I’ve always said that 50% of the work is making the film, and the other 50% is marketing it. Without a strategic distribution plan, your film is likely to flop. As we look at the industry today, brands are cutting marketing budgets and these types of one-story-telling films are often the first to go. If there isn’t a direct result in sales it’s hard to quantify the impact these types of projects have.", "podcast_length": "56:00"}, {"id": "6719882c-9836-4ed6-a92f-06ca1b3f6ee2", "episode_id": "1fe39ccf-fc9c-4d58-a297-b44f0d5bab00", "cms_item_id": "68225dfc7bb476527f8c491a", "chunk_index": 20, "content": "Cole Heilborn (47:40.558): and was just getting into his professional cycling career. And she was coaching him through that career leading up to his first big gravel race. So we thought this was a really beautiful opportunity not only to feature the new Top Stone bike, which he would be racing the new one, Meg is already riding on that product. But we wanted to share a deeper story that could help progress the gravel community. So it really was like an ethos piece where where can we step up to the plate as cyclists? How can Cannondale help shepherd some of these conversations for inclusion and diversity within the gravel community? And really, Cannondale was so hands off in the sense that they allowed me as a director to really get down to the root of the story and let Meg and Jack lead that film. So it ended up being, I want to say like a 12 minute short doc. We had... more of like a commercialized teaser for the film that went out on social media. We partnered with Outride, which was a nonprofit partner. I think anytime you can bring in a nonprofit entity to some of these films, it is so worth it because that project's going to work that much harder for you and it's going to ultimately create impact. We ended up applying to... handful of festivals, I think we got into 11 festivals, we went on two global world tours with the film, through our nonprofit partnership with Outride, it played at 400 schools all over the US to help empower youth through cycling. We have 35 organic media placements. So when I talk about your film needs to be entertaining, beyond just the echo chamber of like the cycling industry, I think organic media placement speaks to that. We also partnered with Vio2 Media, who's a streaming platform and does all of the programming for Peloton. So we had a streamer partnership for this project. It played on all Peloton projects or all Peloton products all over the globe for six months. We had an exclusive six month window with Peloton. Vimeo, I think between Gnarly Bay and Cannondale got like 150 ,000 views, which for Vimeo these days is pretty good.", "token_estimate": 526, "speakers": ["Cole Heilborn"], "start_timestamp": "47:40.558", "end_timestamp": "47:40.558", "podcast_index": 145, "episode_name": "EP: 145 The Golden Age of Branded Films is Dead | Lindsey Hagen | gnarlybay", "slug": "ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "web_url": "https://www.portsidepro.com/podcast-feed/ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "guest_name": "Lindsey Hagen", "guest_title": "Head of Development at Gnarlybay", "categories": ["creative", "brand"], "short_description": "Simply uploading a video to YouTube and expecting hundreds of thousands of people to watch are days of the past. I’ve always said that 50% of the work is making the film, and the other 50% is marketing it. Without a strategic distribution plan, your film is likely to flop. As we look at the industry today, brands are cutting marketing budgets and these types of one-story-telling films are often the first to go. If there isn’t a direct result in sales it’s hard to quantify the impact these types of projects have.", "podcast_length": "56:00"}, {"id": "44999db4-b2a0-4239-b622-c96be72756c2", "episode_id": "1fe39ccf-fc9c-4d58-a297-b44f0d5bab00", "cms_item_id": "68225dfc7bb476527f8c491a", "chunk_index": 21, "content": "Cole Heilborn (50:00.622): And then we had about 200K engagement and views on social media. The film won Vimeo, best branded Vimeo award, ended up getting a gold Telly award and then went on to Sundance's branded storytelling forum. So yes, I would say that is an example of a film where we had the nonprofit partner, we had the organic media placement, we did the film festival. route to global tours, tons of awards, and impact. At the end of the day, there was so much impact that came from this film. I mean, it played at 400 schools all over the nation to empower young writers. And then Jack, the subject of the film, was able to speak through some of the doctors he worked with through his battle with cancer. He is now able to use that film as a tool to mentor other kids. who are faced with a similar diagnosis and procedure. So talk about this project as something that reverberates outside of the cycling industry, I would say it 100 % achieved that goal for us. And it was still tied to a timely moment, which was the product launch and this race, which was happening in real time. And it's all around policy change in the gravel cycling space. So it had some of those key factors that I think really make for a good timely entertaining brand film. Yeah, man, talk about impact. Like there's no way you'd be able to quantify the effect of that playing in 400 schools around the country. That's pretty amazing. When I went into this conversation with you, like it seemed kind of doomsday -esque. Like what we do is a passion for a living, like might not have much of a future. But then listening to you talk about a success story like that, where you've told a beautiful story and it actually has real impact, like it seems more positive. It sounds like what we need to do as filmmakers and as marketers. in order to have those, the impact that we hope for, we just need to put more work into what we're doing. Is that, is that what I'm hearing? Just be tenaciously convicted in whatever story you are telling. If you see potential outside of just making the film, like where can I go one step further as a storyteller? Even if the brand doesn't have the budget or they can't convince their internal marketing team, if you really care about the subject matter, it's worth going to bat for it.", "token_estimate": 576, "speakers": ["Cole Heilborn"], "start_timestamp": "50:00.622", "end_timestamp": "50:00.622", "podcast_index": 145, "episode_name": "EP: 145 The Golden Age of Branded Films is Dead | Lindsey Hagen | gnarlybay", "slug": "ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "web_url": "https://www.portsidepro.com/podcast-feed/ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "guest_name": "Lindsey Hagen", "guest_title": "Head of Development at Gnarlybay", "categories": ["creative", "brand"], "short_description": "Simply uploading a video to YouTube and expecting hundreds of thousands of people to watch are days of the past. I’ve always said that 50% of the work is making the film, and the other 50% is marketing it. Without a strategic distribution plan, your film is likely to flop. As we look at the industry today, brands are cutting marketing budgets and these types of one-story-telling films are often the first to go. If there isn’t a direct result in sales it’s hard to quantify the impact these types of projects have.", "podcast_length": "56:00"}, {"id": "20564f94-ee6b-4576-a890-03b02b0420e5", "episode_id": "1fe39ccf-fc9c-4d58-a297-b44f0d5bab00", "cms_item_id": "68225dfc7bb476527f8c491a", "chunk_index": 22, "content": "Cole Heilborn (52:22.094): And there's a way to do it very gracefully. And you can still support your brand partners even if they can't maybe justify the spend. I think we need to start pushing one step further as filmmakers, especially in the cause space because it's like you, if you're given access to that story, you should guard it and then use it to the best of your ability to do good. If you had to kind of wrap up our conversation and sum it up for folks, what do you hope they take away from this conversation? I love that. Tenaciously, what did you say? Tenaciously committed? That's a very descriptive. I feel like I've got a, I feel like I have a calling that I need to fulfill now. Yeah, I am, I don't know. I can be a little bit of a bulldog when I really care about something, but. It also kind of fuels me. So find what it is that fuels you and work towards it. And you're going to have all the energy you ever need. And if you don't have the marketing budget, I think you could probably still make it happen somehow. Just have to get creative. If you had to predict where things will continue to go, what do you feel like the role that branded films play in the future? What do you see? I think they are going to take on more of like a 360 campaign approach. So I would start thinking strategically about. your film looks like as a campaign. I'm hearing of streamers now being very open to branded content. I know, at least within the outdoor industry, REI has kind of broken into that space. So I would start, you know, making connections on that side of the entertainment world and streamers understand where those guardrails are. Maybe there's a scenario where a brand could fund your sizzle or your pilot. for your longer form project. And maybe they could get involved once you sell it to a streamer. So I think there's potential for the branded storytelling space to just continue expanding into the entertainment world with the right stories. And you have to be, you know, you have to find the partners who are willing to take that leap. But I think it is happening. And I'll be interested to see, because back in the day when I worked in print, you knew when something was funded by a brand because it was...", "token_estimate": 559, "speakers": ["Cole Heilborn"], "start_timestamp": "52:22.094", "end_timestamp": "52:22.094", "podcast_index": 145, "episode_name": "EP: 145 The Golden Age of Branded Films is Dead | Lindsey Hagen | gnarlybay", "slug": "ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "web_url": "https://www.portsidepro.com/podcast-feed/ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "guest_name": "Lindsey Hagen", "guest_title": "Head of Development at Gnarlybay", "categories": ["creative", "brand"], "short_description": "Simply uploading a video to YouTube and expecting hundreds of thousands of people to watch are days of the past. I’ve always said that 50% of the work is making the film, and the other 50% is marketing it. Without a strategic distribution plan, your film is likely to flop. As we look at the industry today, brands are cutting marketing budgets and these types of one-story-telling films are often the first to go. If there isn’t a direct result in sales it’s hard to quantify the impact these types of projects have.", "podcast_length": "56:00"}, {"id": "70a6bca7-fdc1-4134-a46b-e97e61e0c426", "episode_id": "1fe39ccf-fc9c-4d58-a297-b44f0d5bab00", "cms_item_id": "68225dfc7bb476527f8c491a", "chunk_index": 23, "content": "Cole Heilborn (54:45.422): designated as advertorial. I'll be interested to see in the entertainment world what will deem something as advertorial and where we will put in those guardrails from an entertainment perspective. I know product placement used to be pretty heavy handed and I think brands are starting to understand that that's not what needs to happen anymore. We have other assets that can focus more on product. But yeah, I'll be very interested to see streamers what the branded play continues to. evolve and look like years down the line. Fascinating. Lindsay, if folks want to connect with you or with Gnarly Bay, where can they go to find you? Lindsay at GnarlyBay .com is my email and I'm on Instagram. I lie on ZE3 or you can find me on LinkedIn. Beautiful. Well, Lindsay, thank you for taking the time to chat. It's been great to get to know you and get to have this conversation. I think it's a timely conversation because yeah, one, who doesn't want to make something that actually has a real impact. And I think that's what we all want to do. But I think, yeah, maybe we just need to dig a little deeper. Maybe we need to go a little further than the industry has been doing. So to this point. So thank you for sharing some of the things that you've been learning. I look forward to seeing what projects you work on in the future and seeing what sort of impact they have. Thank you, Paul. I appreciate it. Thanks for having me. Yeah, take care. Bye. Thank you for listening to this episode of the Backcountry Marketing Podcast. Please share it with a friend or leave us a review on Apple.", "token_estimate": 403, "speakers": ["Cole Heilborn"], "start_timestamp": "54:45.422", "end_timestamp": "54:45.422", "podcast_index": 145, "episode_name": "EP: 145 The Golden Age of Branded Films is Dead | Lindsey Hagen | gnarlybay", "slug": "ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "web_url": "https://www.portsidepro.com/podcast-feed/ep-145-the-golden-age-of-branded-films-is-dead-lindsey-hagen-gnarlybay", "guest_name": "Lindsey Hagen", "guest_title": "Head of Development at Gnarlybay", "categories": ["creative", "brand"], "short_description": "Simply uploading a video to YouTube and expecting hundreds of thousands of people to watch are days of the past. I’ve always said that 50% of the work is making the film, and the other 50% is marketing it. Without a strategic distribution plan, your film is likely to flop. As we look at the industry today, brands are cutting marketing budgets and these types of one-story-telling films are often the first to go. If there isn’t a direct result in sales it’s hard to quantify the impact these types of projects have.", "podcast_length": "56:00"}, {"id": "caa99365-e6ab-4466-b8e9-b035f6bdff10", "episode_id": "6bf5c62f-0f14-4c73-851c-658c59321d19", "cms_item_id": "68225dfc7bb476527f8c4916", "chunk_index": 0, "content": "Jordan Williams (00:00:00): Instead of assuming maybe the way it was a few years ago that you could just slap a few ads in front of them and get them to click is no longer true because one, you probably won't be able to target the people you want as well, and two, they're not going to click. And three, the cost of getting to those people has skyrocket. So again, the patient's virtue kicks in, which is instead of just trying to sort of rank a bunch of ads in front of people, how do you consistently and increasingly authentically show up in front of customers in a way that they feel good about?\n\nCole Heilborn (00:00:30): Welcome to the Backcountry Marketing Podcast. I'm your host Cole Heel Boy. On this podcast, you'll hear from leaders in the outdoor marketing industry discuss the gritty details of their work as well as the latest challenges and lessons they're learning along the way. If you want to hone your craft and become a stronger marketer, then this podcast is for you. This podcast is produced by Portside Productions, an outdoor film production company based in the Pacific Northwest. If you work at a brand or agency in the outdoor industry that needs help bringing a video project to life, head over to portside pro.com and send us an email we'd love to help. Welcome to the Backcountry Marketing podcast. Today I'm sitting down with Jordan Williams. He has held a variety of director of marketing roles in the industry since 2001. Jordan, you've been at REI, Yale Resorts, smart Wool and Red Bull over that time, quite the career, and I'm excited to have you on the show. Good to see you. I\n\nJordan Williams (00:01:21): Am thrilled to be here. Thanks for inviting me. Where are you calling in from? I am here in Sunny Boulder, Colorado. Yeah, lived here about a decade. You are buried in snow, yet? We are not. The funny El Nino forecast suggests that we in Boulder might end up getting more snow than some of the mountains in Colorado. Based on the southern trajectory of all that, we get those nice wraparound storms that come through the Southern Rockies. So we'll see. It's supposed to be a bit epic in town, but", "token_estimate": 535, "speakers": ["Jordan Williams", "Cole Heilborn"], "start_timestamp": "00:00:00", "end_timestamp": "00:01:21", "podcast_index": 154, "episode_name": "EP: 154 The Most Undervalued Tool in Marketing", "slug": "ep-154-the-most-undervalued-tool-in-marketing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-154-the-most-undervalued-tool-in-marketing", "guest_name": "Jordan Williams", "guest_title": "Marketing at Smartwool, Vail Resorts, REI and Redbull", "categories": ["industry-trends", "brand", "leadership-and-people"], "short_description": "According to Jordan Williams, patience is the most undervalued tool in marketing.", "podcast_length": "1:12"}, {"id": "9453e77f-fb57-4cc5-86a1-ae00933ed147", "episode_id": "6bf5c62f-0f14-4c73-851c-658c59321d19", "cms_item_id": "68225dfc7bb476527f8c4916", "chunk_index": 1, "content": "Cole Heilborn (00:01:52): Well, I'm excited for our conversation today, Jordan. It was a pleasure to connect with you earlier and just learn a little bit more about your history and some of your ideas and some of your perspective and kind of give folks an idea. We're going to be talking about patience. We're going to be talking about patience in a variety of respects, but we're going to be talking about playing the long game, the value of patients when it comes to marketing. And to kick us off, Jordan, I've got a question. As you look at the landscape today and as you consider patience amongst all of the change and disruption that is happening in the marketing world, why is this a virtue that you think is important? Can you kind of give us an opening statement for this conversation?", "token_estimate": 199, "speakers": ["Cole Heilborn"], "start_timestamp": "00:01:52", "end_timestamp": "00:01:52", "podcast_index": 154, "episode_name": "EP: 154 The Most Undervalued Tool in Marketing", "slug": "ep-154-the-most-undervalued-tool-in-marketing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-154-the-most-undervalued-tool-in-marketing", "guest_name": "Jordan Williams", "guest_title": "Marketing at Smartwool, Vail Resorts, REI and Redbull", "categories": ["industry-trends", "brand", "leadership-and-people"], "short_description": "According to Jordan Williams, patience is the most undervalued tool in marketing.", "podcast_length": "1:12"}, {"id": "d2f56438-4d4a-440c-ad0c-080bd0c1d78e", "episode_id": "6bf5c62f-0f14-4c73-851c-658c59321d19", "cms_item_id": "68225dfc7bb476527f8c4916", "chunk_index": 2, "content": "Jordan Williams (00:02:28): I think broadly my sense that patience as a virtue is really born out of this sense that the marketing industry, the advertising industry following the internet revolution went through a phase where there were truly radical changes in the landscape and there was an ability to target audiences in a way that had never occurred. And many of those persist and they're great tools in the toolkit, but I think the premise I have is sort of built off two ideas. One is the sort of digital marketing industrial complex was never as fantastic as the providers might have wanted us to believe to begin with. And two is I think in many ways the honeymoon is ending or has ended. Whether that is Apple introducing privacy controls and sort of privacy elements into iOS 14 a couple of years ago, whether it's just a broad consumer understanding of not wanting to be tracked and therefore sort of using tools especially for Apple that provide that or government overreach, which is sort of warming up concerns about TikTok and Chinese ownership and what's happening with data. (00:03:50): Certainly in Europe, there's a much stricter control set over the digital domain. California leads the way in the us. So all of that in various ways combines to the fact that I think we're at a point where absolutely digital tools are still the bedrock of what we're using to manage marketing and advertising and customer targeting and segmentation and all of that. But interestingly, there's a bunch of ways in which kind of old fashioned old school strategies and tactics are returning as really interesting ones to reach for brands because they're able to connect and reach audiences in a way that are meaningful or powerful and work in the evolving digital landscape.\n\nCole Heilborn (00:04:38): You said old school marketing tactics,\n\nJordan Williams (00:04:40): Old school marketing\n\nCole Heilborn (00:04:42): Immediately. I'm thinking of direct to mail and billboards.", "token_estimate": 495, "speakers": ["Jordan Williams", "Cole Heilborn"], "start_timestamp": "00:02:28", "end_timestamp": "00:04:42", "podcast_index": 154, "episode_name": "EP: 154 The Most Undervalued Tool in Marketing", "slug": "ep-154-the-most-undervalued-tool-in-marketing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-154-the-most-undervalued-tool-in-marketing", "guest_name": "Jordan Williams", "guest_title": "Marketing at Smartwool, Vail Resorts, REI and Redbull", "categories": ["industry-trends", "brand", "leadership-and-people"], "short_description": "According to Jordan Williams, patience is the most undervalued tool in marketing.", "podcast_length": "1:12"}, {"id": "191f6ead-fe71-4571-9023-19aa4a7c2389", "episode_id": "6bf5c62f-0f14-4c73-851c-658c59321d19", "cms_item_id": "68225dfc7bb476527f8c4916", "chunk_index": 3, "content": "Jordan Williams (00:04:45): Well, yeah, I mean the irony is the number of direct to consumer brands that have really built their businesses on things like catalog. You think about Steel Fairity, marine layer ri, where super smart digital first brands with amazing websites and digital user experiences, email segmentation, targeting, all that. However, investing a ton of money into direct mail and catalog and catalog is not a cheap date, but you're able to build an audience, build a customer base, get first purchase, then run retention tactics. And then on top of that, many of those same brands are moving into standalone brick and mortar retail, which if you really want to get into it as the oldest of old school tactics, and we've seen that across the board from the internet, pure plays of the Warby Parkers, Sonos I think is open retail. There's a bunch of different companies that are choosing to leverage what a really high cost, not only high cost, but you have to, if you're signing retail leases, you're signing three at best case, five to 10 year more likely in commercial settings. Catalog is a program that's probably not going to ROI for two probably three years at best. So a lot of these companies are leaning on tactics that not only are old school, but they really require a commitment. You can't just test it for a quarter, test it for a season and bail if it doesn't work, which again plays back into this sort of patience as a virtue premise that I've been pondering a lot of late.\n\nCole Heilborn (00:06:38): So let's pause and back up a little bit before we continue. You've been at REI Veil, smartwool, red Bull over your career. Can you kind of give us the brief highlight reel, the brief history?", "token_estimate": 432, "speakers": ["Jordan Williams", "Cole Heilborn"], "start_timestamp": "00:04:45", "end_timestamp": "00:06:38", "podcast_index": 154, "episode_name": "EP: 154 The Most Undervalued Tool in Marketing", "slug": "ep-154-the-most-undervalued-tool-in-marketing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-154-the-most-undervalued-tool-in-marketing", "guest_name": "Jordan Williams", "guest_title": "Marketing at Smartwool, Vail Resorts, REI and Redbull", "categories": ["industry-trends", "brand", "leadership-and-people"], "short_description": "According to Jordan Williams, patience is the most undervalued tool in marketing.", "podcast_length": "1:12"}, {"id": "02636d63-726f-4412-bc66-6f651ebd5910", "episode_id": "6bf5c62f-0f14-4c73-851c-658c59321d19", "cms_item_id": "68225dfc7bb476527f8c4916", "chunk_index": 4, "content": "Jordan Williams (00:06:50): The really short version is I actually have a degree in theater from n nyu. So I came out of school being trained as a director and I'm an art school kid, a creative kid it turns out, and I can take no credit for this. Training as a director was really helpful for marketing. You're basically, I'm trained in the conservatory practice of working with a bunch of specialists to tell stories in theater, you're working with actors, set designers, playwrights, et cetera. In marketing, you're working with copywriters, graphic designers, interaction designers, media planners, et cetera. So I came out of that, had an early part of my career doing corporate event marketing that led to Red Bull where I got to be a national event marketing manager there in the early days of Red Bull's existence in North America and got to do so much of the crazy wild Red Bull stuff. (00:07:47): Produced a wakeboard contest and a flooded lead mine underground in Missouri Paragliding and Skying event. Chicago got to be a part of the first two Red Bull Rampage events done in Virgin in Utah and then got to produce the first six Fluke Tog events, those crazy flying machine events they do, which I always argue was the most highly budgeted performance art on the planet. Met my now wife, we went and traveled for a little while, came back, got a job at REI ran their traditional marketing team, advertising, seasonal planning, all of the sort of long range planning to set up things like direct mail, retail marketing, new store openings, as well as a bunch of really cool sort of things in the portfolio. I are responsible for marketing Outdoor school, REI, adventures membership in the co-op, the REI Visa card program. If anybody would like to know about Visa card and loyalty program with let me know. (00:08:51): But that experience was fantastic. It was really like Red Bull was like getting an MBA in alternative Gorilla new school marketing and REI was very much about old school, traditional steady as she goes marketing. The most exciting thing I got to do at REI was, and this is going to start dating me when I was there, there was this super interesting thing happening in the landscape. This company out of Boston called Facebook was starting to become a thing that maybe brands might want to play with. There was this thing called Twitter that had started, YouTube was a thing, and so I pitched putting together a team. We ended up calling the digital engagement team and it was this small scrappy internal team that got to do a bunch of really fun stuff. We founded REI, social media practice, claimed all of those handles originally converted a lot of the long form written expert advice content they were doing and started adding YouTube elements to that. (00:09:54): But yeah, it was really fun. It was fun to get to work at REI in a way that was helping bring the co-op into the future from there. Got a job. My wife and I were interested in maybe moving from Seattle, so got a job as the director of marketing Keystone, one of Vail Resort's properties up in Summit County. We lived in Breck, had a great run there, amazing place to be able to live, helped rebrand platform, Keystone Resort and bring it back to a lot of its family roots and its focus on destination visitation. So got an opportunity to move down to Boulder and lead marketing and sales for Vail Resorts retail. From there, went to work for my wife. She's an incredibly talented interior designer. So we decided I would take a break from the corporate world, become the default parent and be the CEO of her interior design firm. And that led me to return to the corporate world where I was a global marketing director at Smart Wall for just under two years.", "token_estimate": 939, "speakers": ["Jordan Williams"], "start_timestamp": "00:06:50", "end_timestamp": "00:06:50", "podcast_index": 154, "episode_name": "EP: 154 The Most Undervalued Tool in Marketing", "slug": "ep-154-the-most-undervalued-tool-in-marketing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-154-the-most-undervalued-tool-in-marketing", "guest_name": "Jordan Williams", "guest_title": "Marketing at Smartwool, Vail Resorts, REI and Redbull", "categories": ["industry-trends", "brand", "leadership-and-people"], "short_description": "According to Jordan Williams, patience is the most undervalued tool in marketing.", "podcast_length": "1:12"}, {"id": "7e25f2b8-d99d-4ed5-8429-fd45bbe32c6b", "episode_id": "6bf5c62f-0f14-4c73-851c-658c59321d19", "cms_item_id": "68225dfc7bb476527f8c4916", "chunk_index": 5, "content": "Cole Heilborn (00:10:57): So you mentioned that you, during your time at REI, it was when Facebook and YouTube and Twitter and all these social platforms were starting and that kind of brought in this golden age of digital media. And I'm curious if you can kind of paint us the picture of from that point up until what iOS 14.5, there was this amazing period where there's a whole bunch of opportunity. Can you kind of describe what that looked like and then what changed? And there were a number of things that changed, but it seems like iOS 14 really was kind of the catalyst that prompted a lot of the change that we saw in the digital ad world.", "token_estimate": 162, "speakers": ["Cole Heilborn"], "start_timestamp": "00:10:57", "end_timestamp": "00:10:57", "podcast_index": 154, "episode_name": "EP: 154 The Most Undervalued Tool in Marketing", "slug": "ep-154-the-most-undervalued-tool-in-marketing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-154-the-most-undervalued-tool-in-marketing", "guest_name": "Jordan Williams", "guest_title": "Marketing at Smartwool, Vail Resorts, REI and Redbull", "categories": ["industry-trends", "brand", "leadership-and-people"], "short_description": "According to Jordan Williams, patience is the most undervalued tool in marketing.", "podcast_length": "1:12"}, {"id": "53167e9e-3601-4190-8294-20d5d7a03857", "episode_id": "6bf5c62f-0f14-4c73-851c-658c59321d19", "cms_item_id": "68225dfc7bb476527f8c4916", "chunk_index": 6, "content": "Jordan Williams (00:11:30): It was an amazing evolution to be a part of because I'll share this. When I was at RE, I was working with our in-house counsel, legal counsel because we were trying to figure out how do you do this? We were bringing online community features onto RE i.com for the first time outside of just product reviews, this wonderful woman, Jolene that I was working with in our council's office, we brought an outside counsel and I would sit in these meetings with these brilliant attorneys from Perkins QE with one of the leading now Silicon Valley tech firm, tech law firms on the planet and having conversations where attorneys were saying, there's no law for this, there's no case law, there's no precedent. We don't know how this works. Was sort of highlighting the fact that like, oh, this is really interesting terrain that no one at a brand level, at a corporate level has really played with. (00:12:28): And in fact, from a tool set, most of the platforms were not built for brand corporate users. Facebook obviously came from Harvard where it was this sort of social on campus network. Twitter was this microblogging platform that it spun out of, I think I'm remembering they were trying to build a podcasting platform at the time it was an offshoot of another business, but none of them had tools to allow brands to manage presences only individuals. So we spent a lot of time cluing together ways to do that. We were early movers on social media management tools. Food Suite had just launched when we were in the middle of this. So it was wild to go from sort of the very wild west beginning days where there was no precedence for how this should work. There wasn't ways in which they were planned for corporate. And then you move through that sort of golden age where clearly companies focused on revenue profitability, cottoned very quickly to the fact that oh, advertisers are where we're going to be gaining our revenue and therefore building everything we can to service them, whether it's social media managers, app brands, advertisers, advertising management integrations, and the third party platforms to allow audience targeting, data analytics, all that. (00:13:55): So there was this sort of golden era, this honeymoon where things got really sophisticated over the course of five years and that felt amazing. And I once in that period heard, I unfortunately not going to be able to cite who this was, but somebody coined the term trying to create customer experiences in the digital realm that were spooky, not creepy, which I think sort of is my title for that ethos, right? It's the how do you create a way where you're putting your message or your product or whatever you want to get in front of a customer in a way in which they subconsciously even think, wow, that's interesting. I was thinking about getting a new ski shell this winter, or I was thinking about taking a trip and funny, the keystone is now showing up rather than the creepy experience that I think we all urban myth or not have had of having a conversation about car insurance or something with a friend or your spouse. And suddenly you start seeing progressive ads on Instagram and you're like, Hey, Siri, is my microphone on? (00:15:14): So yeah, there was a moment where the ability to target was extraordinary. Additionally, what I'll offer is as a marketer, I experienced definitely some moral and ethical moments in the midst of this that were interesting, which is using Facebook as example. Now meta, there were moments where the ability to target audience facets that felt problematic at a societal level. There was moments when you could target by income, household, net worth, race, religion, like all of these things that I think we collectively have come to understand can be abused incredibly are largely corrosive to society. And we've seen largely by political advertisers were exploited significantly to drive problematic campaigns, I would argue. And then I think with the arrival and the advent of iOS 14, five, Google announcing the cookie list future and then postponing that kind of to this day, things started changing and there was sort of an awareness that we needed to start thinking more about first party data, zero party data, really how do we use the information that we as a brand or an entity might own about a customer and own in a way that that customer has explicitly said, you can have my email or you can have my cell phone for SMS. (00:16:49): I would like to hear from you really started emerging as the vital part of that customer relationship management rather than relying on ad platforms, social media platforms, et cetera. I would encourage everybody to Google if they want, there's an essay written called The End Ification of Platforms, and the premise is when many platforms start, whether that's social media, Amazon is another often used example in the early days, they are incredibly user-centric. It is awesome to be a user of them because everybody at that company is designing that platform to be as usable, friendly, awesome. It's improving all the time because the only thing they care about in the early stages based on how we typically are running and have run largely venture backed platforms in the marketing and ad and social media space, e-commerce space as well is in the early days all they care about is user growth, revenue and profit come later. (00:17:58): So part one of the story of the end notification platforms is early days it's awesome to be a user in the sort of middle of the story. They start having to strike a balance where like, hey, we need revenue. Revenue per user. Profitability is starting to become a requirement. Either we've matured, we've gone public, we need another round of funding where maybe people need more than just user growth. And so they hit this sweet spot where many of the platforms are really balancing ad placement, user experience, that sort of thing. And then the last stage as the author describes the end ification of these platforms, which I think we can all have our own experience with Amazon is the one that jumps to mind the most is the draw, the lure, the inescapable gravitational pull of milking as much money out of the platform you have built as possible becomes the inescapable force. (00:19:05): And what happens at that point is if you're meta, you start putting ads everywhere and you start getting more comfortable with ads all over Facebook, more ads in the feed, switching up an Instagram feed from being chronological to being sort of what you might be interested in, which is also an easier way to slip in a bunch of promotional stuff that might feel a little less intrusive if it weren't interrupting all of your friends. YouTube starts laying, you've got an ad below the video, overlaying the video at the end of the video. And Amazon I think is the one that most people might feel on a day to day, which is, it used to be you go to Amazon, you search for the thing you're looking for, you get really high quality results, you can filter by maybe customer review, you find what a great product pretty quickly. (00:20:00): And now you go to Amazon, you search for what you want and there might be sponsored promoted products on the majority of the first three plus pages. And the ability as a consumer to really know, did somebody buy this placements, did they not? And if you're selling on Amazon, you have to pay them advertising dollars at this point. There's this sort of mafia esque you have to pay to play if you're going to make it there. And ultimately the point of this is this journey, this sort of story arc to get back to the sort of Greek three part tale model is many of these platforms that we all loved are kind of falling apart in a way where we as users are increasingly unhappy using 'em. And I think there's going to be interesting days ahead because currently they're, so whether it's Google Meta, Amazon, et cetera are so massive and there's a whole other topic, antitrust enforcement in the US has had a fairly distinct perspective on what they should be enforcing. (00:21:16): There's been, I would argue, a really stifling of innovation in this digital space. I think that's going to change in the years to come. And I'm curious to see what comes next because I think once you start generating, especially as a public company, the level of revenue and reporting to Wall Street, you can't calls for Mark Zuckerberg to change the algorithm, to not promote engagement or rage. Engagement is never going to happen as a public company because that's how you get the clicks and the eyeballs. So that's sort of an addendum to I think the journey we've been on across the digital landscape.", "token_estimate": 2188, "speakers": ["Jordan Williams"], "start_timestamp": "00:11:30", "end_timestamp": "00:11:30", "podcast_index": 154, "episode_name": "EP: 154 The Most Undervalued Tool in Marketing", "slug": "ep-154-the-most-undervalued-tool-in-marketing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-154-the-most-undervalued-tool-in-marketing", "guest_name": "Jordan Williams", "guest_title": "Marketing at Smartwool, Vail Resorts, REI and Redbull", "categories": ["industry-trends", "brand", "leadership-and-people"], "short_description": "According to Jordan Williams, patience is the most undervalued tool in marketing.", "podcast_length": "1:12"}, {"id": "e7b8bb97-7b2b-4361-a6f3-4d6a54fa848f", "episode_id": "6bf5c62f-0f14-4c73-851c-658c59321d19", "cms_item_id": "68225dfc7bb476527f8c4916", "chunk_index": 7, "content": "Cole Heilborn (00:21:55): Well, it seems like it's ripe for disruption. It feels like the big platforms are slow, they're stagnant and they're bogged down and that's when something new usually pops up.\n\nJordan Williams (00:22:06): And I think in the downfall of Twitter, there's a bunch of these distributed microblogging platforms that are popping up that are, anybody can establish a server is sort of interesting. They're a little hard to use for the mainstream player. I do think there's a fundamental paradox at play, which is that what brands what we want is brand safety, which requires content moderation. And I think it's been proven at this point that content moderation at scale is arguably impossible to do right below that, at the very least, incredibly hard to do. And so that's where I think there will be an interesting is this one of those spaces where AI steps in. And so instead of hiring a bunch of humans who we unfortunately traumatized by having them weed out the horrific stuff that some of us as humans seem to want to post online, do we end up using AI to help weed out a lot of that, to get us back to a place where we can have shared spaces, shared communities that feel safe for us as brand marketers. But I agree, I think there's going to be a bunch of interesting stuff coming as some of these older platforms get disintermediated or if you're Elon Musk, just burn them down, which is a whole other topic.\n\nCole Heilborn (00:23:44): It's a whole other topic. Yeah. So 2021 iOS 14 and a half comes out, it throws a wrench into many businesses. Marketing efforts it throws a wrench into has significant loss for companies like Facebook. I think I read the following year they had a 10 billion loss as a direct result of iOS, 14 and a half digital ads seems very much like a short-term play. You're throwing an ad out there in the hope that someone clicks on it and buys a thing. I'm curious now, are we seeing a shift because of this, because of iOS 14 and a half? Are we seeing a shift towards more long-term marketing efforts now that we've had, what is it a couple of years to kind of enter into this post iOS 14 and a", "token_estimate": 538, "speakers": ["Cole Heilborn", "Jordan Williams"], "start_timestamp": "00:21:55", "end_timestamp": "00:23:44", "podcast_index": 154, "episode_name": "EP: 154 The Most Undervalued Tool in Marketing", "slug": "ep-154-the-most-undervalued-tool-in-marketing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-154-the-most-undervalued-tool-in-marketing", "guest_name": "Jordan Williams", "guest_title": "Marketing at Smartwool, Vail Resorts, REI and Redbull", "categories": ["industry-trends", "brand", "leadership-and-people"], "short_description": "According to Jordan Williams, patience is the most undervalued tool in marketing.", "podcast_length": "1:12"}, {"id": "d669f5ca-7d29-4fea-8a0c-70956c5952a5", "episode_id": "6bf5c62f-0f14-4c73-851c-658c59321d19", "cms_item_id": "68225dfc7bb476527f8c4916", "chunk_index": 8, "content": "Jordan Williams (00:24:27): Half? Yeah, I mean ultimately my take is I think the smart brands and the smart marketers are finding the right place and the right way to use different tools. Obviously we as marketers on a personal level might be offended or frustrated with the ills of meta. And there are a handful of brands that have said, we're leading Facebook, we're leaving Instagram for moral reasons, for ethical reasons. The catch 22, the sort of Hobbs and bargain that most brands are making is it's still an incredibly powerful platform to connect with consumers. Instagram specifically, YouTube specifically Google for sure. So I think it becomes about, if you think about whatever journey you're trying to create, whether that's capturing new consumers, increasing brand awareness, increasing loyalty, repeat purchase, whatever the goal you have is, I think what's starting to happen is there's a much more thoughtful way in which what are the tools and tactics we want to use at any given part of that journey? (00:25:54): And increasingly and understanding that a lot of the online advertising is really specifically or should be in a perfect world, really focused as much as possible on increasing brand awareness, getting traffic first visit to your site and then through the journey to first purchase. But once you get to first purchase by and large to the best of your ability, online advertising falls way down on the list of priorities for retaining that customer. At that point. It's email, it's SMS, it's direct mail, it's site personalization, it's a really innovative customer service on steel, just to give them a shout out, launched a program where they have an SMS marketing program that is run by actual humans, which is a funny thing to say in this day and age, but if you sign up for their SMS program, they have a human on their team, native English speaker, you're in the US who will drop you a text every once in a while and just say, Hey, do you need anything? Can I help answer any questions? And it is this sort of customer service esque version of marketing. They're trying to be helpful, how can I provide value to you? (00:27:18): So I think ultimately that's sort of the first part is how do you use these traditional marketing techniques to win customers and then really try and to the best of the ability set aside those tool sets. I also think in addition to that, there's never been a better time to be a storyteller and using long form content. Something that I really appreciated that Red Bull was in many ways a pioneer of which is what are ostensibly marketing vehicles, marketing tools that are authentically, not underhandedly, but authentically a value add for our target consumer. So if you think about Red Bull Rampage, if you're into mountain biking, watching Red Bull Rampage every year, super fun. You get to watch the most elite free ride mountain bikers on the planet, do stuff that is increasingly mind bending. (00:28:18): It is an entire Red Bull ad, but I happily watch because it is cool to, what I want it is of the things I want to do. If you're Black Crows or Marona and you are into free ride skiing, I'll watch anything Nico puts out on his sort of polestar driven Norwegian ski trips. It's amazing content. It's like these little, what used to be once a year when I was a kid going to the Warren Miller or TGR or Matchstick is now sort of he's putting out all the time and I'll eat it up. And in doing so, I have a positive sense of Black Grays, Marna Polestar, all of his brand partners. So there's ways in which storytelling and brand content as value add for consumers becomes a way in which you can increase brand awareness, increased loyalty, increased intent to purchase next time in many ways. (00:29:22): And so I think there's sort of multiple levels to, there's the tactical level about how you get to purchase, there's a bigger halo effort of how do you create brand and brand impression and brand awareness and brand loyalty. And then at the end of it, I think it's really about how are you creating authentically meaningful consumer experiences. So if I've shopped on your site before and I show up, especially if I'm logged in, how do you create a site that is personalized for me? You're showing me the stuff that I'm interested in and at a really high end sophisticated level at REI, they were just starting this, that many brands are doing this, brands are getting to personalized catalog where they're doing unique print per customer versions of catalogs where, hey, if you're like Cole, you've got a, you've an eight month old, so your catalog from REI or Backcountry could show you Burley cross country ski or Chariot products because it's like, hey, you've got a kid, you're going to be towing around for a little while, whether on the bike, on a run, on a cross country ski, let's show you that, but I've got an eight year or a 10-year-old and a 13-year-old, so show me small mountain bikes that kids might like or family ski products for teenagers. (00:30:52): Those are those sorts of things where brands mostly on a subconscious level to most consumers are creating like, Hey, we know you and we want to hopefully give you the version of us that you will be most interested in. Going back to that hopefully spooky, not creepy.", "token_estimate": 1330, "speakers": ["Jordan Williams"], "start_timestamp": "00:24:27", "end_timestamp": "00:24:27", "podcast_index": 154, "episode_name": "EP: 154 The Most Undervalued Tool in Marketing", "slug": "ep-154-the-most-undervalued-tool-in-marketing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-154-the-most-undervalued-tool-in-marketing", "guest_name": "Jordan Williams", "guest_title": "Marketing at Smartwool, Vail Resorts, REI and Redbull", "categories": ["industry-trends", "brand", "leadership-and-people"], "short_description": "According to Jordan Williams, patience is the most undervalued tool in marketing.", "podcast_length": "1:12"}, {"id": "9cc44624-3b1c-4bba-97df-60d53a0cee9d", "episode_id": "6bf5c62f-0f14-4c73-851c-658c59321d19", "cms_item_id": "68225dfc7bb476527f8c4916", "chunk_index": 9, "content": "Cole Heilborn (00:31:09): So you just outlined an entire marketing plan in about three minutes, which is it's fast to fascinating. I love the idea that storytelling is more relevant than ever. That's something that hits home for me that I believe there's a lot here. This is by no means a short-term game. This is a very long-term forward thinking plan. Is this all changed? Is this a more patient play than maybe things would've been five or 10 years ago in the golden age of digital ads?", "token_estimate": 123, "speakers": ["Cole Heilborn"], "start_timestamp": "00:31:09", "end_timestamp": "00:31:09", "podcast_index": 154, "episode_name": "EP: 154 The Most Undervalued Tool in Marketing", "slug": "ep-154-the-most-undervalued-tool-in-marketing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-154-the-most-undervalued-tool-in-marketing", "guest_name": "Jordan Williams", "guest_title": "Marketing at Smartwool, Vail Resorts, REI and Redbull", "categories": ["industry-trends", "brand", "leadership-and-people"], "short_description": "According to Jordan Williams, patience is the most undervalued tool in marketing.", "podcast_length": "1:12"}, {"id": "603031a6-7bd4-47a4-b229-e03228f04d56", "episode_id": "6bf5c62f-0f14-4c73-851c-658c59321d19", "cms_item_id": "68225dfc7bb476527f8c4916", "chunk_index": 10, "content": "Jordan Williams (00:31:41): Yeah, because I think the Yes, full stop. Yes, the sense I have, and again, this is all obviously I will copy out all this, this is my worldview, this is what I believe in, but it's what I've experienced and put to use at a bunch of different brands and it's works. It is a longer term play, it's a patient play because I think there was a period when I would sort of ascribe it to be this sort of period of peak growth hacker period where you could design a product, launch a site, crank out a site on Shopify, go in either yourself or hire a really smart campaign manager, do incredibly nuanced and sophisticated audience targeting, get your product in front of somebody and sell it and get revenue going. And certainly you can still do that to some degree, but there were whole companies that could sort of survive and thrive for some number of years in this sort of peak of this. I think that's increasingly hard. I think it's increasingly hard to differentiate that way. (00:32:56): One based on the change in the digital landscape that we've been talking about. Two, I also think attitudinally consumers are becoming more jaded. We're becoming a bit more advertising blind to a lot of that. We're willing to just sort of scroll by that in our feed or skip the ad. And so the requirement to tell stories, the requirement to build relationships with customers, the requirement to get somebody from not being aware of your brand, to aware of your brand, to willing to try your brand, product, service, whatever you offer for the first time, and then try and get them back into a second purchase. And a true relationship, especially in the outdoor industry for a lot of the products that most of the brands in the industry sell, meaning high cost, maybe seasonal use, because most of the industry is awesomely incorrectly focused on quality, sustainability, durability. A lot of the products that we as brands in the outdoor industry sell, you don't buy that often. Does the average skier snowboarder, how often are you buying hard goods? How often are you upgrading or swapping out your outerwear for an alpine season? (00:34:20): There are things that move faster, certainly at Smart Wool, if you're a runner, you're going through socks at a higher rate. What might work for skincare products or these sort of replenishable items where you're buying them once a month, et cetera. And I was at smartwool, think about if you have high quality marina wool, smartwool base layers, unless you are a crazy agro 150 day in them a year, most users are only buying those every many years. So all of that is background to say it's patient because not only does it take more time to get people into your brands, but if the repeat purchase cycle is longer, your ability to talk to consumers is longer. Your ability to build these relationships takes longer and therefore from a marketing strategy, the sort of storytelling and presence of mind that you have to persist over a longer period is even more important.", "token_estimate": 759, "speakers": ["Jordan Williams"], "start_timestamp": "00:31:41", "end_timestamp": "00:31:41", "podcast_index": 154, "episode_name": "EP: 154 The Most Undervalued Tool in Marketing", "slug": "ep-154-the-most-undervalued-tool-in-marketing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-154-the-most-undervalued-tool-in-marketing", "guest_name": "Jordan Williams", "guest_title": "Marketing at Smartwool, Vail Resorts, REI and Redbull", "categories": ["industry-trends", "brand", "leadership-and-people"], "short_description": "According to Jordan Williams, patience is the most undervalued tool in marketing.", "podcast_length": "1:12"}, {"id": "c1960705-53b2-4cde-ba99-77b396272f61", "episode_id": "6bf5c62f-0f14-4c73-851c-658c59321d19", "cms_item_id": "68225dfc7bb476527f8c4916", "chunk_index": 11, "content": "Cole Heilborn (00:35:24): So here's a follow up to that.\n\nJordan Williams (00:35:26): Yeah,\n\nCole Heilborn (00:35:26): So you're saying that essentially brands are playing a longer game, being more patient in building relationships with customers. I also think at the same time though, if you pulled the average American people would say, well, consumers and customers and society is just less patient these days. So it seems like we have these two different forces. Individuals are less patient, but brands are potentially, or in this example, are displaying more patients. Are those at odds with each other or do they work well together?", "token_estimate": 160, "speakers": ["Cole Heilborn", "Jordan Williams"], "start_timestamp": "00:35:24", "end_timestamp": "00:35:26", "podcast_index": 154, "episode_name": "EP: 154 The Most Undervalued Tool in Marketing", "slug": "ep-154-the-most-undervalued-tool-in-marketing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-154-the-most-undervalued-tool-in-marketing", "guest_name": "Jordan Williams", "guest_title": "Marketing at Smartwool, Vail Resorts, REI and Redbull", "categories": ["industry-trends", "brand", "leadership-and-people"], "short_description": "According to Jordan Williams, patience is the most undervalued tool in marketing.", "podcast_length": "1:12"}, {"id": "7994fe88-8f38-4df6-87f8-5f8b0ab24b55", "episode_id": "6bf5c62f-0f14-4c73-851c-658c59321d19", "cms_item_id": "68225dfc7bb476527f8c4916", "chunk_index": 12, "content": "Jordan Williams (00:36:00): That's a great question and it's a challenging one. I think I'll offer a couple of different answers and I'll completely own the fact that this first one is maybe my own optimism and sort of the hope that I'm clinging to in the modern world. I'll say I hope to frame it correctly, but I do see testament to this. I think consumers are coming to understand as we've moved through this crazy disruptive digital age where we suddenly have phones in our pocket that are available, supercomputers 24 hours a day content is ever present, the tiktoks of the world, the Tinders of the world where you can just whip through stuff. I believe we will have balancing forces that will self-regulate some of this behavior. I think we see some consumers and people, I'll stop talking about them as consumers. I think there are people, and I'm optimistic and increasing number of people and especially in the outdoor industry that are coming to understand this isn't the way we've been living, the way the world has been approaching. (00:37:16): This isn't necessarily that healthy. And I think you see different facets of this. I think you see a return, and some of this was accelerated by the pandemic, a return to slower interests, right? Sort of baking sourdough, the number of people I know that are knitting things. The number of people that are interested in picking up a hobby that has a certain craft component, whether it's home brewing or building stuff around the house, doing maintenance on their own equipment and understanding that a slower picking some moments of slowness in your life is really healthy. Getting outside. I had the joy of going on a week long backpacking trip down into the Grand Canyon a couple months ago, and the ability to get off the grid, no cell service, no phone, just the canyon, the river and the stars was a total gift and a reminder to me of the power that does. (00:38:25): I also think you see it in the way in which the industry and customers and consumers are embracing kind of old fashioned things. Wool. And I know I'm biased, I came from smart wool, but I think there was a period where we were all convinced that it's that line from the graduate plastics that polypro and all of that was going to be the future. And it turns out Marino wool, what PACA is doing here in Colorado with alpaca insulation, the knowledge that waxed cottons are actually an interesting material to use in a bunch of different settings. So a bit of a return to sort of what we would've thought of as old fashioned materials as part of this. So I think part one in long-winded answer your question is I think consumers are, and we as people are maybe going to self-regulate back to an understanding that slowness or periods of slowness in our lives are better. (00:39:26): I think at the core, your question persists though, which is there is a tension between in the digital landscape in that fast moving space, how do you get a potential customer's attention? But I would go back to patience, which is instead of assuming maybe the way it was a few years ago that you could just slap a few ads in front of them and get them to click is no longer true. Because one, you may not target, you probably won't be able to target the people you want as well. And two, they're not going to click. And three, the component we haven't talked about is the cost of getting to those people has skyrocketed. So as the Googles and alphabets and Metas of the world have become these revenue driving behemoths and net income driving behemoths public companies, they have to continue to generate that kind of income for their own success as a public company. (00:40:24): So the cost of connecting with consumers has continued to go up in these digital spaces. So again, the patience virtue kicks in, which is instead of just trying to sort of crank a bunch of ads in front of people, how do you consistently and increasingly authentically show up in front of customers in a way that they feel good about? How do you as a brand sponsor podcasts that they listen to? When we were at Smart Wall, there was a bunch of work we did with NPR actually to help raise brand awareness at a broad level. And NPR is interesting because you can't be promotional as it's a national public radio, but we found it an incredibly effective and increasingly cost effective way to get our brand out in a space that consumers felt good about and connect our brand with something they liked. So whether that's sponsoring athletes, doing content projects, sponsoring podcasts, sponsoring events, these ways in which that you can get your brand out there that take longer and are slower and are to track is still, I think the way in which you do it authentically, even in this really fast-paced world.", "token_estimate": 1200, "speakers": ["Jordan Williams"], "start_timestamp": "00:36:00", "end_timestamp": "00:36:00", "podcast_index": 154, "episode_name": "EP: 154 The Most Undervalued Tool in Marketing", "slug": "ep-154-the-most-undervalued-tool-in-marketing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-154-the-most-undervalued-tool-in-marketing", "guest_name": "Jordan Williams", "guest_title": "Marketing at Smartwool, Vail Resorts, REI and Redbull", "categories": ["industry-trends", "brand", "leadership-and-people"], "short_description": "According to Jordan Williams, patience is the most undervalued tool in marketing.", "podcast_length": "1:12"}, {"id": "1fee29da-1e91-4532-a782-43ab1a40eea1", "episode_id": "6bf5c62f-0f14-4c73-851c-658c59321d19", "cms_item_id": "68225dfc7bb476527f8c4916", "chunk_index": 13, "content": "Cole Heilborn (00:41:42): I don't remember I heard this, but I think it's a pretty common idea, this idea that there's so much content and so much stuff in the world that chances are we don't remember it, but of the things that we do remember, we only remember a tiny, tiny percentage of the stuff that we, because I think there's a stat out there that says, we see and consume like 10,000 ads a day, and how many of those do you remember? None of them. If you're a brand, how do you help people remember? How do you help people find you in the noise? And what I come back to and what you were referencing is this idea of storytelling. And for me, that's emotion. It's like how do you create a feeling and people remember feelings, people remember how they felt about something, and whether that's through a 62nd spot, a feature film, a really well-written article, a beautiful magazine article, that's the stuff that we remember. And so I wonder, and I think I hope as well that I think there's going to be this resurgence of trying to create feelings with the stuff that we do.", "token_estimate": 270, "speakers": ["Cole Heilborn"], "start_timestamp": "00:41:42", "end_timestamp": "00:41:42", "podcast_index": 154, "episode_name": "EP: 154 The Most Undervalued Tool in Marketing", "slug": "ep-154-the-most-undervalued-tool-in-marketing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-154-the-most-undervalued-tool-in-marketing", "guest_name": "Jordan Williams", "guest_title": "Marketing at Smartwool, Vail Resorts, REI and Redbull", "categories": ["industry-trends", "brand", "leadership-and-people"], "short_description": "According to Jordan Williams, patience is the most undervalued tool in marketing.", "podcast_length": "1:12"}, {"id": "88c23669-7a7e-4ef8-b6b2-d808d64a39fa", "episode_id": "6bf5c62f-0f14-4c73-851c-658c59321d19", "cms_item_id": "68225dfc7bb476527f8c4916", "chunk_index": 14, "content": "Jordan Williams (00:42:45): I couldn't agree more. I was having a conversation with somebody yesterday. This sounds like you and I synced up and agreed to hit this point, but it was honestly yesterday where they said, what's the one thing a brand should do? And I said, create a feeling. And to be clear, because I think it's worth expounding upon from my perspective when I say feeling is fundamentally, that's an emotional response we're trying to garner. Now, it could be an emotional response connected to your product that the feeling is if I use that product, I will be at Smart Wall more comfortable when I'm going and doing the things I want. It could be that I will rip harder on the slopes, I will ride on the trails like the pros. It could be product related, it could be societally related, right? I feel better about buying your product because the way in which this company is working in the world makes me feel better or more hopeful, whether that's they're operating in a way that makes me feel like my consuming this product is going to have less of a harmful impact, could be environmentally, I feel better about buying from this company because the way they treat their employees, the way in which they make say, outdoor spaces safer and more open to people that don't look like you and I, right? (00:44:29): Whether that's people of color, LGBTQ plus. (00:44:37): But a feeling nonetheless is I think what you're going for and a feeling in its most perfect form, I would argue, is you're creating a sense that your brand is a community, it's a tribe. And if you wear that brand, use those products, you are a member of that tribe. And I think the examples that come to mind are if you wear Patagonia, putting aside the sweater vested VC bros in Silicon Valley, but if you wear Patagonia, there's a feeling that many of us have that I ascribe to a certain worldview about how corporations should operate, and I'm willing to use my wallet to support that. It could be if you ski on Black Crows or wear their product, it's sort of like I'm a part of this sort of zany rad, a little bit off the edge sort of Euro crowd, this sort of all these crows with their personalities. (00:45:50): And I think it's about feeling like you're connecting to something bigger than you, whether that's performance related, impact related. And I think if you do that well, people end up having an understanding of your brand that they may not be able to articulate. Some of you may have seen this, Cole, you may have seen this, but I think it was Seth Goodin who said this recently, but he was using the example of the power of brand. And the example he used was, if I told you that Nike was going to be opening some hotels, I think any of us would immediately have our own sense of what that would be like. Now, our sense would be different, but all of us would probably have a pretty good idea about what a Nike hotel would look like. You're like, all right, it's going to have a rad fitness facility. It's going to be colorful, it's going to be sporty, it's going to be kind young, it's going to be in a cool neighborhood. And then poor Hyatt, the example you used was, if I told you Hyatt is launching a line of footwear, tell me what that's going to be like. And obviously the takeaway is you're like, I have no idea what shoes they would make because Hyatt is, I would argue a logo, but doesn't mean anything to any of us. (00:47:14): Whereas Nike means something to all of us because they've been brilliant at what they've been doing for so long. And obviously at this point they have all the talent in the world and all the money in the world to go do it. But I think that is sort of an interesting litmus test for an acid test for if your brand means something, if you introduce something outside of your category, would people have an idea about what that might be like? Yeah.", "token_estimate": 972, "speakers": ["Jordan Williams"], "start_timestamp": "00:42:45", "end_timestamp": "00:42:45", "podcast_index": 154, "episode_name": "EP: 154 The Most Undervalued Tool in Marketing", "slug": "ep-154-the-most-undervalued-tool-in-marketing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-154-the-most-undervalued-tool-in-marketing", "guest_name": "Jordan Williams", "guest_title": "Marketing at Smartwool, Vail Resorts, REI and Redbull", "categories": ["industry-trends", "brand", "leadership-and-people"], "short_description": "According to Jordan Williams, patience is the most undervalued tool in marketing.", "podcast_length": "1:12"}, {"id": "568e772d-69d4-450a-8754-5c86435904a9", "episode_id": "6bf5c62f-0f14-4c73-851c-658c59321d19", "cms_item_id": "68225dfc7bb476527f8c4916", "chunk_index": 15, "content": "Cole Heilborn (00:47:43): So you mentioned that brands are tribes, and I'm going to kind of give you a little bit of a roundabout story, but it's going to connect.\n\nJordan Williams (00:47:49): So\n\nCole Heilborn (00:47:50): I was talking to a buddy of mine, chase White, who's a photographer up in Squamish, and he was on the show a couple years ago, phenomenal photographer, great guy. And we were talking about what it's like to come off of a production and to reenter into let's say society, which is an exaggeration, but I was telling him we wrapped up this big shoot over the summer. We were gone for a couple of weeks, and I came home and I didn't feel at home. I felt slightly on edge. I felt a little anxious. I didn't feel like I missed being on set. I missed being in that environment where you're on all the time, you're with this close-knit group of collaborators. And there was something that I felt like I was lacking as I came home. Nothing against being home and my son and my wife, but so I was telling him about this, and he was saying, you should read this book called Tribes. (00:48:39): And it's sitting on my bookshelf behind me, and I can't remember the author, but the premise of the book is that back in the early days of America, there were 13 colonies. There was these events that were happening and that people were trying to explain. And what would be happening is that white people, western civilization, would find themselves migrating or merging and leaving civilization to go live with the natives, and the natives would never come the other direction and come live in a white colony. And the question was, why is this? Why are white people living with the natives, but the natives aren't coming to live with the white people, generally speaking? And the answer was, well, because they have something that we don't have in our culture and in our society, there's a literal tribe and it meets all of the requirements that people meet. (00:49:31): They feel like they belong, they feel like they matter, they feel like they have a meaning. And the book goes on to explain all these different circumstances and all these different examples throughout life where different events lead to this creation of a tribe. They talk about sporting events, they talk about combat and veterans, and this feeling of not belonging. And it made me realize that there's a piece of that that I feel when I'm out on a shoot and then I come back home, there's this disconnection between being in the zone and then coming back and having to readjust to regular life. But I think it all connects to what you're saying about brands or tribes, and you feel like you're a part of a tribe. And I think it's that feeling that's sometimes hard to explain and hard to quantify and figure out, what am I feeling? But you feel something.", "token_estimate": 709, "speakers": ["Cole Heilborn", "Jordan Williams"], "start_timestamp": "00:47:43", "end_timestamp": "00:47:50", "podcast_index": 154, "episode_name": "EP: 154 The Most Undervalued Tool in Marketing", "slug": "ep-154-the-most-undervalued-tool-in-marketing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-154-the-most-undervalued-tool-in-marketing", "guest_name": "Jordan Williams", "guest_title": "Marketing at Smartwool, Vail Resorts, REI and Redbull", "categories": ["industry-trends", "brand", "leadership-and-people"], "short_description": "According to Jordan Williams, patience is the most undervalued tool in marketing.", "podcast_length": "1:12"}, {"id": "289d5677-83b8-4683-acfd-763a143066b2", "episode_id": "6bf5c62f-0f14-4c73-851c-658c59321d19", "cms_item_id": "68225dfc7bb476527f8c4916", "chunk_index": 16, "content": "Jordan Williams (00:50:16): Yeah, I love that story. And I'll match one, like I said this earlier, our daughter's 13 turning 14 next month, and she's awesome. And I don't ascribe to all of the stereotypes that exist out there, fathers and daughters and teenagers and whatever, but some of it is very, very true. And my wife and I read this great book, I think it's called Untangled. I think I'm getting that right. But the author who's a childhood psychologist basically talks about the journey that teenagers are on, and especially middle school girls. And what she describes at a psychological level is our daughter and teenagers, middle schoolers, especially girls who I don't understand why there's patriarchy, because girls mature so much faster than USS boys. And the psychological experience that she describes is at this age, your child is needing to separate and disentangle from your family to form their own independence and form their own independent being. (00:51:23): But at a biological instinctual level, we understand as humans, homo sapiens, that there is safety in numbers. And so what they need to do is adopt a new tribe outside of the family. And so she was saying, Hey, if your teenage daughter, when they talk about their friends and their friend group and the drama in middle school, and it feels life and death to them, and you don't understand why, understand that psychologically it is at a base fundamental, psychological, biological level, it feels life and death to them because they have to lead the family, but they have to adopt this new tribe to stay safe. And so I think it's another example that you're hitting on that we as people understand consciously, but especially subconsciously, that belonging to things is important. And I think one of the things that's happening is we as a society, we as parents, we as individually are increasingly understanding that, and this is an entirely different podcast, the ways in which society has changed the last decades in the sort of sixties through now, say what you will about religion, but the decline in church participation, the decline in participation in civics organizations, rotary, Shriners, whatever. (00:52:55): We in many ways have retreated into these digital spaces that suggests that they're social, that suggests that they're online community, but actually aren't. And we are increasingly isolated and depressed and sad. Suicide rates, as we all know, are high. And I think the outdoor industry specifically has this amazingly powerful healing connecting role that many of us love. It's the ability to do the things we want to do. By and large, we enjoy doing them together. Many of the activities we need to do together for safety, right? Climbing, backcountry, skiing, kayaking, whatever it is, and the joy of doing it with other people, the ability to come back from a day on the hill, a river mission, whatever it is, and feel like I did that with my friends. (00:53:53): And therefore, there's this natural ability for brands to understand that connecting in with that and authentically doing things to support that. And I think that's where there are these interesting experiences I have as brand marketers, as a brand marketer, and I'll use some vague examples from Smart Wall, where as a marketer it was like, well, we should give money to a bunch of these different organizations. But as a public company, well, there's a difference between marketing dollars and nonprofit donations. And VF does a great job across both. This is not a denigration of them at all. But it is interesting where as an example, we as a marketing team would have these blurred moments of, well, is that a marketing spend or is that a nonprofit donation? Because we kind of view it as both or the same. And I say that just to illuminate the idea that as a marketer, the idea that that overlap could be a natural outcome of the work we were trying to accomplish. And an example of the way in which we're trying to create authentic connection, giving money to groups to get LGBTQ plus outside or supporting the plus size community to feel welcome in the outdoors or these wonderful things, long overdue that are happening in the industry at last. It's a blurry line between are you marketing, are you supporting? And the ultimate outcome is they're both. And that's a good thing. (00:55:31): So yeah, I think there is this tribal, this connection that we need as humans, which again, I think goes back to the through line we've been talking to, which is you can't create tribe, you can't create connection, you can't create community fast. I mean, when was the last time you outside of maybe being a kid or showing up at college or maybe with friends if you're having babies at the same time, there are only a few moments in life when we actually make friends really quickly. But outside of that, it takes a while to get to know people. And especially as adults, it takes, I would argue even longer. So that persistent consistent way in which brands should show up, I think goes back to this sort of patience as brand marketing virtue.", "token_estimate": 1279, "speakers": ["Jordan Williams"], "start_timestamp": "00:50:16", "end_timestamp": "00:50:16", "podcast_index": 154, "episode_name": "EP: 154 The Most Undervalued Tool in Marketing", "slug": "ep-154-the-most-undervalued-tool-in-marketing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-154-the-most-undervalued-tool-in-marketing", "guest_name": "Jordan Williams", "guest_title": "Marketing at Smartwool, Vail Resorts, REI and Redbull", "categories": ["industry-trends", "brand", "leadership-and-people"], "short_description": "According to Jordan Williams, patience is the most undervalued tool in marketing.", "podcast_length": "1:12"}, {"id": "55281efc-47a6-4ee2-91b3-7e94ea3f1264", "episode_id": "6bf5c62f-0f14-4c73-851c-658c59321d19", "cms_item_id": "68225dfc7bb476527f8c4916", "chunk_index": 17, "content": "Cole Heilborn (00:56:20): So if you had, let's give you a hypothetical scenario. Let's say you were working on a brand, you had unlimited money and you had an unlimited runway. You didn't have to prove a return on anything. And I know this isn't a real world example, but I'm curious, oh,\n\nJordan Williams (00:56:36): Please make it so I'd love this job. Anybody who's got that, go for it.\n\nCole Heilborn (00:56:41): What would you do in your most creative self? What would you do to create a tribe?", "token_estimate": 125, "speakers": ["Cole Heilborn", "Jordan Williams"], "start_timestamp": "00:56:20", "end_timestamp": "00:56:41", "podcast_index": 154, "episode_name": "EP: 154 The Most Undervalued Tool in Marketing", "slug": "ep-154-the-most-undervalued-tool-in-marketing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-154-the-most-undervalued-tool-in-marketing", "guest_name": "Jordan Williams", "guest_title": "Marketing at Smartwool, Vail Resorts, REI and Redbull", "categories": ["industry-trends", "brand", "leadership-and-people"], "short_description": "According to Jordan Williams, patience is the most undervalued tool in marketing.", "podcast_length": "1:12"}, {"id": "741074fe-6c22-42eb-8114-bda0878ed25c", "episode_id": "6bf5c62f-0f14-4c73-851c-658c59321d19", "cms_item_id": "68225dfc7bb476527f8c4916", "chunk_index": 18, "content": "Jordan Williams (00:56:51): Oh, man. I think the first element, I'll try answering it this way. I think the first element is you have to know what do you stand for in the world? What do you care about? Who do you want to be known as? Right? There's a brand establishing exercise, which there's a bunch of different versions you can play, but if you're a brand where somebody at a party, who would they be at the party? Are they the person who sits in the corner who likes to have really deep conversations? Are they the dj? Do they talk to everybody? If your brand was a music playlist, what kind of music would it be? But I think even more than that, what do you as a brand care about? Is there a community that you want to be a part of? Is there a purpose you have? (00:57:46): Because I think birthing your brand and the stories you want to tell out of a place that is true is the crux of all of this. We have the landscape is littered with brands where they have ginned up or hired consultants to do a marketplace SWOT analysis and have sort of come out with examples. I was looking at one on LinkedIn, is this yours? Somebody was highlighting, it was a Toyota ad a few years ago that had a forerunner, ostensibly pitching to the mountain bike community. Yeah, this might've been us, yeah, of credit due. And it was like the worst Walmart crappy bike with reflectors. I think it had a kickstand. The person was dressed in some combo of sort of a BMX racing outfit or a dh. I mean, everything was wrong. The forerunner wasn't dirty, it didn't have a bike rack. None of this was authentic. (00:58:52): And I think I also saw a Chevron ad the other day pitching how they were great environmental stewards, and you're like, why are you even trying this? And I drive a car still that needs petroleum. I fly on planes when I need to. I'm knocking oil writ large. So I think part one is who are you and where are you from? And then I think it's about what are the best ways in which that community point of connection can be made. And there's a whole bunch of examples. I don't have any brilliant revolutionary ideas, but there's a whole bunch of examples out there of people doing really interesting things. I was just up in Portland a month ago, and I went by the Snow Peak flagship out in the northwest, and they have Teki, which is a restaurant, and you're like, you're a camping brand. (00:59:48): Why do you have a restaurant? It's like, well, you can come have dinner basically at our store. And the way in which we prepare the food, the way in which we serve the food, the architecture of the restaurant that you sit in are ways in which we're sharing with you the thing that we care about as a brand gathering around fire, talk about tribals going way back. But sitting around a fire in the preparation of food and sharing that with others is a core expression of what they care about in the world as a brand. And so that crazy notion, if you reach back, there have been brands that have done this from a department store perspective, from age old, but the idea that an outdoor brand should open a restaurant, the Japanese outdoor brand should open a restaurant in Portland would be crazy talk. (01:00:43): But the fact that they're opening a restaurant, they're opening campgrounds, companies are offering adventure travel experiences, sort of guided adventure travel experiences under their brand. So I would lean into what are the most perfect ways in which you can share the essence of who you are as a brand. And within that, there's a business premise I've long held to, and this sounds snarky and it's not, but when you're sitting in a meeting in a brainstorm, and maybe the brainstorm is kind of run dry or maybe it gets a little tense, you don't feel like you're getting as far as you want, and someone, and I do this all the time, so this is pointing the finger back at me when someone throws out the idea that's so ridiculous. Mostly to get a laugh and break the tension. I would argue almost 10 times out of 10, that's the best idea that is thrown out in a meeting, that it's so ridiculous and over the top that everybody goes, oh yeah, that would be crazy. (01:01:52): You're like, yeah, now take that idea and maybe unpack it and strip it back to a place that's a little more real. But that idea is probably the best because it's coming from this maybe uncomfortable place that you had, but that may be the best idea you have. Right? And Red Bull basically built a brand of, think of the craziest possible thing you could do, and they would say yes to it. And it helps to be a privately owned entity that's owned and operated by one wildly high net worth individual, Dietrich Ma sheets, rest in peace. And so they had a corporate framework where saying yes to stuff was easy, really hard to do if you're a public company, harder to do if you're a public company. (01:02:45): But those crazy hair-brained ideas are often the best idea that people at the company have. So whether that's working with artists, creating experiences, because I think going back to the tribe and the example you raised of Colonial America, what those tribal experiences were, and again, I'm saying this as a cisgender straight white dude, I'll acknowledge all of that, but working as a community to where the act of feeding everyone is a communal act. The act of sustaining the community, whether that's hunting and gathering, whether that's farming, whether that's raising young, are these communal experiences, and therefore it makes all the sense to the world that, going back to by example, snow Peak is offering where you can dine together or you can go camping together, or brands are offering, Hey, you can come climbing with us, you can come skiing with us, I think are fundamental ways in which the non-traditional, the patient approach is coming to a fore. I dunno if that was a weak answer to year if you had all the money in the world, but that's a staunch question.", "token_estimate": 1494, "speakers": ["Jordan Williams"], "start_timestamp": "00:56:51", "end_timestamp": "00:56:51", "podcast_index": 154, "episode_name": "EP: 154 The Most Undervalued Tool in Marketing", "slug": "ep-154-the-most-undervalued-tool-in-marketing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-154-the-most-undervalued-tool-in-marketing", "guest_name": "Jordan Williams", "guest_title": "Marketing at Smartwool, Vail Resorts, REI and Redbull", "categories": ["industry-trends", "brand", "leadership-and-people"], "short_description": "According to Jordan Williams, patience is the most undervalued tool in marketing.", "podcast_length": "1:12"}, {"id": "df757a02-8dc8-4385-ac5b-8f9a46300050", "episode_id": "6bf5c62f-0f14-4c73-851c-658c59321d19", "cms_item_id": "68225dfc7bb476527f8c4916", "chunk_index": 19, "content": "Cole Heilborn (01:04:04): Well, like all questions, the answer is generally, it depends.\n\nJordan Williams (01:04:07): Yeah.\n\nCole Heilborn (01:04:09): Well, what I love what you said though, good ideas. I heard this recently. It's that hard work only takes you so far, and at some point you cross a threshold where it's no longer just about hard work. But now it becomes about hard work and good ideas, and it's the good ideas that take you to the next level. It's the great ideas that take you to the next level. And that's nots. Not a reason to say that you still don't have to work hard, but good ideas generally come from time. They come from space. They come from making space a priority so that you have time to actually think and brainstorm and come up with ideas. And that comes from, I think, the core virtue of patience, which is, it's okay if I'm not spending this next hour rushing to get something done, I'm going to take time to actually sit and think and come up with an idea. Because who knows how far that idea might take you in the long run. Sure, it's good to be productive for that hour, but if you use that hour brainstorming, you might get way further. If you give yourself that space", "token_estimate": 302, "speakers": ["Cole Heilborn", "Jordan Williams"], "start_timestamp": "01:04:04", "end_timestamp": "01:04:09", "podcast_index": 154, "episode_name": "EP: 154 The Most Undervalued Tool in Marketing", "slug": "ep-154-the-most-undervalued-tool-in-marketing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-154-the-most-undervalued-tool-in-marketing", "guest_name": "Jordan Williams", "guest_title": "Marketing at Smartwool, Vail Resorts, REI and Redbull", "categories": ["industry-trends", "brand", "leadership-and-people"], "short_description": "According to Jordan Williams, patience is the most undervalued tool in marketing.", "podcast_length": "1:12"}, {"id": "7624e77f-d847-4dce-b402-6e16f572b467", "episode_id": "6bf5c62f-0f14-4c73-851c-658c59321d19", "cms_item_id": "68225dfc7bb476527f8c4916", "chunk_index": 20, "content": "Jordan Williams (01:05:12): Or even more, and you're a creative, the advice of go nothing. Stop thinking about this problem. Go for a walk, go take a shower. Actually get your brain completely off of this. And what we know and has been proven psychologically is your brain is working in the background subconsciously on finding an answer. And often it could be when you're doing the thing that is not directly related to that problem solving act is when you actually get the answer. But I think there's something about our puritanical, Calvinistic, American must be productive. Pull yourself up by your bootstraps. Accomplish, accomplish, accomplish brain ethos approach to the world means that if you're not actively working on something, you're lazy, you're not doing hard work, as opposed to what we actually understand is true, which is if you're trying to solve a problem, do some research, do the brainstorm, think about it, and then actually don't think about it, go do almost anything else. (01:06:25): And in doing anything else and kind of ignoring it actively is a win. Certainly in the creative field, the artistic field, this is true. But I would also argue at its core, any facet of business is creative. I don't care if you're a merchant, a buyer in finance, we all have problems to solve in the way we work in the world. And those solutions come to us often when we take a break, whether that's formally meditating or truly, I'm going to go cook soup for an hour and just think about not burning the onions and the miis and I'm going to make some soup. But that might be the moment when your brain actually unpacks the answer that you were looking for.\n\nCole Heilborn (01:07:10): Well, Jordan, we're running out of time for today, but if you had to wrap it up for us, we talked about a lot, but there's this through line of patience. If you could leave our audience with any final thoughts, what would you want to leave 'em with?", "token_estimate": 487, "speakers": ["Jordan Williams", "Cole Heilborn"], "start_timestamp": "01:05:12", "end_timestamp": "01:07:10", "podcast_index": 154, "episode_name": "EP: 154 The Most Undervalued Tool in Marketing", "slug": "ep-154-the-most-undervalued-tool-in-marketing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-154-the-most-undervalued-tool-in-marketing", "guest_name": "Jordan Williams", "guest_title": "Marketing at Smartwool, Vail Resorts, REI and Redbull", "categories": ["industry-trends", "brand", "leadership-and-people"], "short_description": "According to Jordan Williams, patience is the most undervalued tool in marketing.", "podcast_length": "1:12"}, {"id": "77785d23-4a66-42ed-8c48-cd390f16dab4", "episode_id": "6bf5c62f-0f14-4c73-851c-658c59321d19", "cms_item_id": "68225dfc7bb476527f8c4916", "chunk_index": 21, "content": "Jordan Williams (01:07:25): I think the final thought I would offer is maybe an acknowledgement of reality, which is if you're a marketer, if you're a brand leader, you have requirements, you have bosses, you have goals, you have revenue to drive. You have, if you're at a public company, a quarter to hit. So everything I've talked about today is, comes with the caveat and a deep and empathetic understanding, a reality eyelid as well, that this is really hard balance and it's a hard pitch sometimes when you want to go get the budget approved for the thing that's harder or if you want to take a nonconventional approach. And so the final thought I'd offer is use data, use budgetary arguments, use case studies to unpack the fact that doing the easy and obvious what you have been doing may not be ROI the way you want it to, or may not be cost effective in the months or years to come. And instead, investing in a great customer data warehouse where you can store customer data safely and have zero and first party data and build an amazing email program is a better spend than giving meta another big check. (01:08:53): Investing money in, not influencers, I would argue, which is a whole nother thing in the sort of shallow influencer kind of way, but instead actually creating relationships with people in the community you would love to communicate with and connect with and help them achieve what they want to. Again, going back to Red Bull, we would often work with athletes and just say, what would you do if you could build an event? What would you want the event to be? And that's what we would end up doing, which is why the events were often as meaningful and cool for that community. But I know and want to offer, this is a hard road to host sometimes. It is a tough argument to win. It's tough money to get out of the budget. So to the best of your ability, do the hard work to create a business driven, empirical driven when possible data framed argument about why this is the right thing to do, or at least the right thing to test because it can easily come across of you just want to do the cool fluffy thing. (01:10:02): I want to go make a movie. I want to sponsor this cool event so I can go to Jackson in February. And you're like, well, no, there's actual financially driven, long-term smart strategy. And I would argue the hard work coming up with ideas and figuring out cool stuff to do is in many ways not the hard work. That's the fun work. It's the work that's sort of around us all the time, but the hard work is how do you actually connect it back to the bottom line and win the arguments it takes to do it.", "token_estimate": 661, "speakers": ["Jordan Williams"], "start_timestamp": "01:07:25", "end_timestamp": "01:07:25", "podcast_index": 154, "episode_name": "EP: 154 The Most Undervalued Tool in Marketing", "slug": "ep-154-the-most-undervalued-tool-in-marketing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-154-the-most-undervalued-tool-in-marketing", "guest_name": "Jordan Williams", "guest_title": "Marketing at Smartwool, Vail Resorts, REI and Redbull", "categories": ["industry-trends", "brand", "leadership-and-people"], "short_description": "According to Jordan Williams, patience is the most undervalued tool in marketing.", "podcast_length": "1:12"}, {"id": "c9dabafe-fdfd-4e1a-a76e-a79c9baa0c88", "episode_id": "6bf5c62f-0f14-4c73-851c-658c59321d19", "cms_item_id": "68225dfc7bb476527f8c4916", "chunk_index": 22, "content": "Cole Heilborn (01:10:33): Amazing. Well, Jordan, I really appreciate this conversation. If folks want to connect with you, where can they find you?\n\nJordan Williams (01:10:39): Yeah, I would say LinkedIn is great. You can find me on LinkedIn, connect with me there, send me ees. Happy to chat with anybody. And yeah, that's probably the easiest and fastest way to get to me in this setting.\n\nCole Heilborn (01:10:52): Awesome. Well, thank you very much. I enjoyed this conversation. I think we've got some potential topics to circle back on and do a part two and a part three now, psychology,\n\nJordan Williams (01:11:01): Tribalism and Humanity podcast coming to you soon.\n\nCole Heilborn (01:11:04): Well, and I think we need to talk about restaurant integrations.\n\nJordan Williams (01:11:08): That sounds, yes. Dining and lodging as a brand extension for sure.\n\nCole Heilborn (01:11:14): Alright, well, Jordan, I hope you have a great rest of your day.\n\nJordan Williams (01:11:16): Hey, cool. Thanks so much. This was awesome.\n\nCole Heilborn (01:11:18): See you. Thank you for listening to this episode of the Backcountry Marketing Podcast. Please share it with a friend or leave us a review on Apple.", "token_estimate": 301, "speakers": ["Cole Heilborn", "Jordan Williams"], "start_timestamp": "01:10:33", "end_timestamp": "01:11:18", "podcast_index": 154, "episode_name": "EP: 154 The Most Undervalued Tool in Marketing", "slug": "ep-154-the-most-undervalued-tool-in-marketing", "web_url": "https://www.portsidepro.com/podcast-feed/ep-154-the-most-undervalued-tool-in-marketing", "guest_name": "Jordan Williams", "guest_title": "Marketing at Smartwool, Vail Resorts, REI and Redbull", "categories": ["industry-trends", "brand", "leadership-and-people"], "short_description": "According to Jordan Williams, patience is the most undervalued tool in marketing.", "podcast_length": "1:12"}, {"id": "9f8bcc13-20c8-4513-ae9b-22a980bfda3d", "episode_id": "a393c459-812a-4229-a992-085feac0876e", "cms_item_id": "68225dfc7bb476527f8c491b", "chunk_index": 0, "content": "Lindsay Rogers (00:00:00): This is the Red Bull model of we're going to bring you in, we're going to wash you off, clean you up, and we're only going to put you on the roster if you are bootying over and over again. As soon as you stop performing, you're out. So that I feel like that model is slowly being retired because it's really hard to connect to as a human. So I think brands really need to look at the humanity behind these athletes and what are they doing that's creative and interesting, and not just climbing Everest, not just doing that big peak.\n\nCole Heilborn (00:00:31): Welcome to the Backcountry Marketing podcast. I'm your host Cole Heel boy. On this podcast, you'll hear from leaders in the outdoor marketing industry discuss the gritty details of their work as well as the latest challenges and lessons they're learning along the way. If you want to hone your craft and become a stronger marketer, then this podcast is for you. This podcast is produced by Portside Productions, an outdoor film production company based in the Pacific Northwest. If you work at a brand or agency in the outdoor industry that needs help bringing a video project to life, head over to portside pro.com and send us an email we'd love to help. Welcome to the Backcountry Marketing podcast. My name is Cole Hilborn. Today I'm sitting down with Lindsay Rogers, founder of Raw Strategy. Raw Strategy works with high level athletes and leaders throughout the outdoor industry to work on positioning and messaging. They also work with the Olympic and Paralympic teams, as well as some of the North Face athletes on positioning. Lindsay, welcome to the show.\n\nLindsay Rogers (00:01:25): Thanks so much for having me.\n\nCole Heilborn (00:01:26): Thanks for being here. I love this idea of positioning and messaging for athletes. I don't feel like this is something that I've ever really considered. Positioning is a big topic in the business agency creative world, but how cool is it that you get to do this with athletes?", "token_estimate": 504, "speakers": ["Lindsay Rogers", "Cole Heilborn"], "start_timestamp": "00:00:00", "end_timestamp": "00:01:26", "podcast_index": 157, "episode_name": "EP: 157 Beyond the Podium - Have We Setup Athletes to Fail?", "slug": "beyond-the-podium---have-we-setup-athletes-to-fail", "web_url": "https://www.portsidepro.com/podcast-feed/beyond-the-podium---have-we-setup-athletes-to-fail", "guest_name": "Lindsay Yaw Rogers", "guest_title": "Founder of Raw Strategy", "categories": ["leadership-and-people"], "short_description": "The outdoor industry has no shortage of objective-based films. Year after year we see brands pumping out countless stories of physical feats and athletic prowess. These narratives, often breathtaking and awe-inspiring, have become the backbone of how outdoor brands communicate with their audience. But at the heart of these stories, there's a critical element we might be overlooking: the human experience.", "podcast_length": "1:06"}, {"id": "4ea0460d-dea9-4137-8ffe-40bedad1da2c", "episode_id": "a393c459-812a-4229-a992-085feac0876e", "cms_item_id": "68225dfc7bb476527f8c491b", "chunk_index": 1, "content": "Lindsay Rogers (00:01:41): I do feel kind of lucky. Yeah, I mean, it was interesting. I was an athlete for a long time, and then I left to become a freelance writer and then work on the brand side. And I did start to notice that there were all these athletes in all sorts of different parts of the outdoor industry who were working with brands, but none of us and none of them really knew how to kind of talk about yourself, what to talk about in terms of your own personal story, and then if you had a message, what was it? How do you talk about it? How do you communicate it? How do you align it with the brands that you're supposed to be paid from, et cetera. So that's why I kind of created that initial program called The Raw Athlete, is to help give those athletes what they need to actually be prepared to communicate their value to those brands and connect to the brands in that way. (00:02:30): So it's not a skillset that I think you're supposed to have as an athlete, right? You're sort of focused for on doing what you do well. So we found that a lot of brands are really excited about the fact that we are coming in and saying, Hey, we're going to give them this skill, and it's also going to help you. It's going to benefit you as a brand. So yeah, it's been exciting and I love working with athletes. Their job is so personal to them, it's what they're ultimately passionate about, and that's what I absolutely love.\n\nCole Heilborn (00:03:00): So today we're going to be talking about athletes and ambassadors and just some of the changes and trends that are happening in the industry. You've obviously got a front row seat to a lot of this, and I think we hear rumors about athlete teams changing things, evolving. It seems like programs are really being put through the wringer in some cases, and I'm excited to sit down with you and dissect what our athlete programs look like today. What makes a successful team and how can brands better equip their teams to be better athletes and advocate for brands? I'd love if you could give us an opening statement. I guess why is this a topic that you're passionate about?", "token_estimate": 533, "speakers": ["Lindsay Rogers", "Cole Heilborn"], "start_timestamp": "00:01:41", "end_timestamp": "00:03:00", "podcast_index": 157, "episode_name": "EP: 157 Beyond the Podium - Have We Setup Athletes to Fail?", "slug": "beyond-the-podium---have-we-setup-athletes-to-fail", "web_url": "https://www.portsidepro.com/podcast-feed/beyond-the-podium---have-we-setup-athletes-to-fail", "guest_name": "Lindsay Yaw Rogers", "guest_title": "Founder of Raw Strategy", "categories": ["leadership-and-people"], "short_description": "The outdoor industry has no shortage of objective-based films. Year after year we see brands pumping out countless stories of physical feats and athletic prowess. These narratives, often breathtaking and awe-inspiring, have become the backbone of how outdoor brands communicate with their audience. But at the heart of these stories, there's a critical element we might be overlooking: the human experience.", "podcast_length": "1:06"}]
